INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('aquatic-life-institute','Aquatic Life Institute','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["ALI"],"categories":["advocacy-campaigns","policy-law","welfare-science","movement-infrastructure"],"species":["farmed-fish","wild-fish","crustaceans","cephalopods"],"regions":["global"],"countries":["US","FR"],"interventions":["certification-standards","corporate-campaigns","legislation-policy","research","capacity-building"],"approach":"welfare-reform","summary":"Works on the welfare of farmed and wild-caught aquatic animals worldwide by engaging seafood certification schemes, companies and policymakers, publishing research reports and benchmarks, and leading the Aquatic Animal Alliance coalition.","website":"https://www.ali.fish/","hq":"United States","founded":"2019","sources":[{"url":"https://www.ali.fish/about","title":"About us — Aquatic Life Institute","accessed":"2026-11-05","published":null},{"url":"https://animalcharityevaluators.org/charity-review/aquatic-life-institute/","title":"Aquatic Life Institute — Animal Charity Evaluators review","accessed":"2026-11-05","published":null}],"notes":"aquaticlifeinstitute.org redirects to ali.fish. HQ (US), French subsidiary and founding year 2019 are from the ACE review. ACE-recommended charity (2024).","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('aquatic-animal-alliance','Aquatic Animal Alliance','network','aquatic-life-institute','movement-infrastructure','aquatic','active','{"aliases":["AAA"],"categories":["movement-infrastructure","advocacy-campaigns","policy-law"],"species":["farmed-fish","wild-fish","crustaceans","cephalopods"],"regions":["global"],"countries":[],"interventions":["capacity-building","legislation-policy","producer-engagement","public-awareness","research"],"approach":"welfare-reform","summary":"Coalition of advocacy organisations created by Aquatic Life Institute in 2020 to improve the welfare of aquatic animals in the food system through industry engagement, policy advocacy, public education and research; its blog features member campaigns worldwide.","website":"https://aquaticanimalalliance.org/","hq":null,"founded":"2020","sources":[{"url":"https://aquaticanimalalliance.org/","title":"Aquatic Animal Alliance — home","accessed":"2026-11-05","published":null},{"url":"https://animalcharityevaluators.org/charity-review/aquatic-life-institute/","title":"Aquatic Life Institute — Animal Charity Evaluators review","accessed":"2026-11-05","published":null}],"notes":"ACE review cites 180+ member organisations in over 75 countries (figure as reported by ACE, 2025).","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('fish-welfare-initiative','Fish Welfare Initiative','organisation',NULL,'welfare-science','aquatic','active','{"aliases":["FWI"],"categories":["welfare-science","advocacy-campaigns","funding"],"species":["farmed-fish"],"regions":["south-asia","east-asia"],"countries":["IN","CN"],"interventions":["farm-practices","producer-engagement","research","humane-slaughter","grantmaking"],"approach":"welfare-reform","summary":"Works to improve the welfare of farmed fishes, currently mainly in India through its Alliance for Responsible Aquaculture farm programme and field research (feed, slaughter, lice detection), and collaborates with stakeholders in China.","website":"https://www.fishwelfareinitiative.org/","hq":"United States","founded":"2019","sources":[{"url":"https://www.fishwelfareinitiative.org/","title":"Improving Farmed Fish Welfare | Fish Welfare Initiative","accessed":"2026-11-05","published":null},{"url":"https://www.fishwelfareinitiative.org/transparency","title":"Transparency — Fish Welfare Initiative","accessed":"2026-11-05","published":null},{"url":"https://www.fishwelfareinitiative.org/china","title":"Fish Welfare in China | Fish Welfare Initiative","accessed":"2026-11-05","published":null},{"url":"https://animalcharityevaluators.org/charity-review/fish-welfare-initiative/","title":"Fish Welfare Initiative — Animal Charity Evaluators review","accessed":"2026-11-05","published":null}],"notes":"''hq'' reflects registration as a US 501(c)(3) (EIN 85-2065536); field operations are in India. Founding year 2019 per ACE. Site navigation also lists The Philippines; a Sept 2026 post describes operations in India and China and is scoping expansion to another country. Launched through Ambitious Impact/Charity Entrepreneurship (per AIM site).","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('fwi-alliance-for-responsible-aquaculture','Alliance for Responsible Aquaculture','programme','fish-welfare-initiative','welfare-science','aquatic','active','{"aliases":["ARA"],"categories":["welfare-science"],"species":["farmed-fish"],"regions":["south-asia"],"countries":["IN"],"interventions":["farm-practices","producer-engagement","data-tools"],"approach":"welfare-reform","summary":"Fish Welfare Initiative''s core farm programme in Andhra Pradesh, India: staff measure water quality (e.g. dissolved oxygen) at enrolled ponds and recommend corrective actions to farmers when readings fall outside set ranges.","website":"https://www.fishwelfareinitiative.org/","hq":"India","founded":null,"sources":[{"url":"https://www.fishwelfareinitiative.org/post/rfp-india","title":"Open Call: Funding New Ideas to Improve the Welfare of Farmed Fishes in India","accessed":"2026-11-05","published":"2026-10-06"},{"url":"https://www.fishwelfareinitiative.org/post/data-issues","title":"Data Issues and Retraction in Our Farm Program","accessed":"2026-11-05","published":"2026-10-21"}],"notes":"Operating regions named as Eluru (138 farms) and Nellore (46 farms) in the Oct 2026 post; FWI retracted two years of Nellore data after detecting data fabrication.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('shrimp-welfare-project','Shrimp Welfare Project','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["SWP"],"categories":["advocacy-campaigns","welfare-technology","welfare-science"],"species":["crustaceans"],"regions":["global","south-asia","southeast-asia","latin-america","africa","europe"],"countries":["GB","VN","HN","IN","ID","EC","LK","VE","TH","NG"],"interventions":["humane-slaughter","corporate-campaigns","producer-engagement","farm-practices","research"],"approach":"welfare-reform","summary":"Works with shrimp producers, seafood suppliers and retailers to improve farmed shrimp welfare, chiefly by providing electrical stunners for pre-slaughter stunning, helping retailers adopt shrimp welfare policies (e.g. on eyestalk ablation), farmer engagement in India and research.","website":"https://www.shrimpwelfareproject.org/","hq":"United Kingdom","founded":"2021","sources":[{"url":"https://www.shrimpwelfareproject.org/","title":"Shrimp Welfare Project — home","accessed":"2026-11-05","published":null},{"url":"https://www.shrimpwelfareproject.org/shrimpact","title":"(Shr)Impact — Shrimp Welfare Project","accessed":"2026-11-05","published":null},{"url":"https://animalcharityevaluators.org/charity-review/shrimp-welfare-project/","title":"Shrimp Welfare Project — Animal Charity Evaluators review","accessed":"2026-11-05","published":null},{"url":"https://rethinkpriorities.org/impact-area/uncovering-neglected-issues-advancing-shrimp-welfare/","title":"Uncovering neglected issues: advancing shrimp welfare — Rethink Priorities","accessed":"2026-11-05","published":null}],"notes":"Registered charity in the UK (no. 1204414). Founded 2021 per ACE; incubated by Charity Entrepreneurship (Ambitious Impact). Countries are those listed for stunner impact on the (Shr)Impact page. ACE Recommended Charity 2023-2025.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('swp-humane-slaughter-initiative','Humane Slaughter Initiative','programme','shrimp-welfare-project','welfare-technology','aquatic','active','{"aliases":["HSI (SWP)"],"categories":["welfare-technology","advocacy-campaigns"],"species":["crustaceans"],"regions":["southeast-asia","south-asia","latin-america","africa"],"countries":["VN","HN","IN","ID","EC","LK","VE","TH","NG"],"interventions":["humane-slaughter","producer-engagement"],"approach":"welfare-reform","summary":"Shrimp Welfare Project programme that provides electrical stunners to aquaculture producers at minimal or no cost; SWP reports 37 corporate stunner agreements across 9 countries, of which 20 stunners were installed and commissioned at time of access.","website":"https://www.shrimpwelfareproject.org/humane-slaughter-initiative","hq":null,"founded":null,"sources":[{"url":"https://www.shrimpwelfareproject.org/shrimpact","title":"(Shr)Impact — Shrimp Welfare Project","accessed":"2026-11-05","published":null},{"url":"https://www.shrimpwelfareproject.org/","title":"Shrimp Welfare Project — home","accessed":"2026-11-05","published":null}],"notes":"Not to be confused with Humane Society International (also abbreviated HSI). Agreement/stunner counts are SWP''s own figures and change over time.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('crustacean-compassion','Crustacean Compassion','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":[],"categories":["advocacy-campaigns","policy-law"],"species":["crustaceans","cephalopods"],"regions":["uk"],"countries":["GB"],"interventions":["legislation-policy","corporate-campaigns","public-awareness","research"],"approach":"welfare-reform","summary":"UK charity campaigning for legal protection and humane treatment of decapod crustaceans (e.g. crabs, lobsters), including bans on boiling alive and live sales, protections in science, supermarket scorecards and a code of practice; recently also campaigns on cephalopods.","website":"https://www.crustaceancompassion.org/","hq":"United Kingdom","founded":"2016","sources":[{"url":"https://www.crustaceancompassion.org/","title":"Crustacean Compassion | UK Animal Welfare Organisation","accessed":"2026-11-05","published":null},{"url":"https://www.crustaceancompassion.org/single-post/a-decade-of-decapod-protection-celebrating-10-years-of-crustacean-compassion","title":"A decade of decapod protection: Celebrating 10 years of Crustacean Compassion","accessed":"2026-11-05","published":"2026-06-10"}],"notes":"Registered charity in England and Wales (no. 1215720). Founding year inferred from a June 2026 post marking its tenth anniversary (began as a volunteer campaign). Some pages returned a bot check (HTTP 429) on repeat requests.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('fishcount','fishcount.org.uk','resource',NULL,'welfare-science','aquatic','active','{"aliases":["Fishcount"],"categories":["welfare-science","movement-infrastructure"],"species":["wild-fish","farmed-fish","crustaceans"],"regions":["global"],"countries":[],"interventions":["data-tools","research","humane-slaughter"],"approach":"research","summary":"Website on reducing fish suffering in commercial fishing and fish farming; publishes estimates of numbers of fishes killed (e.g. 1.1-2.2 trillion wild fishes caught annually 2000-2019; ~124 billion farmed fishes killed in 2019) and reports on capture and humane slaughter.","website":"https://fishcount.org.uk/","hq":null,"founded":null,"sources":[{"url":"https://fishcount.org.uk/","title":"fishcount.org.uk — home","accessed":"2026-11-05","published":null}],"notes":"curl returned HTTP 403; content read via WebFetch. The page does not name an operating organisation (copyright ''fishcount.org.uk 2010-2025''). Estimates are reported as published in the journal Animal Welfare. Site lists new pages on a humane fish slaughter policy roadmap and farmed invertebrate estimates.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('fair-fish-international','fair-fish international','organisation',NULL,'welfare-science','aquatic','active','{"aliases":["fair-fish"],"categories":["welfare-science","advocacy-campaigns","policy-law"],"species":["farmed-fish","wild-fish"],"regions":["europe","global"],"countries":["CH"],"interventions":["research","certification-standards","public-awareness","producer-engagement","legislation-policy"],"approach":"welfare-reform","summary":"Association founded in Switzerland in 2000 working on the welfare of fishes in fisheries and aquaculture through research (the fair-fish database), public awareness, policy work and advice to industry, including fish welfare criteria for the Friend of the Sea label.","website":"https://fair-fish.net/","hq":"Switzerland","founded":"2000","sources":[{"url":"https://fair-fish.net/page/T27/our-vision-and-mission","title":"fair-fish - Our Vision and Mission","accessed":"2026-11-05","published":null},{"url":"https://fair-fish.net/page/VOl/carefishfarm","title":"fair-fish - Carefish/farm","accessed":"2026-11-05","published":null}],"notes":"No RSS feed found (/feed/ returned 404). Runs Carefish/farm (since 2017) and Carefish/catch projects.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('fair-fish-database','fair-fish database','resource','fair-fish-international','welfare-science','aquatic','active','{"aliases":["FishEthoBase"],"categories":["welfare-science","movement-infrastructure"],"species":["farmed-fish","wild-fish"],"regions":["global"],"countries":[],"interventions":["data-tools","research"],"approach":"research","summary":"Open database compiling scientific knowledge on the welfare of aquatic species in aquaculture (''farm'' branch) and fisheries (''catch'' branch), assigning each species a WelfareScore based on 10 criteria for minimal and best-possible conditions.","website":"https://fair-fish.net/page/1DB/fair-fish-database","hq":null,"founded":null,"sources":[{"url":"https://fair-fish.net/page/1DB/fair-fish-database","title":"fair-fish database","accessed":"2026-11-05","published":null},{"url":"https://friendofthesea.org/fos-and-fair-fish-awarded-open-philantropy-project-grant-to-boost-fish-welfare/","title":"FoS and fair-fish awarded Open Philanthropy Project grant to boost Fish Welfare","accessed":"2026-11-05","published":"2018-01-16"}],"notes":"fishethobase.net did not respond (connection failure/503). The 2018 FOS page refers to ''the FishEthoBase research team of fair-fish international''; that the current ''fair-fish database'' is the renamed FishEthoBase is inferred, not stated on the fetched page.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('eurogroup-for-animals','Eurogroup for Animals','organisation',NULL,'policy-law','aquatic','active','{"aliases":[],"categories":["policy-law","movement-infrastructure","advocacy-campaigns"],"species":["farmed-fish","wild-fish","crustaceans","cephalopods","all-animals","farmed-animals","wild-animals","companion-animals","fur-animals"],"regions":["europe"],"countries":["BE"],"interventions":["legislation-policy","research","capacity-building"],"approach":"welfare-reform","summary":"Pan-European animal advocacy umbrella organisation; its Aquatic Animals policy area pushes for EU welfare rules for farmed and wild-caught fish, crustaceans and cephalopods (including at slaughter) and opposes octopus farming, publishing white papers and factsheets.","website":"https://www.eurogroupforanimals.org/","hq":"Belgium","founded":"1980","sources":[{"url":"https://www.eurogroupforanimals.org/what-we-do/policy-areas/aquatic-animals","title":"Aquatic Animals | Eurogroup for Animals","accessed":"2026-11-05","published":null},{"url":"https://www.eurogroupforanimals.org/who-we-are","title":"Who we are | Eurogroup for Animals","accessed":"2026-11-05","published":null},{"url":"https://en.wikipedia.org/wiki/Eurogroup_for_Animals","title":"Eurogroup for Animals - Wikipedia","accessed":"2026-11-05","published":null}],"notes":"Feed covers all Eurogroup news, not only aquatic. Address: Brussels.","merged_from":["eurogroup-for-animals"]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('compassion-in-world-farming','Compassion in World Farming','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["CIWF"],"categories":["advocacy-campaigns","policy-law"],"species":["farmed-fish","cephalopods","farmed-animals","chickens","pigs","cows"],"regions":["europe","global","uk"],"countries":["GB"],"interventions":["legislation-policy","corporate-campaigns","public-awareness","research"],"approach":"welfare-reform","summary":"International farm animal welfare organisation; aquatic work includes EU policy advocacy on farmed fish welfare and opposition to octopus farming, including joint work with Eurogroup for Animals on Nueva Pescanova''s proposed Canary Islands octopus farm.","website":"https://www.ciwf.org.uk/","hq":"United Kingdom","founded":"1967","sources":[{"url":"https://www.eurogroupforanimals.org/library/exposing-environmental-risks-octopus-farming","title":"Exposing the environmental risks of octopus farming (Eurogroup for Animals / CIWF case study)","accessed":"2026-11-05","published":"2024-07-12"},{"url":"https://www.eurogroupforanimals.org/news/eu-vision-2040-step-towards-protection-aquatic-animals","title":"EU Vision 2040: a step towards protection for aquatic animals","accessed":"2026-11-05","published":"2026-10-21"},{"url":"https://en.wikipedia.org/wiki/Compassion_in_World_Farming","title":"Compassion in World Farming - Wikipedia","accessed":"2026-11-05","published":null}],"notes":"All CIWF domains tried (ciwf.org.uk, ciwf.org, ciwf.eu, ciwf.com) returned HTTP 429 (Vercel security checkpoint), so CIWF''s own pages, HQ and feeds could not be verified. Facts here come from Eurogroup pages, which quote a CIWF Aquaculture Policy Officer. | ciwf.org and ciwf.org.uk returned HTTP 429 (Vercel security checkpoint) during research; facts taken from Wikipedia (founded 1967, Godalming, England). Feed not checked. Country office list not verified.","merged_from":["compassion-in-world-farming"]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('albert-schweitzer','Albert Schweitzer Foundation','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["Albert Schweitzer Stiftung für unsere Mitwelt"],"categories":["advocacy-campaigns","policy-law"],"species":["farmed-fish","crustaceans","farmed-animals","chickens"],"regions":["europe"],"countries":["DE"],"interventions":["corporate-campaigns","certification-standards","legislation-policy"],"approach":"welfare-reform","summary":"Berlin-based foundation working against factory farming; since 2016 it has worked on aquaculture welfare, including the Aquaculture Welfare Standards Initiative with retailers, scientists, authorities and certifiers.","website":"https://albertschweitzerfoundation.org/","hq":"Germany","founded":"2000","sources":[{"url":"https://albertschweitzerfoundation.org/campaigns/aquaculture-welfare-standards-initiative","title":"Aquaculture Welfare Standards Initiative • Albert Schweitzer Foundation","accessed":"2026-11-05","published":null},{"url":"https://albertschweitzerfoundation.org/news/the-albert-schweitzer-foundation-celebrates-25-years","title":"The Albert Schweitzer Foundation celebrates 25 years","accessed":"2026-11-05","published":null},{"url":"https://albertschweitzerfoundation.org/","title":"Albert Schweitzer Foundation","accessed":"2026-11-05","published":null},{"url":"https://albertschweitzerfoundation.org/about-us","title":"About us - Albert Schweitzer Foundation","accessed":"2026-11-05","published":null}],"notes":"No RSS feed found. | Berlin address on site; site references corporate outreach and politics work. Founding year not verified. No feed found.","merged_from":["albert-schweitzer"]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('aquaculture-welfare-standards-initiative','Aquaculture Welfare Standards Initiative','programme','albert-schweitzer','advocacy-campaigns','aquatic','active','{"aliases":["AWSI"],"categories":["advocacy-campaigns","welfare-science"],"species":["farmed-fish"],"regions":["europe","global"],"countries":["DE"],"interventions":["certification-standards","corporate-campaigns","humane-slaughter","farm-practices"],"approach":"welfare-reform","summary":"Multi-stakeholder initiative (industry incl. major supermarkets, science, authorities, certifiers) that issues aquaculture welfare recommendations on water quality, handling, feeding, transport and stunning, and seeks uptake via certification schemes such as ASC and GGN.","website":"https://albertschweitzerfoundation.org/campaigns/aquaculture-welfare-standards-initiative","hq":"Germany","founded":null,"sources":[{"url":"https://albertschweitzerfoundation.org/campaigns/aquaculture-welfare-standards-initiative","title":"Aquaculture Welfare Standards Initiative • Albert Schweitzer Foundation","accessed":"2026-11-05","published":null}],"notes":null,"merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('animal-equality','Animal Equality','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["Animal Equality UK","Igualdad Animal","Animal Equality India","Animal Equality Italia"],"categories":["advocacy-campaigns","policy-law","community-media"],"species":["farmed-fish","wild-fish","farmed-animals","pigs","cows","chickens"],"regions":["global","europe","north-america","latin-america","uk","south-asia"],"countries":["US","MX","BR","DE","IT","ES","IN","GB"],"interventions":["investigations","corporate-campaigns","legislation-policy","litigation","public-awareness"],"approach":"mixed","summary":"International farmed animal protection organisation running investigations, corporate, legal and public campaigns; its fish work highlights the absence of legal slaughter protections in fish farming and fishing, and Animal Equality UK has campaigned on Scottish farmed fish.","website":"https://animalequality.org/","hq":"United States","founded":"2006","sources":[{"url":"https://animalequality.org/issues/fish/","title":"The fish industry: Cruelty on a massive scale — Animal Equality","accessed":"2026-11-05","published":null},{"url":"https://thehumaneleague.org.uk/article/parliamentary-reception-shines-a-light-on-forgotten-fishes","title":"Parliamentary reception shines a light on forgotten fishes — The Humane League UK","accessed":"2026-11-05","published":"2025-01-22"},{"url":"https://animalequality.org/","title":"Animal Equality | Protecting animals worldwide","accessed":"2026-11-05","published":null},{"url":"https://animalequality.org/who-we-are/","title":"Who we are - Animal Equality","accessed":"2026-11-05","published":null},{"url":"https://igualdadanimal.org/quienes-somos/","title":"Quiénes somos - Igualdad Animal","accessed":"2026-11-05","published":null}],"notes":"Fish is one of several issue areas, not the main focus. Operates country sites (homepage says it works in 15 countries); US entity is a 501(c)(3). Feeds are global-site feeds covering all topics. | HQ listed as Los Angeles on the who-we-are page; organisation originated in Spain (2006). Spanish-language site igualdadanimal.org has its own feed.","merged_from":["animal-equality"]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('humane-league-uk','The Humane League UK','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["THL UK"],"categories":["advocacy-campaigns","policy-law"],"species":["farmed-fish","chickens"],"regions":["uk"],"countries":["GB"],"interventions":["legislation-policy","corporate-campaigns","public-awareness"],"approach":"welfare-reform","summary":"UK charity campaigning on farmed animal welfare; its fish work calls for species-specific legislation requiring pre-slaughter stunning of farmed fish and has included parliamentary events in the Scottish Parliament.","website":"https://thehumaneleague.org.uk/","hq":"United Kingdom","founded":null,"sources":[{"url":"https://thehumaneleague.org.uk/article/parliamentary-reception-shines-a-light-on-forgotten-fishes","title":"Parliamentary reception shines a light on forgotten fishes — The Humane League UK","accessed":"2026-11-05","published":"2025-01-22"},{"url":"https://thehumaneleague.org.uk/our-campaigns","title":"Live Campaigns — The Humane League UK","accessed":"2026-11-05","published":null}],"notes":"Registered charity no. 1177926. Its live campaigns page (accessed) lists chicken welfare, not fish, as the current live campaign. No RSS feed found (/feed 404).","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('mercy-for-animals','Mercy For Animals','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["MFA"],"categories":["advocacy-campaigns","community-media"],"species":["farmed-fish","crustaceans","cephalopods","farmed-animals","chickens","pigs"],"regions":["north-america","latin-america","south-asia","southeast-asia","global"],"countries":["US","CA","BR","IN","MY"],"interventions":["corporate-campaigns","public-awareness","legislation-policy","investigations"],"approach":"mixed","summary":"US-based farmed animal organisation working in several countries; aquatic work includes public advocacy against octopus farming and, per Rethink Priorities, an early corporate shrimp welfare campaign that led Tesco to pledge to end eyestalk ablation and ice-slurry slaughter.","website":"https://mercyforanimals.org/","hq":"United States","founded":"1999","sources":[{"url":"https://mercyforanimals.org/blog/octopus-farming/","title":"Octopus Farming Isn''t Here Yet — Let''s Keep it That Way","accessed":"2026-11-05","published":"2026-06-03"},{"url":"https://rethinkpriorities.org/impact-area/uncovering-neglected-issues-advancing-shrimp-welfare/","title":"Uncovering neglected issues: advancing shrimp welfare — Rethink Priorities","accessed":"2026-11-05","published":null},{"url":"https://mercyforanimals.org/","title":"Home - Mercy For Animals","accessed":"2026-11-05","published":null},{"url":"https://mercyforanimals.org/about/","title":"About - Mercy For Animals","accessed":"2026-11-05","published":null},{"url":"https://en.wikipedia.org/wiki/Mercy_for_Animals","title":"Mercy for Animals - Wikipedia","accessed":"2026-11-05","published":null}],"notes":"Aquatic animals are a minor part of overall work. Countries from site footer (US/CA, Brazil, Latam, India, Malaysia). Feed mixes MFA blog posts with links to external press coverage. | Six regions not enumerated on fetched page; Brazil and India appear on the about page. Feed mixes MFA blog posts with external press-coverage links.","merged_from":["mercy-for-animals"]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('welfare-footprint-institute','Welfare Footprint Institute','organisation',NULL,'welfare-science','aquatic','active','{"aliases":["WFI","Welfare Footprint Project","Welfare Footprint"],"categories":["welfare-science"],"species":["farmed-fish","crustaceans","chickens","pigs","all-animals","farmed-animals"],"regions":["global"],"countries":[],"interventions":["research","data-tools"],"approach":"research","summary":"Research institute developing the Welfare Footprint Framework, which quantifies welfare as cumulative time in affective states; aquatic work includes appraisals of farmed fish species, fish slaughter (e.g. air asphyxia in rainbow trout) and whiteleg shrimp welfare.","website":"https://welfarefootprint.org/","hq":"United States","founded":null,"sources":[{"url":"https://welfarefootprint.org/","title":"Welfare Footprint Institute — animal welfare quantification","accessed":"2026-11-05","published":null},{"url":"https://welfarefootprint.org/species/welfare-of-farmed-fish","title":"Welfare of Farmed Fish | WFI","accessed":"2026-11-05","published":null},{"url":"https://welfarefootprint.org/shrimp","title":"Shrimp welfare | WFI","accessed":"2026-11-05","published":null},{"url":"https://welfarefootprint.org/about/team","title":"Team - Welfare Footprint Institute","accessed":"2026-11-05","published":null}],"notes":"Incorporated as a US 501(c)(3). Commonly referred to as ''Welfare Footprint Project''; the current site uses ''Welfare Footprint Institute'' (a formal rename was not confirmed on a fetched page). Shrimp project was commissioned by Shrimp Welfare Project. No RSS feed found. | Site now uses the name ''Welfare Footprint Institute''; ''Welfare Footprint Project'' was the earlier name in common use — rename date not verified. /feed redirects to /news (HTML).","merged_from":["welfare-footprint-institute"]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
