INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('ea-animal-welfare-fund','Animal Welfare Fund (EA Funds)','funder',NULL,'funding','aquatic','active','{"aliases":["EA Animal Welfare Fund","AWF","Animal Welfare Fund"],"categories":["funding"],"species":["farmed-fish","crustaceans","chickens","insects","wild-animals","farmed-animals"],"regions":["global","asia","africa","latin-america"],"countries":[],"interventions":["grantmaking"],"approach":"neutral-infrastructure","summary":"Grantmaking fund under EA Funds; its stated goals include aquatic animal welfare R&D and on-farm improvements for farmed shrimp and fish in Asia, Africa and Latin America, and making humane slaughter the default for shrimp.","website":"https://funds.effectivealtruism.org/funds/animal-welfare","hq":"United Kingdom","founded":null,"sources":[{"url":"https://funds.effectivealtruism.org/funds/animal-welfare","title":"Animal Welfare Fund | Effective Altruism Funds","accessed":"2026-11-05","published":null},{"url":"https://funds.effectivealtruism.org/about-us","title":"About us | Effective Altruism Funds","accessed":"2026-11-05","published":null}],"notes":"''hq'' reflects the UK registered office of the EA Funds legal entities shown in the site footer. Grant reports are published on the EA Forum. No RSS feed found. | EA Funds is operated under Centre for Effective Altruism entities (US and UK) per the about page; HQ recorded as UK (Oxford registered office) — uncertain. No feed found.","merged_from":["ea-animal-welfare-fund"]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('coefficient-giving','Coefficient Giving','funder',NULL,'funding','aquatic','active','{"aliases":["Open Philanthropy","Open Philanthropy Project","Open Phil"],"categories":["funding"],"species":["farmed-fish","crustaceans","farmed-animals"],"regions":["global"],"countries":[],"interventions":["grantmaking"],"approach":"neutral-infrastructure","summary":"Philanthropic funder (formerly Open Philanthropy) whose farm animal welfare grantmaking includes aquatic projects, e.g. support for ASC''s Responsible Shrimp Slaughter Project and Friend of the Sea''s Fish Welfare Project.","website":"https://coefficientgiving.org/","hq":"United States","founded":"2011","sources":[{"url":"https://asc-aqua.org/news/shrimp-welfare-project/","title":"ASC launches project to bridge science-to-practice gap in shrimp welfare","accessed":"2026-11-05","published":"2026-09-28"},{"url":"https://friendofthesea.org/marine-conservation-projects-and-awareness/fish-welfare/","title":"Fish Welfare Project — Friend of the Sea","accessed":"2026-11-05","published":null},{"url":"https://friendofthesea.org/fos-and-fair-fish-awarded-open-philantropy-project-grant-to-boost-fish-welfare/","title":"FoS and fair-fish awarded Open Philanthropy Project grant to boost Fish Welfare","accessed":"2026-11-05","published":"2018-01-16"},{"url":"https://www.vox.com/future-perfect/469038/open-philanthropy-coefficient-giving-name-change","title":"One of the world''s most influential philanthropies is changing its name (Vox)","accessed":"2026-11-05","published":"2025-11-18"},{"url":"https://en.wikipedia.org/wiki/Coefficient_Giving","title":"Coefficient Giving - Wikipedia","accessed":"2026-11-05","published":null}],"notes":"coefficientgiving.org returned HTTP 403 to curl and WebFetch, so its own pages were not read. The link to Open Philanthropy is inferred from openphilanthropy.org redirecting to coefficientgiving.org. Grant amounts not verified. | coefficientgiving.org (and openphilanthropy.org redirect) returned 403 to the research fetcher. Formation 2011 and San Francisco location per Wikipedia. Its Farm Animal Welfare fund details not verified directly.","merged_from":["coefficient-giving"]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('essere-animali','Essere Animali','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":[],"categories":["advocacy-campaigns","policy-law"],"species":["farmed-fish","farmed-animals","pigs","chickens"],"regions":["europe"],"countries":["IT"],"interventions":["research","legislation-policy","certification-standards","investigations","diet-change","public-awareness"],"approach":"mixed","summary":"Italian animal protection organisation; aquatic work includes a 2023 report finding that pre-slaughter stunning of farmed fish would have little impact on production costs and criticism of Italy''s ''Sustainable Aquaculture'' certification for lacking a stunning requirement.","website":"https://www.essereanimali.org/","hq":"Italy","founded":null,"sources":[{"url":"https://www.eurogroupforanimals.org/news/new-report-reveals-minimal-cost-fish-welfare","title":"New report reveals the minimal cost of fish welfare — Eurogroup for Animals","accessed":"2026-11-05","published":"2023-02-14"},{"url":"https://www.essereanimali.org/","title":"Essere Animali - Organizzazione per i Diritti Animali","accessed":"2026-11-05","published":null},{"url":"https://www.essereanimali.org/chi-siamo/","title":"Chi siamo - Essere Animali","accessed":"2026-11-05","published":null}],"notes":"essereanimali.org returned HTTP 502 on every attempt, so the organisation''s own site, current activity and feeds could not be verified; status set to ''unclear''. Facts are from a 2023 Eurogroup page. | Founding year not verified.","merged_from":["essere-animali"]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('ali-aquaculture-certification-benchmark','Aquaculture Certification Schemes Benchmark: Aquatic Animal Welfare','resource','aquatic-life-institute','welfare-science','aquatic','active','{"aliases":["ALI Certification Benchmark"],"categories":["welfare-science","movement-infrastructure"],"species":["farmed-fish","crustaceans","cephalopods"],"regions":["global"],"countries":[],"interventions":["certification-standards","research","data-tools"],"approach":"welfare-reform","summary":"Aquatic Life Institute report comparing welfare requirements in major seafood certification schemes (3rd edition, Oct 2024: 8 schemes and 1 ratings agency) on water quality, stocking density, enrichment, feed, stunning and slaughter, and species prohibitions.","website":"https://www.ali.fish/resource-library/aquaculture-certification-schemes-benchmark-2024","hq":null,"founded":null,"sources":[{"url":"https://www.ali.fish/resource-library/aquaculture-certification-schemes-benchmark-2024","title":"2024 Aquaculture Certification Schemes Benchmark: Aquatic Animal Welfare","accessed":"2026-11-05","published":"2024-10-07"}],"notes":"The 2024 edition carries a published correction on GAP''s insect-feed ban. A later edition was not found during this research.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('wfi-trout-air-asphyxia-analysis','Quantifying the welfare impact of air asphyxia in rainbow trout slaughter','resource','welfare-footprint-institute','welfare-science','aquatic','active','{"aliases":["Welfare Footprint fish slaughter pain track"],"categories":["welfare-science"],"species":["farmed-fish"],"regions":["global"],"countries":[],"interventions":["research","humane-slaughter"],"approach":"research","summary":"Peer-reviewed Welfare Footprint analysis (Scientific Reports, 2025) estimating about 10 (1.9-21.7) minutes of moderate to intense pain per rainbow trout killed by air asphyxia, and modelling the cost-effectiveness of electrical and percussive stunning.","website":"https://welfarefootprint.org/publications/trout-air-asphyxia.html","hq":null,"founded":null,"sources":[{"url":"https://welfarefootprint.org/publications/trout-air-asphyxia.html","title":"Air asphyxia in rainbow trout slaughter | WFI","accessed":"2026-11-05","published":null}],"notes":"DOI 10.1038/s41598-025-04272-1. WFI also hosts a ''Fish welfare at slaughter'' species page and a farmed fish appraisal.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('fish-feel','Fish Feel','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":[],"categories":["advocacy-campaigns"],"species":["farmed-fish","wild-fish"],"regions":["north-america"],"countries":["US"],"interventions":["public-awareness","education"],"approach":"abolitionist","summary":"All-volunteer US nonprofit that promotes the recognition of fish as sentient beings. It educates the public about fish, the harms caused by their exploitation in fishing and farming, and how to help them.","website":"https://fishfeel.org/","hq":"United States","founded":null,"sources":[{"url":"https://fishfeel.org/about/","title":"Fish Feel | About Us","accessed":"2026-11-19","published":null}],"notes":"Based in Silver Spring, Maryland; 501(c)(3). Founding year not stated on the About page. Newest feed item is dated 2025-12-31.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('icare-fish','ICARE-FISH','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["iCare-Fish","iCare Fish"],"categories":["advocacy-campaigns","welfare-science"],"species":["farmed-fish","wild-fish"],"regions":["africa"],"countries":["NG"],"interventions":["farm-practices","producer-engagement","research","capacity-building","public-awareness"],"approach":"welfare-reform","summary":"Works on the welfare of aquatic animals in Africa. In Nigeria it has run a baseline survey of cluster fish farms in Edo and Delta States and welfare training for farmers in three farm clusters, and it also engages fishing communities.","website":"https://icare-fish.org/","hq":null,"founded":null,"sources":[{"url":"https://icare-fish.org/","title":"Advocating for Fish Welfare - ICARE-FISH","accessed":"2026-11-19","published":null}],"notes":"Headquarters, founding year and the expansion of the name are not stated on the site; all field work described is in Nigeria. Listed as an Aquatic Animal Alliance member. Newest post is dated 2025-12-02.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('scale-welfare','Scale Welfare','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":[],"categories":["advocacy-campaigns","welfare-science"],"species":["farmed-fish"],"regions":["southeast-asia"],"countries":["PH","VN"],"interventions":["producer-engagement","humane-slaughter","farm-practices","research"],"approach":"welfare-reform","summary":"Works with fish producers and companies in Southeast Asia on low-cost welfare improvements. It is piloting an improved ice-slurry slaughter method for tilapia in the Philippines and has scoped the farmed pangasius industry in Vietnam.","website":"https://www.scalewelfare.org/","hq":null,"founded":null,"sources":[{"url":"https://www.scalewelfare.org/","title":"Improving farmed fish welfare across Southeast Asia | Scale Welfare","accessed":"2026-11-19","published":null},{"url":"https://www.scalewelfare.org/about/","title":"About | Scale Welfare","accessed":"2026-11-19","published":null}],"notes":"Fiscally sponsored project of Anti Entropy (US 501(c)(3)). Team is in the Netherlands, Vietnam and the Philippines; no headquarters or founding year stated. Blog at /blog/ (first post 2026-07-15); no RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('aquaculture-accountability-project','Aquaculture Accountability Project','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["AAP"],"categories":["advocacy-campaigns"],"species":["farmed-fish","crustaceans","wild-fish"],"regions":["north-america"],"countries":[],"interventions":["research","public-awareness","diet-change"],"approach":"mixed","summary":"Challenges ''sustainable seafood'' claims about industrial fish farming, with research and news on farmed salmon and shrimp and on wild fish used as feed. It aims to slow industrial aquaculture and reduce consumption of sea animals.","website":"https://aquacultureaccountability.org/","hq":null,"founded":null,"sources":[{"url":"https://aquacultureaccountability.org/","title":"Aquaculture Accountability Project","accessed":"2026-11-19","published":null},{"url":"https://aquacultureaccountability.org/about/","title":"Who We Are - Aquaculture Accountability Project","accessed":"2026-11-19","published":null}],"notes":"Incubated by the Better Food Foundation and now independent; works in partnership with Farm Forward. The site does not state where it is based - region set to North America from its incubator and partners, to be checked. Newest feed item 2026-03-26.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('vissenbescherming','Stichting Vissenbescherming','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["Vissenbescherming"],"categories":["advocacy-campaigns"],"species":["farmed-fish","wild-fish","crustaceans"],"regions":["europe"],"countries":["NL"],"interventions":["public-awareness","legislation-policy","education"],"approach":"mixed","summary":"Dutch foundation for the welfare of fish and other aquatic animals, working in the Netherlands and at European level. It covers sea fisheries, fish farming, angling, ornamental fish and the sale and cooking of live lobsters and crabs, and runs a shrimp campaign.","website":"https://www.vissenbescherming.nl/","hq":"Netherlands","founded":"2000","sources":[{"url":"https://www.vissenbescherming.nl/","title":"Vissenbescherming","accessed":"2026-11-19","published":null}],"notes":"Based in The Hague. Newest feed item 2025-09-18.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('shellfish-network','Shellfish Network','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":[],"categories":["advocacy-campaigns","policy-law"],"species":["crustaceans","cephalopods"],"regions":["uk"],"countries":["GB"],"interventions":["legislation-policy","public-awareness","diet-change"],"approach":"mixed","summary":"UK campaign group seeking to extend the protections of the Animal Welfare Act to shellfish, including crustaceans such as lobsters and crabs. It lobbies MPs, runs petitions and publishes evidence on shellfish sentience.","website":"https://shellfishnetwork.weebly.com/","hq":"United Kingdom","founded":null,"sources":[{"url":"https://shellfishnetwork.weebly.com/","title":"Shellfish Network - Home","accessed":"2026-11-19","published":null}],"notes":"Founding year not stated. Newest dated item on the site is from October 2025; most campaign material dates from 2021-2024.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('seastemik','Seastemik','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":[],"categories":["advocacy-campaigns"],"species":["farmed-fish","wild-fish"],"regions":["europe"],"countries":["FR"],"interventions":["public-awareness","corporate-campaigns","diet-change"],"approach":"mixed","summary":"French association that works to reduce fish consumption in France and to move away from intensive fish farming, especially of salmon. It runs public and corporate campaigns and promotes plant-based alternatives.","website":"https://seastemik.org/","hq":"France","founded":null,"sources":[{"url":"https://seastemik.org/","title":"Accueil | Seastemik","accessed":"2026-11-19","published":null}],"notes":"Site menu lists a ''Pinkbombs'' project on salmon farming. Founding year not stated; no RSS feed found. Site footer is dated 2026.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('world-day-for-end-of-fishing','World Day for the End of Fishing and Fish Farming','programme',NULL,'direct-action','aquatic','active','{"aliases":["World Day for the End of Fishing","La question aquatique","Journée Mondiale pour la Fin de la Pêche"],"categories":["direct-action","advocacy-campaigns"],"species":["farmed-fish","wild-fish","crustaceans","cephalopods"],"regions":["global"],"countries":["FR"],"interventions":["protest","public-awareness"],"approach":"abolitionist","summary":"Annual international day of action, held in late March, calling for an end to fishing and fish farming. The French association La question aquatique coordinates it; the 10th edition on 28 March 2026 reported 183 actions by 202 organisations in 32 countries.","website":"https://end-of-fishing.org/en/","hq":"France","founded":null,"sources":[{"url":"https://end-of-fishing.org/en/","title":"End of fishing - World day for the end of fishing and fish farming","accessed":"2026-11-19","published":null},{"url":"https://end-of-fishing.org/en/who-are-we/","title":"Who are we? - World day for the end of fishing and fish farming","accessed":"2026-11-19","published":null}],"notes":"The site says La question aquatique has organised the day since 2019; a 10th edition in 2026 implies a first edition around 2017 under an earlier organiser (not stated on the pages fetched). Participation figures are the organiser''s own. Next editions listed: 27 March 2027, 25 March 2028.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('for-fishes','For the Fishes','organisation',NULL,'advocacy-campaigns','aquatic','unclear','{"aliases":[],"categories":["advocacy-campaigns"],"species":["wild-fish"],"regions":["north-america"],"countries":["US"],"interventions":["public-awareness","legislation-policy","research","data-tools"],"approach":"mixed","summary":"Hawaii-based nonprofit working to reduce demand for coral reef fish and other wildlife caught for the aquarium trade, through consumer education, research and advocacy. It publishes the Tank Watch guide to saltwater aquarium species.","website":"https://forthefishes.org/","hq":"United States","founded":null,"sources":[{"url":"https://forthefishes.org/","title":"Home - For The Fishes","accessed":"2026-11-19","published":null}],"notes":"Based in Kihei, Hawaii. Newest dated news item on the homepage is from October 2021 and the RSS feed stops in 2019, so current activity is unconfirmed (site footer is dated 2026).","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('ethical-seafood-research','Ethical Seafood Research','organisation',NULL,'welfare-science','aquatic','active','{"aliases":["ESR","Ethical Seafood Research Centre"],"categories":["welfare-science","advocacy-campaigns"],"species":["farmed-fish"],"regions":["africa"],"countries":["KE","EG"],"interventions":["research","farm-practices","producer-engagement","capacity-building","legislation-policy"],"approach":"welfare-reform","summary":"Nonprofit that aims to reduce aquatic animal suffering in the food system, with a focus on Africa. It trains fish farmers in welfare protocols and works with governments, universities and industry; it has country managers in Kenya and Egypt.","website":"https://ethicalseafoodresearch.org/","hq":null,"founded":null,"sources":[{"url":"https://ethicalseafoodresearch.org/","title":"Ethical Seafood Research","accessed":"2026-11-19","published":null},{"url":"https://ethicalseafoodresearch.org/about/","title":"About - Ethical Seafood Research","accessed":"2026-11-19","published":null}],"notes":"Registered as Ethical Seafood Research Centre Ltd in Scotland (SC837259), as a non-profit association in Spain and as a company limited by guarantee in Kenya; no single headquarters stated. Also runs a seaweed farming programme. Founding year not stated. Site returned 403 to plain HTTP clients.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('shared-africa','SHARED Africa','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":[],"categories":["advocacy-campaigns","policy-law"],"species":["farmed-fish","farmed-animals"],"regions":["africa"],"countries":["GH"],"interventions":["legislation-policy","humane-slaughter","research"],"approach":"welfare-reform","summary":"Animal welfare organisation currently focused on Ghana. Its FISH FIRST project advocates for enforceable fish welfare provisions in Ghana''s fisheries legislation, mainly for cage-farmed Nile tilapia; a second project seeks pre-slaughter stunning rules.","website":"https://www.sharedafrica.org/","hq":null,"founded":null,"sources":[{"url":"https://www.sharedafrica.org/","title":"SHARED Africa","accessed":"2026-11-19","published":null},{"url":"https://www.sharedafrica.org/projects","title":"Projects - SHARED Africa","accessed":"2026-11-19","published":null}],"notes":"Headquarters, founding year and the meaning of ''SHARED'' are not stated on the site. Listed as an Aquatic Animal Alliance member. The site''s RSS feed only contains template posts from 2019, so it is not listed.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('apon-nigeria','Animal Protection Organisation of Nigeria','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["APON"],"categories":["advocacy-campaigns"],"species":["farmed-fish","all-animals"],"regions":["africa"],"countries":["NG"],"interventions":["research","education","farm-practices"],"approach":"welfare-reform","summary":"Nigerian animal protection organisation with a youth-education mission. Its Fish Welfare Implementation Pilot surveyed catfish welfare practices on ten farms in Olluedede village, Auchi, Edo State, with a report published in May 2026.","website":"https://aponwelfare.org/","hq":"Nigeria","founded":null,"sources":[{"url":"https://aponwelfare.org/fish-welfare-survey-in-nigeria/","title":"Fish Welfare Survey in Nigeria","accessed":"2026-11-19","published":"2026-05-01"},{"url":"https://aponwelfare.org/","title":"APON - Animal Protection Organisation of Nigeria","accessed":"2026-11-19","published":null}],"notes":"City of headquarters and founding year not stated on the pages fetched. Listed as an Aquatic Animal Alliance member (as ''APON Welfare'').","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('animal-rights-initiative','Animal Rights Initiative','organisation',NULL,'policy-law','aquatic','active','{"aliases":["ARI"],"categories":["policy-law","advocacy-campaigns"],"species":["cephalopods","all-animals"],"regions":["north-america"],"countries":["US"],"interventions":["legislation-policy","public-awareness"],"approach":"abolitionist","summary":"US nonprofit that pursues state legislation to prohibit octopus farming before it starts. It reports Washington State''s ban of March 2024 and bills or sponsors in Hawaii, California, New Jersey, Oregon, Connecticut and other states; it also campaigns on fur.","website":"https://www.animalrightsinitiative.org/","hq":"United States","founded":"2017","sources":[{"url":"https://www.animalrightsinitiative.org/octopus","title":"Octopus | Animal Rights Initiative","accessed":"2026-11-19","published":null},{"url":"https://www.animalrightsinitiative.org/about","title":"About | Animal Rights Initiative","accessed":"2026-11-19","published":null}],"notes":"Began in 2017 with Seattle-based volunteers; 501(c)(3). Legislative status is as described on its own campaign page and was not checked against state records. Newest feed item 2025-04-22; the site links a 2025 annual report.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('catch-welfare-platform','Catch Welfare Platform','network',NULL,'welfare-science','aquatic','active','{"aliases":[],"categories":["welfare-science","movement-infrastructure"],"species":["wild-fish"],"regions":["europe"],"countries":["NO","NL"],"interventions":["research","producer-engagement","humane-slaughter"],"approach":"welfare-reform","summary":"Industry-science platform for practical improvements to animal welfare in capture fisheries. An initiative of Nofima, the Institute of Marine Research (Norway) and Wageningen University & Research, it runs conferences and an award and invites industry members.","website":"https://catchwelfareplatform.com/","hq":null,"founded":null,"sources":[{"url":"https://catchwelfareplatform.com/","title":"Catch Welfare Platform","accessed":"2026-11-19","published":null}],"notes":"The site says it is funded by Open Philanthropy (now Coefficient Giving) and lists partners including Zhejiang University (China), UiT (Norway) and Vietfish Magazine (Vietnam). Start year not stated; the homepage refers to a fourth conference. RSS feed exists but has no items.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('carefish-catch','Carefish/catch','programme','fair-fish-international','welfare-science','aquatic','active','{"aliases":[],"categories":["welfare-science"],"species":["wild-fish"],"regions":["europe"],"countries":[],"interventions":["research","certification-standards"],"approach":"welfare-reform","summary":"Project on the welfare of wild-caught fish. It assesses the welfare impact of major fishing methods, proposes ways to reduce suffering, tests their economic feasibility and feeds the results into fishing standards such as Friend of the Sea.","website":"https://carefish.net/catch/","hq":null,"founded":null,"sources":[{"url":"https://fair-fish.net/page/AsT/carefishcatch?linklist=True","title":"Carefish/catch - fair-fish","accessed":"2026-11-19","published":null},{"url":"https://carefish.net/catch/","title":"Carefish/catch","accessed":"2026-11-19","published":null}],"notes":"Partners: fair-fish (welfare data in the fair-fish database), CCMAR, FishEthoGroup, Friend of the Sea and DeMoS. Funder and start/end years are not stated on the pages fetched; the project site carries a news item dated 2025-11-28 summarising project highlights, so it may be near completion.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('onekind','OneKind','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":[],"categories":["advocacy-campaigns"],"species":["farmed-fish","all-animals"],"regions":["uk"],"countries":["GB"],"interventions":["legislation-policy","public-awareness","research"],"approach":"mixed","summary":"Scottish animal welfare charity. Its ''Stop salmon farming expansion'' campaign calls on the Scottish Government to halt expansion of salmon farming, and it has published reports on salmon and cleaner fish welfare on Scotland''s salmon farms.","website":"https://www.onekind.org/","hq":"United Kingdom","founded":null,"sources":[{"url":"https://www.onekind.org/stop-salmon-farming-expansion","title":"Stop salmon farming expansion | OneKind","accessed":"2026-11-19","published":"2022-05-03"},{"url":"https://www.onekind.org/blog/latest-blow-to-destructive-salmon-farming-industry-18-11-26","title":"Latest blow to destructive salmon farming industry","accessed":"2026-11-19","published":"2026-11-17"}],"notes":"Registered Scottish charity SC041299. Reports include ''Cleaner fish welfare on Scotland''s salmon farms'' (2018) and ''Underwater cages, parasites and dead fish'' (2021, with Compassion in World Farming). Campaign page last updated 2025-12-18. Founding year not stated on the pages fetched; no RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('samayu','Samayu','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":[],"categories":["advocacy-campaigns","policy-law"],"species":["farmed-fish","farmed-animals","chickens","companion-animals"],"regions":["south-asia"],"countries":["IN"],"interventions":["legislation-policy","research","producer-engagement","capacity-building","farm-practices","public-awareness"],"approach":"welfare-reform","summary":"Indian non-profit working at the intersection of food, health and justice. Combines research, policy advocacy and community work on aquaculture reform, poultry antimicrobial resistance with state governments, faith-based engagement on animals, food-system convenings and dog coexistence. Its aquaculture work includes a One Health One Welfare project with the Madhya Pradesh Fisheries Department involving over 120 farmers and eight fisher cooperatives.","website":"https://samayu.org/","hq":"India","founded":null,"sources":[{"url":"https://samayu.org/","title":"Home | Samayu - Animals, People & Planet","accessed":"2026-11-19","published":null}],"notes":"City and founding year not stated on the homepage. Samayu''s own figure for the Madhya Pradesh project is a potential 92.5 million farmed fish affected. Listed as an Aquatic Animal Alliance member. RSS feed exists but has no items. | Founding year not stated on the site. Not fish-only: also works on poultry and dogs. /feed/ returns RSS with no items, so no feed listed. Also profiled in aquatic-gaps-entities.json under the same id; the build merges the two records (this one adds the movement-wide tags).","merged_from":["samayu"]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('animals-aotearoa','Animals Aotearoa','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":[],"categories":["advocacy-campaigns"],"species":["chickens","cephalopods","farmed-fish","farmed-animals"],"regions":["oceania"],"countries":["NZ"],"interventions":["corporate-campaigns","legislation-policy","public-awareness"],"approach":"welfare-reform","summary":"New Zealand organisation, part of the Open Wing Alliance, working to end the abuse of farmed animals. Its work centres on chicken welfare, including corporate campaigns and an election scorecard on farmed animal welfare. It campaigns for a pre-emptive ban on octopus factory farming in New Zealand, including an open letter to the Government signed by 169 organisations and a petition.","website":"https://animalsaotearoa.org/","hq":"New Zealand","founded":"2021","sources":[{"url":"https://animalsaotearoa.org/octopus-factory-farming/","title":"About Octopus Factory Farming - Animals Aotearoa","accessed":"2026-11-19","published":null},{"url":"https://animalsaotearoa.org/about-us/impact/","title":"Animals Aotearoa Impact & Annual Reports","accessed":"2026-11-19","published":null},{"url":"https://animalsaotearoa.org/","title":"Animals Aotearoa","accessed":"2026-11-19","published":null},{"url":"https://animalsaotearoa.org/feed/","title":"Animals Aotearoa (site feed: description and recent posts)","accessed":"2026-11-19","published":null},{"url":"https://animalcharityevaluators.org/movement-grants/past-movement-grants-recipients/","title":"ACE Movement Grants: past recipients","accessed":"2026-11-19","published":null}],"notes":"Registered charity CC59360; member of the Open Wing Alliance and the Aquatic Animal Alliance. The open letter''s URL indicates May 2025. Site rate-limited automated requests (429), so the feed could not be checked. | Site pages returned HTTP 429 (rate limit) to the research sandbox, so the description comes from the site''s own RSS feed. ACE Movement Grant recipient in 2025; also an EA Animal Welfare Fund grantee.","merged_from":["animals-aotearoa"]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('safe-nz','SAFE','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["Save Animals From Exploitation","SAFE for Animals"],"categories":["advocacy-campaigns"],"species":["farmed-fish","farmed-animals","all-animals"],"regions":["oceania"],"countries":["NZ"],"interventions":["legislation-policy","public-awareness","diet-change","investigations"],"approach":"mixed","summary":"New Zealand animal rights charity that uses research, strategic communications, investigations and public support to drive institutional, political and societal change for animals, with campaigns on farmed animals and the animal welfare system. On fish it calls for an immediate halt to proposed fish farm expansions and new developments, citing repeated mass mortality events on Chinook salmon farms.","website":"https://safe.org.nz/","hq":"New Zealand","founded":null,"sources":[{"url":"https://safe.org.nz/news/fish-farms-the-underwater-factory-farms-hidden-beneath-the-surface/","title":"Fish farms: the underwater factory farms hidden beneath the surface","accessed":"2026-11-19","published":"2026-10-23"},{"url":"https://safe.org.nz/about-us/","title":"How we work – SAFE","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/SAFE_(New_Zealand_organisation)","title":"SAFE (New Zealand organisation) - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"Founding year not verified on the page fetched. The feed covers all SAFE topics, not only fish. | Wikipedia: evolved from an Auckland branch of the British Union for the Abolition of Vivisection; renamed Save Animals from Experiments in 1972 and Save Animals from Exploitation in 1987. Founding year left null because sources give different starting points.","merged_from":["safe-nz"]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('animalia-finland','Animalia','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["Animalia ry"],"categories":["advocacy-campaigns"],"species":["farmed-fish","wild-fish","farmed-animals","fur-animals"],"regions":["europe"],"countries":["FI"],"interventions":["legislation-policy","public-awareness"],"approach":"mixed","summary":"Finnish animal rights organisation. On fish farming it calls for a ban on carbon dioxide stunning of farmed fish, more welfare inspections and data, tighter stocking-density rules and no public support for expanding fish farming.","website":"https://animalia.fi/","hq":"Finland","founded":null,"sources":[{"url":"https://animalia.fi/kalankasvatus/","title":"Kalankasvatus - Animalia","accessed":"2026-11-19","published":null}],"notes":"Registered in Helsinki. Founding year not stated on the page fetched. The page cites about seven million fish slaughtered a year on Finnish fish farms, mostly rainbow trout. The feed covers all Animalia topics.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('project-1882','Project 1882','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["Djurens Rätt","Project 1882","Nordiska samfundet mot plågsamma djurförsök"],"categories":["advocacy-campaigns","policy-law"],"species":["farmed-fish","wild-fish","farmed-animals","fur-animals","chickens","animals-in-research"],"regions":["europe"],"countries":["SE"],"interventions":["legislation-policy","public-awareness","diet-change","corporate-campaigns"],"approach":"mixed","summary":"Swedish animal rights and animal protection membership organisation, active since 1882 and known internationally as Project 1882. Runs targeted campaigns, corporate outreach and political advocacy for animals in factory farms, fur farms and experiments. On fishes it seeks stronger welfare law in Sweden and the EU, a ban on carbon dioxide stunning at slaughter, legal coverage of wild-caught fish and welfare criteria in fish certifications.","website":"https://www.project1882.org/","hq":"Sweden","founded":"1882","sources":[{"url":"https://www.project1882.org/what-we-do/factory-farms/fishes","title":"Fishes | Project 1882","accessed":"2026-11-19","published":null},{"url":"https://www.djurensratt.se/","title":"Djurens Rätt – Sedan 1882 (homepage)","accessed":"2026-11-19","published":null},{"url":"https://www.project1882.org/","title":"Project 1882 – Since 1882 (international site)","accessed":"2026-11-19","published":null},{"url":"https://sv.wikipedia.org/wiki/Djurens_R%C3%A4tt","title":"Djurens Rätt - Wikipedia (sv)","accessed":"2026-11-19","published":null}],"notes":"The Swedish-language site is djurensratt.se and news slugs on project1882.org use ''Djurens Rätt''. Site news includes a report against investment in fish-farming factories and a call for more protection of salmon in Scotland. No RSS feed found. | Uses the name Project 1882 internationally (project1882.org); the aquatic-gaps research file lists the same organisation under id ''project-1882'' - merge. Homepage (Nov 2026) reports about 70,000 members and donors; Swedish Wikipedia gives c. 50,000 members. No RSS feed found.","merged_from":["djurens-ratt"]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('noah-for-dyrs-rettigheter','NOAH - for dyrs rettigheter','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["NOAH"],"categories":["advocacy-campaigns"],"species":["farmed-fish","wild-fish","wild-animals","all-animals"],"regions":["europe"],"countries":["NO"],"interventions":["public-awareness","legislation-policy"],"approach":"mixed","summary":"Norwegian animal rights organisation. Its ''animals in the sea'' work covers farmed fish, fishing, whaling and sealing; it publishes material on fish pain and on welfare problems in Norwegian fish farming and says it has helped tighten rules on the treatment of fish.","website":"https://www.dyrsrettigheter.no/","hq":"Norway","founded":null,"sources":[{"url":"https://www.dyrsrettigheter.no/havet/","title":"Dyrene i havet - NOAH - for dyrs rettigheter","accessed":"2026-11-19","published":null}],"notes":"Founding year not stated on the page fetched. The feed covers all NOAH topics.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('animal-rights-center-japan','Animal Rights Center Japan','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["ARCJ","アニマルライツセンター","Animal Rights Center"],"categories":["advocacy-campaigns"],"species":["crustaceans","farmed-fish","chickens","pigs","farmed-animals"],"regions":["east-asia"],"countries":["JP"],"interventions":["public-awareness","corporate-campaigns","investigations","protest","education","research"],"approach":"mixed","summary":"Tokyo-based certified nonprofit, established in 1987, focused on reducing the suffering of animals used for food. Carries out farm investigations, corporate outreach and negotiation, street activism, education and awareness surveys; projects include a company welfare benchmark and a sanctuary. Its #ShrimpsMatter campaign, launched in August 2021 with funding from Compassion in World Farming, informs consumers about eyestalk ablation of breeder shrimp.","website":"https://arcj.org/en/","hq":"Japan","founded":"1987","sources":[{"url":"https://arcj.org/en/issues-en/animal-welfare-en/shrimpsmatter/","title":"Cruelty in shrimp farms exposed, #ShrimpsMatter campaign launched!","accessed":"2026-11-19","published":null},{"url":"https://arcj.org/en/","title":"Animal Rights Center Japan (English homepage)","accessed":"2026-11-19","published":null},{"url":"https://arcj.org/en/about-us/","title":"About us - Animal Rights Center Japan","accessed":"2026-11-19","published":null}],"notes":"The campaign page says activities through January 2022 were funded by Compassion in World Farming International. Founding year not verified. Feeds cover all ARCJ topics (Japanese and English). | Established October 1987; approved specified nonprofit corporation since 18 August 2017 (about page). Feed is the main Japanese-language feed; an English feed also exists at /en/feed/. Also profiled in aquatic-gaps-entities.json under the same id; the build merges the two records (this one adds the movement-wide tags).","merged_from":["animal-rights-center-japan"]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('l214','L214','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["L214 Éthique & Animaux"],"categories":["advocacy-campaigns"],"species":["farmed-fish","wild-fish","farmed-animals","chickens","pigs"],"regions":["europe"],"countries":["FR"],"interventions":["investigations","public-awareness","legislation-policy","corporate-campaigns","diet-change"],"approach":"mixed","summary":"French association defending animals used for food (meat, milk, eggs, fish). Since 2008 it has published more than 175 filmed investigations into farming, transport and slaughter conditions, and campaigns for change at political and individual level. On fish it publishes a dossier on fishing and aquaculture and an investigation of trout farms and a trout slaughterhouse of the Aqualande group.","website":"https://www.l214.com/","hq":"France","founded":"2008","sources":[{"url":"https://www.l214.com/animaux/poissons/","title":"L''exploitation des poissons : un océan de souffrances | L214","accessed":"2026-11-19","published":null},{"url":"https://www.l214.com/enquetes/","title":"Enquêtes de L214 | L214","accessed":"2026-11-19","published":null},{"url":"https://www.l214.com/","title":"L214 : Agir pour les animaux (homepage)","accessed":"2026-11-19","published":null},{"url":"https://www.l214.com/qui-sommes-nous/en-bref/","title":"L214 | Qui sommes-nous ? En bref","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/L214","title":"L214 - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"Search results (not fetched) show L214 filed an objection in December 2025 to Pure Salmon''s planned salmon farm at Le Verdon-sur-Mer. Founding year not verified. The feed covers all L214 topics. | Wikipedia describes its purpose as promotion of animal rights and antispeciesism; it grew out of the Stop Gavage campaign against foie gras. Approach tagged abolitionist on that basis, though it also runs welfare-focused corporate campaigns.","merged_from":["l214"]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('welfarm','Welfarm','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["WELFARM – Protection mondiale des animaux de ferme"],"categories":["advocacy-campaigns","policy-law"],"species":["farmed-fish","farmed-animals"],"regions":["europe"],"countries":["FR"],"interventions":["legislation-policy","public-awareness","humane-slaughter","education","farm-practices"],"approach":"welfare-reform","summary":"French association, with a mission recognised as being of public utility, that works for better consideration of the welfare of farmed animals at every stage of their lives: rearing, transport and slaughter. Also produces educational material for teachers. On fish it opposes three planned very large intensive salmon farms in France, calls for a moratorium on such farms and for mandatory stunning of fish before slaughter; campaign launched in April 2024.","website":"https://welfarm.fr/","hq":"France","founded":null,"sources":[{"url":"https://welfarm.fr/nos-champs-d-action/les-poissons-des-animaux-sensibles-et-intelligents/","title":"Les poissons, des animaux sensibles et intelligents - Welfarm","accessed":"2026-11-19","published":"2024-07-08"},{"url":"https://welfarm.fr/","title":"Welfarm (homepage)","accessed":"2026-11-19","published":null}],"notes":"The salmon campaign is titled ''RAS : Tout à signaler'' with a petition at urgence-saumons.fr. Founding year not stated on the page fetched. The feed covers all Welfarm topics. | Founding year not stated on the pages fetched (commonly given as 1994, formerly PMAF) - unverified, left null.","merged_from":["welfarm"]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('paz-projet-animaux-zoopolis','PAZ (Projet Animaux Zoopolis)','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["PAZ","Association PAZ"],"categories":["advocacy-campaigns"],"species":["wild-fish","crustaceans","all-animals"],"regions":["europe"],"countries":["FR"],"interventions":["legislation-policy","public-awareness","corporate-campaigns"],"approach":"mixed","summary":"Paris-based French animal advocacy association. Its fishing work seeks a ban on live-bait angling (pêche au vif), analyses public subsidies to recreational fishing and tracks retailers selling live fish and crabs as bait.","website":"https://zoopolis.fr/","hq":"France","founded":null,"sources":[{"url":"https://zoopolis.fr/campagne-peche-au-vif-les-lignes-bougent/","title":"Campagne pêche au vif : les lignes bougent","accessed":"2026-11-19","published":"2021-01-30"},{"url":"https://zoopolis.fr/feed/","title":"PAZ RSS feed","accessed":"2026-11-19","published":null}],"notes":"A feed item of 2026-06-19 reports PAZ''s 2026 review of Decathlon stores selling live fish and crabs as bait. Founding year not stated on the pages fetched. The feed covers all PAZ topics.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('animal-law-focus','Animal Law Focus','organisation',NULL,'policy-law','aquatic','active','{"aliases":["Fundación Animal Law Focus"],"categories":["policy-law","advocacy-campaigns"],"species":["farmed-fish","farmed-animals"],"regions":["latin-america"],"countries":["CL"],"interventions":["research","data-tools","public-awareness","legislation-policy","litigation","investigations"],"approach":"mixed","summary":"Chile-rooted legal organisation that uses the law against cruelty to farmed animals in the Global South. Researches regulatory gaps, files complaints, proposes reforms and works with authorities and companies; programmes cover farm animals, animals in aquaculture and Veg Focus. Its aquaculture programme runs the #22Minutos campaign for recognition of fish sentience, an interactive map of Chile''s aquaculture sites and a ranking of companies by violations.","website":"https://www.animallawfocus.org/","hq":"Chile","founded":null,"sources":[{"url":"https://www.animallawfocus.org/aquaculture","title":"Aquaculture | Animal Law Focus","accessed":"2026-11-19","published":null},{"url":"https://www.animallawfocus.org/ourwork","title":"Nuestro Trabajo | Animal Law Focus","accessed":"2026-11-19","published":null},{"url":"https://www.animallawfocus.org/","title":"Animal Law Focus (homepage)","accessed":"2026-11-19","published":null},{"url":"https://animalcharityevaluators.org/blog/announcing-round-11-movement-grants/","title":"Announcing Round 11 Movement Grants - Animal Charity Evaluators","accessed":"2026-11-19","published":null}],"notes":"The ranking draws on official complaints and sanctions from 2018-2023; the map is described as a beta. The organisation says its work covers selected countries in Latin America, Africa and South and Southeast Asia, but only Chile is documented for aquaculture. Founding year not stated. | Chile base taken from the site description and ACE''s grant listing (Fundación Animal Law Focus, Chile; litigation against farms and slaughterhouses). Site says work focuses on selected countries of Latin America, Africa and South and Southeast Asia; founding year not stated. Also profiled in aquatic-gaps-entities.json under the same id; the build merges the two records (this one adds the movement-wide tags).","merged_from":["animal-law-focus"]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('latin-group-for-animals','Latin Group for Animals','network',NULL,'policy-law','aquatic','active','{"aliases":["Grupo Latino por los Animales","LatinGroup for Animals"],"categories":["policy-law","movement-infrastructure"],"species":["all-animals","cephalopods"],"regions":["latin-america"],"countries":[],"interventions":["legislation-policy","capacity-building"],"approach":"mixed","summary":"Network of more than 60 organisations from 12 Latin American countries, formed in early 2025, that works to strengthen laws and public policies for animals. Aquatic animals are one of its work areas, and it promotes a petition to ban octopus farms in Chile.","website":"https://latingroupforanimals.org/","hq":null,"founded":"2025","sources":[{"url":"https://latingroupforanimals.org/","title":"Latin Group for Animals - Grupo Latino por los Animales","accessed":"2026-11-19","published":null},{"url":"https://latingroupforanimals.org/redirigir-pulpos/","title":"Redirect to petition against octopus farms in Chile","accessed":"2026-11-19","published":null}],"notes":"Member list is at /integrantes/ (not fetched); the 12 countries are not named on the homepage. Detail of the aquatic work area is thin on the site. RSS feed exists but has no items.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('fundacion-veg','Fundación Veg','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["Vegetarianos Hoy","FVEG","Fundación Vegetarianos Hoy"],"categories":["advocacy-campaigns"],"species":["farmed-fish","crustaceans","cephalopods","farmed-animals"],"regions":["latin-america"],"countries":["CL","MX","CO","PE","AR"],"interventions":["research","public-awareness","diet-change","certification-standards","legislation-policy"],"approach":"mixed","summary":"Non-profit created in Santiago, Chile, in 2012 to promote plant-based eating and reduce the suffering of animals raised for food in Latin America. Runs vegan product certification, the Cambia Tu Plato food campaign and policy advocacy, with teams in Argentina, Chile, Colombia, Mexico and Peru. In July 2024 it published a survey with Inside Research on how Chileans perceive fish and other aquatic animals as sentient beings.","website":"https://fundacionveg.org/","hq":"Chile","founded":"2012","sources":[{"url":"https://fundacionveg.org/inside-research-peces-animales-sintientes-2024/","title":"Encuesta Inside Research: Los Peces como Animales Sintientes (2024)","accessed":"2026-11-19","published":"2024-07-22"},{"url":"https://fundacionveg.org/","title":"Fundación Veg (homepage)","accessed":"2026-11-19","published":null},{"url":"https://fundacionveg.org/quienes-somos/","title":"Quiénes somos - Fundación Veg","accessed":"2026-11-19","published":null}],"notes":"Listed as an Aquatic Animal Alliance member under vegetarianoshoy.org. Only the 2024 survey was verified as fish-specific work; other aquatic campaigns were not confirmed on fetched pages. The site''s RSS feed has a single 2024 item and is not listed. | The about page also uses the earlier name Fundación Vegetarianos Hoy. Site RSS feed has a single item from 2024, so it is not listed. Also profiled in aquatic-gaps-entities.json under the same id; the build merges the two records (this one adds the movement-wide tags).","merged_from":["fundacion-veg"]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('in-defense-of-animals','In Defense of Animals','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["IDA"],"categories":["advocacy-campaigns"],"species":["cephalopods","all-animals"],"regions":["north-america"],"countries":["US"],"interventions":["legislation-policy","public-awareness"],"approach":"mixed","summary":"US animal protection organisation, active since 1983. Its octopus work includes a campaign asking Spanish authorities to reject Nueva Pescanova''s planned octopus farm and support for US federal and state bills to ban octopus farming.","website":"https://www.idausa.org/","hq":"United States","founded":"1983","sources":[{"url":"https://www.idausa.org/campaign/wild-animals-and-habitats/latest-news/victory-plans-for-the-worlds-first-octopus-farm-are-scrapped/","title":"Victory: Plans for the World''s First Octopus Farm Are Scrapped","accessed":"2026-11-19","published":"2026-07-31"}],"notes":"Based in San Rafael, California. Its site also carries action pages on octopus farming bans in Massachusetts, New Jersey and New York. No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('animal-outlook','Animal Outlook','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["Compassion Over Killing","COK"],"categories":["advocacy-campaigns","policy-law"],"species":["farmed-fish","farmed-animals","chickens"],"regions":["north-america"],"countries":["US"],"interventions":["investigations","public-awareness","diet-change","litigation"],"approach":"mixed","summary":"US national non-profit animal advocacy organisation, formed in 1995 as Compassion Over Killing and based in Washington, D.C. Its investigators, attorneys and advocates expose conditions in animal agribusiness, pursue legal accountability and promote vegan eating. It investigated Cooke Aquaculture''s salmon hatchery in Maine in 2019 and published a return investigation of the same facility in May 2026.","website":"https://animaloutlook.org/","hq":"United States","founded":"1995","sources":[{"url":"https://animaloutlook.org/animal-outlooks-return-investigation-of-cooke-aquaculture/","title":"Animal Outlook''s return investigation of Cooke Aquaculture","accessed":"2026-11-19","published":"2026-05-15"},{"url":"https://animaloutlook.org/","title":"Animal Outlook | Exposing Truth. Inspiring Change.","accessed":"2026-11-19","published":null},{"url":"https://animaloutlook.org/about/","title":"About Us - Animal Outlook","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/Animal_Outlook","title":"Animal Outlook - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"501(c)(3). Founding year and former name not verified on fetched pages. The feed covers all Animal Outlook topics. | Former name, founding year and location from Wikipedia.","merged_from":["animal-outlook"]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('animal-kingdom','Animal Kingdom Foundation','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":["AKF","Better Fish, Tomorrow"],"categories":["advocacy-campaigns","sanctuary-rescue"],"species":["farmed-fish","all-animals","companion-animals","chickens","farmed-animals"],"regions":["southeast-asia"],"countries":["PH"],"interventions":["research","public-awareness","legislation-policy","sanctuary","education"],"approach":"welfare-reform","summary":"Philippine non-profit founded in 2002. Runs a rescue centre and low-cost clinic and campaigns to end the dog meat trade; its campaigns also include ''Cage-Free, Go Cruel-Free'' for laying hens and ''Better Fish Tomorrow''. Also responds to disasters affecting animals. Its ''Better Fish, Tomorrow'' campaign works on farmed fish welfare: a study of farmers'' and stakeholders'' views, educational materials and a call to include fish welfare in aquaculture policy.","website":"https://www.akfrescues.org/","hq":"Philippines","founded":"2002","sources":[{"url":"https://www.akfrescues.org/fish","title":"Fish - Animal Kingdom Foundation","accessed":"2026-11-19","published":null},{"url":"https://www.akfrescues.org/","title":"Animal Kingdom Foundation | Animal Welfare Philippines","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/Animal_Kingdom_Foundation","title":"Animal Kingdom Foundation - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"The fish page names milkfish and tilapia and criticises ice-slurry slaughter; it gives no dates and its footer is dated 2024, so how current the campaign is was not confirmed. The older domain akf.org.ph failed TLS from the research environment. Founding year not stated. | Based in Capas, Tarlac (Wikipedia). Older domain akf.org.ph returned 503. Also profiled in aquatic-gaps-entities.json under the same id; the build merges the two records (this one adds the movement-wide tags).","merged_from":["animal-kingdom"]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('asian-fish-welfare-network','Asian Fish Welfare Network','programme','university-of-stirling','welfare-science','aquatic','active','{"aliases":["AFWN","Improving Farmed Fish Welfare in Asia"],"categories":["welfare-science"],"species":["farmed-fish"],"regions":["southeast-asia"],"countries":["TH","VN","ID","GB"],"interventions":["research","capacity-building","grantmaking","education"],"approach":"research","summary":"University of Stirling Institute of Aquaculture project (2025-2028) building capacity for farmed fish and aquatic animal welfare research in Thailand, Vietnam and Indonesia. It funds collaborative research through competitive calls, MSc studentships, training and workshops.","website":"https://susaquastirling.net/asiafishwelfare","hq":"United Kingdom","founded":"2025","sources":[{"url":"https://susaquastirling.net/asiafishwelfare","title":"Asian Fish Welfare Network","accessed":"2026-11-19","published":null},{"url":"https://thefishsite.com/articles/indonesia-begins-exploring-fish-welfare-through-new-research-initiative","title":"Indonesia begins exploring fish welfare through new research initiative","accessed":"2026-11-19","published":"2026-06-22"}],"notes":"Funded by Coefficient Giving. Successor to the ''Improving Farmed Fish Welfare in Asia'' project (late 2022-2025), which funded fifteen research projects. A third funding call was launched with a webinar on 2026-09-03; the online course became available in Vietnamese and Thai on 2026-10-24. No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('equalia','Equalia','organisation',NULL,'advocacy-campaigns','aquatic','unclear','{"aliases":[],"categories":["advocacy-campaigns"],"species":["farmed-fish"],"regions":["europe"],"countries":["ES"],"interventions":["producer-engagement","farm-practices"],"approach":"welfare-reform","summary":"Spanish animal welfare NGO. With Compassion in World Farming and the aquaculture industry association APROMAR it published the first general guidelines on the welfare of farmed fish in Spain in October 2022, with sea bass and sea bream guidance planned next.","website":null,"hq":"Spain","founded":null,"sources":[{"url":"https://eurogroupforanimals.org/news/first-fish-welfare-guidelines-set-course-spanish-aquaculture","title":"First fish welfare guidelines set course for Spanish aquaculture","accessed":"2026-11-19","published":"2022-10-28"}],"notes":"Verified only through the 2022 Eurogroup for Animals article. The organisation''s own site (equalia.org) did not resolve from the research environment on 2026-11-19, so website, current status and current aquatic work are unconfirmed. ''Spanish NGO'' is from general knowledge of the organisation, not the article.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('globalgap','GLOBALG.A.P.','organisation',NULL,'welfare-science','aquatic','active','{"aliases":["GLOBALGAP","EUREPGAP","IFA Aquaculture"],"categories":["welfare-science"],"species":["farmed-fish","crustaceans"],"regions":["global"],"countries":["DE"],"interventions":["certification-standards"],"approach":"neutral-infrastructure","summary":"Farm assurance standard-setter based in Cologne. Its Integrated Farm Assurance standard for aquaculture (v6) lists farmed aquatic species welfare, management and husbandry among its core topics and covered 35 aquatic species in 31 countries at the end of 2024.","website":"https://globalgap.org/","hq":"Germany","founded":"1997","sources":[{"url":"https://globalgap.org/what-we-offer/solutions/ifa-aquaculture/","title":"Integrated Farm Assurance for aquaculture | GLOBALG.A.P.","accessed":"2026-11-19","published":null},{"url":"https://globalgap.org/about/","title":"About GLOBALG.A.P.","accessed":"2026-11-19","published":null}],"notes":"Began in 1997 as the retailer initiative EUREPGAP; first aquaculture standard (salmonids) launched October 2004. The page fetched does not detail specific welfare criteria such as stunning. Its RSS feed has no items.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('global-seafood-alliance','Global Seafood Alliance','organisation',NULL,'welfare-science','aquatic','active','{"aliases":["GSA","Best Aquaculture Practices","BAP","Best Seafood Practices"],"categories":["welfare-science"],"species":["farmed-fish","crustaceans","wild-fish"],"regions":["global"],"countries":["US"],"interventions":["certification-standards","education"],"approach":"neutral-infrastructure","summary":"International membership NGO for responsible seafood practices, based in Portsmouth, New Hampshire. It runs the Best Aquaculture Practices (BAP) and Best Seafood Practices (BSP) certification programmes and lists animal health and welfare among the issues it convenes on.","website":"https://www.globalseafood.org/","hq":"United States","founded":null,"sources":[{"url":"https://www.globalseafood.org/about/","title":"Global Seafood Alliance: Advancing Responsible Seafood","accessed":"2026-11-19","published":null},{"url":"https://www.globalseafood.org/contact/","title":"Contact Us - Global Seafood Alliance","accessed":"2026-11-19","published":null}],"notes":"Formerly the Global Aquaculture Alliance (not confirmed on the pages fetched). The About page reports 4,000+ BAP and BSP certified facilities. Specific BAP welfare requirements were not reviewed.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('naturland','Naturland','organisation',NULL,'welfare-science','aquatic','active','{"aliases":[],"categories":["welfare-science"],"species":["farmed-fish","crustaceans"],"regions":["global","europe"],"countries":["DE"],"interventions":["certification-standards"],"approach":"welfare-reform","summary":"German organic farming association with international certification. Its organic aquaculture standards, first published in 1996, set stocking limits such as 10 kg/m3 for salmon, a compulsory slaughter protocol including stunning, and a ban on eyestalk ablation in prawns.","website":"https://www.naturland.de/en/","hq":"Germany","founded":"1982","sources":[{"url":"https://www.naturland.de/en/naturland/what-we-stand-for/animal-welfare/fish-prawns.html","title":"Fish & Prawns - Naturland","accessed":"2026-11-19","published":null},{"url":"https://www.naturland.de/en/naturland/who-we-are.html","title":"Who we are - Naturland","accessed":"2026-11-19","published":null}],"notes":"Based in Gräfelfing. Founded regionally in 1982 and working internationally since 1986. Also has a sustainable capture fisheries standard. No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('soil-association','Soil Association','organisation',NULL,'welfare-science','aquatic','active','{"aliases":[],"categories":["welfare-science"],"species":["farmed-fish"],"regions":["uk"],"countries":["GB"],"interventions":["certification-standards"],"approach":"welfare-reform","summary":"UK food and farming charity that sets organic standards. After a review of organic farmed salmon it announced in November 2026 that it will withdraw from setting standards for organic salmon, citing a lack of evidence of good enough outcomes for the fish.","website":"https://www.soilassociation.org/","hq":"United Kingdom","founded":null,"sources":[{"url":"https://www.soilassociation.org/our-standards/standards-innovation-our-work/uk-organic-salmon-standards/","title":"UK organic salmon standards | Soil Association","accessed":"2026-11-19","published":null},{"url":"https://www.onekind.org/blog/latest-blow-to-destructive-salmon-farming-industry-18-11-26","title":"Latest blow to destructive salmon farming industry (OneKind)","accessed":"2026-11-19","published":"2026-11-17"}],"notes":"Soil Association Certification will honour existing contracts and certify to the organic regulations while a withdrawal timetable is agreed with the sector. Whether it still sets standards for other aquaculture species was not confirmed. Founding year not verified; no RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('global-animal-partnership','Global Animal Partnership','organisation',NULL,'welfare-science','aquatic','active','{"aliases":["G.A.P."],"categories":["welfare-science"],"species":["farmed-fish","farmed-animals","chickens","pigs","cows"],"regions":["north-america"],"countries":["US"],"interventions":["certification-standards","farm-practices","producer-engagement"],"approach":"welfare-reform","summary":"US non-profit that develops and publishes welfare standards for farm animals, structured as a five-tier ''Five Step'' animal welfare programme, and labels products from farms certified to those standards. Founded in 2008 with assistance from Whole Foods Market. Its standards include Farmed Atlantic Salmon Standards v1.0 and Farmed Atlantic Salmon Slaughter Facility Standards v1.0, issued in June 2022.","website":"https://globalanimalpartnership.org/","hq":"United States","founded":"2008","sources":[{"url":"https://globalanimalpartnership.org/standards-3/","title":"Standards 2026 - Global Animal Partnership","accessed":"2026-11-19","published":null},{"url":"https://globalanimalpartnership.org/wp-content/uploads/2022/06/G.A.P.Animal-Welfare-Standards-for-Farmed-Atlantic-Salmon-v1.0.20220615.pdf","title":"G.A.P. Animal Welfare Standards for Farmed Atlantic Salmon v1.0","accessed":"2026-11-19","published":"2022-06-15"},{"url":"https://globalanimalpartnership.org/","title":"Global Animal Partnership (homepage)","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/Global_Animal_Partnership","title":"Global Animal Partnership - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"501(c)(3). The salmon standard PDF link was found on the standards page but the PDF itself was not read. Founding year and headquarters city not verified. Its RSS feed has no items. | Founding details from Wikipedia. Feed URL returned no items.","merged_from":["global-animal-partnership"]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('ace-aquatec','Ace Aquatec','organisation',NULL,'welfare-technology','aquatic','active','{"aliases":[],"categories":["welfare-technology"],"species":["farmed-fish","crustaceans"],"regions":["global","uk"],"countries":["GB","NO","CA","CL"],"interventions":["humane-slaughter","farm-practices","data-tools"],"approach":"neutral-infrastructure","summary":"Dundee-based aquaculture technology company. It makes in-water electric stunners (A-HSU) for salmon, trout, yellowtail, tilapia and other species, plus biomass and harvest cameras, a water-only sea lice removal system and acoustic predator deterrents.","website":"https://www.aceaquatec.com/","hq":"United Kingdom","founded":null,"sources":[{"url":"https://www.aceaquatec.com/","title":"Aquaculture Technologies With A Welfare Focus | Ace Aquatec","accessed":"2026-11-19","published":null},{"url":"https://aceaquatec.com/our-story","title":"Our story | Ace Aquatec","accessed":"2026-11-19","published":null},{"url":"https://aceaquatec.com/our-company","title":"Our company | Ace Aquatec","accessed":"2026-11-19","published":null}],"notes":"Commercial supplier; welfare claims are the company''s own. Offices in Scotland, Norway, Canada and Chile; says it is active in 26 countries and has developed these technologies for more than 20 years. Its site meta description also lists shrimp stunning. News at /news-and-resources/news; no RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('optimar','Optimar','organisation',NULL,'welfare-technology','aquatic','active','{"aliases":[],"categories":["welfare-technology"],"species":["farmed-fish","wild-fish","crustaceans"],"regions":["europe","global"],"countries":["NO"],"interventions":["humane-slaughter","farm-practices"],"approach":"neutral-infrastructure","summary":"Norwegian maker of fish handling and processing equipment for fishing vessels, aquaculture and onshore plants, working with the seafood industry since 1978. It supplies electrical stunning systems and reports work with Shrimp Welfare Project and Crustacean Compassion.","website":"https://optimarglobal.com/en","hq":"Norway","founded":"1978","sources":[{"url":"https://optimarglobal.com/en/fish-welfare","title":"Fish welfare | Optimar","accessed":"2026-11-19","published":null}],"notes":"Commercial supplier based at Valderøya; welfare claims are the company''s own. Specific stunner model names were not listed on the page fetched. No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('aqui-s','AQUI-S New Zealand','organisation',NULL,'welfare-technology','aquatic','active','{"aliases":["AQUI-S","AQUI-S New Zealand Ltd"],"categories":["welfare-technology"],"species":["farmed-fish"],"regions":["oceania","global"],"countries":["NZ"],"interventions":["humane-slaughter","farm-practices"],"approach":"neutral-infrastructure","summary":"Company in Lower Hutt, New Zealand, that makes AQUI-S aquatic anaesthetics, used to sedate fish and reduce stress during handling, transport and ''rested'' low-stress harvesting. It also sells an iki jime tool and publishes material on fish pain and slaughter welfare.","website":"https://www.aqui-s.com/","hq":"New Zealand","founded":null,"sources":[{"url":"https://www.aqui-s.com/aqui-s-welfare","title":"Fish Welfare | AQUI-S","accessed":"2026-11-19","published":null}],"notes":"Commercial supplier; welfare claims are the company''s own. The site has contact pages for Europe, USA/Canada, Australia, Chile, South Africa, Vietnam, Malaysia/Singapore and the UAE, but regulatory approvals by country were not listed. Founding year not stated; no RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('aquabyte','Aquabyte','organisation',NULL,'welfare-technology','aquatic','active','{"aliases":["Aquabyte AS"],"categories":["welfare-technology"],"species":["farmed-fish"],"regions":["europe"],"countries":["NO"],"interventions":["data-tools","farm-practices"],"approach":"neutral-infrastructure","summary":"Norwegian company supplying underwater cameras and AI image analysis to fish farms. Its Welfare product automatically tracks 17 welfare indicators for salmon, coho and trout, such as skin and fin damage and eye health, building on the Laksvel protocol.","website":"https://aquabyte.ai/","hq":"Norway","founded":null,"sources":[{"url":"https://aquabyte.ai/en/products/welfare","title":"Welfare | Aquabyte","accessed":"2026-11-19","published":null}],"notes":"Commercial supplier based in Laksevåg (Bergen); product claims are the company''s own. Founding year and countries of operation not stated on the page fetched. No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('eurcaw-aqua','EURCAW-Aqua','organisation',NULL,'welfare-science','aquatic','active','{"aliases":["EU Reference Centre for the Welfare of Aquatic Animals","EURCAW Aqua"],"categories":["welfare-science","policy-law"],"species":["farmed-fish","crustaceans","cephalopods"],"regions":["europe"],"countries":["GR","ES","CZ"],"interventions":["research","education","capacity-building"],"approach":"research","summary":"EU Reference Centre for the Welfare of Aquatic Animals, created on 17 January 2024 under Regulation (EU) 2017/625. It covers fish, cephalopods and decapods, prioritising farmed species important to European aquaculture, and provides expert resources, training and events.","website":"https://www.eurcaw-aqua.eu/","hq":null,"founded":"2024","sources":[{"url":"https://www.eurcaw-aqua.eu/","title":"EURCAW Aqua - Home","accessed":"2026-11-19","published":null}],"notes":"Team bios point to the University of Crete (Greece), Universitat Autònoma de Barcelona (Spain) and the Biology Centre of the Czech Academy of Sciences; the full consortium list and lead institution were not confirmed on the homepage. Recent items include a rainbow trout welfare roadshow in Brescia, Italy (5-6 November 2026).","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('crustawohl','CrustaWohl','programme',NULL,'welfare-science','aquatic','active','{"aliases":[],"categories":["welfare-science"],"species":["crustaceans"],"regions":["europe"],"countries":["DE"],"interventions":["research","farm-practices"],"approach":"research","summary":"German research project of IGB Berlin and the Alfred Wegener Institute developing an assessment system for animal welfare and health in shrimp farming. It studies chronic stress in shrimp in recirculating systems to derive behavioural and physiological indicators.","website":"https://www.igb-berlin.de/en/project/crustawohl","hq":"Germany","founded":null,"sources":[{"url":"https://www.igb-berlin.de/en/project/crustawohl","title":"CrustaWohl | IGB","accessed":"2026-11-19","published":null},{"url":"https://www.shrimpwelfareproject.org/blog/uncovering-chronic-stress-in-crustaceans-a-project-partnership-between-swp-and-crustawohl","title":"Uncovering Chronic Stress in Crustaceans: A Project Partnership Between SWP and CrustaWohl","accessed":"2026-11-19","published":"2024-12-19"}],"notes":"IGB names Oceanloop, the Aquaculture Stewardship Council and the Albert Schweitzer Foundation''s Aquaculture Welfare Standards Initiative as cooperation partners; Shrimp Welfare Project signed a collaboration agreement in late November 2024. An IGB manual on welfare monitoring of whiteleg shrimp is linked from the project page. Funder and end date not confirmed on fetched pages.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('humane-slaughter-association','Humane Slaughter Association','organisation',NULL,'welfare-science','aquatic','active','{"aliases":["Council of Justice to Animals"],"categories":["welfare-science","funding","welfare-technology"],"species":["farmed-fish","farmed-animals"],"regions":["uk","global"],"countries":["GB"],"interventions":["humane-slaughter","research","grantmaking","education","capacity-building"],"approach":"welfare-reform","summary":"UK charity, founded in 1911, that supports research, training and technical guidance to improve animal welfare during transport and slaughter. Its fish work has included demonstrating and funding research on electrical stunning of farmed trout and sea bass.","website":"https://www.hsa.org.uk/","hq":"United Kingdom","founded":"1911","sources":[{"url":"https://en.wikipedia.org/wiki/Humane_Slaughter_Association","title":"Humane Slaughter Association - Wikipedia","accessed":"2026-11-19","published":null},{"url":"https://scienceforanimalwelfare.org/award/large-research-grants/","title":"Large Research Grants - Science for Animal Welfare","accessed":"2026-11-19","published":null}],"notes":"Verified via Wikipedia only: hsa.org.uk returned 403 (bot challenge) to automated requests. Charitable incorporated organisation no. 1159690, based in Wheathampstead. Work on crustaceans and cephalopods was not confirmed in the source. The common abbreviation ''HSA'' is omitted from aliases because the map already uses it for the Hunt Saboteurs Association. | Its own site (hsa.org.uk) returned HTTP 403 to automated requests on 2026-11-19, so this profile rests on Wikipedia and on Science for Animal Welfare, which refers applicants working on farmed animal transport, markets or slaughter to HSA grants. Current grant schemes, amounts, deadlines, species covered (for example fish and crustaceans) and international reach were not verified: check the HSA site. Founded in 1911 as the Council of Justice to Animals. Usually abbreviated HSA, which the Hunt Saboteurs Association also uses, so the abbreviation is not listed as an alias. Also profiled in data/research/aquatic-gaps-entities.json under the same id; this entry adds its role as a research funder.","merged_from":["humane-slaughter-association"]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('aquatic-animal-law-initiative','Aquatic Animal Law Initiative','programme','lewis-clark-center-for-animal-law-studies','policy-law','aquatic','unclear','{"aliases":["AALI"],"categories":["policy-law"],"species":["farmed-fish","wild-fish","animals-in-research"],"regions":["north-america"],"countries":["US"],"interventions":["litigation","legislation-policy","research","education"],"approach":"mixed","summary":"Initiative launched in 2016 at Lewis & Clark Law School''s animal law clinic to advance the interests of aquatic animals through the legal system, public education and law reform, including the exclusion of fish from the US Animal Welfare Act and the effects of aquaculture.","website":"https://law.lclark.edu/centers/animal_law_studies/animal_law_clinics/aali/","hq":"United States","founded":"2016","sources":[{"url":"https://law.lclark.edu/centers/animal_law_studies/animal_law_clinics/aali/","title":"Aquatic Animal Law Initiative - Lewis & Clark Law School","accessed":"2026-11-19","published":null},{"url":"https://law.lclark.edu/centers/animal_law_studies/news-and-events/aquatic-animals/","title":"Aquatic Animals - Center for Animal Law Studies","accessed":"2026-11-19","published":null}],"notes":"Co-hosted World Aquatic Animal Day (3 April; third annual edition in 2022) with the Animal Law Clinic. The AALI page carries no dated items, and search results indicate its founding director moved in 2022 to George Washington University, where an Aquatic Animal Law Project now exists (not verified on a fetched page) - current activity at Lewis & Clark is unconfirmed.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('norwegian-fish-health-report','Fish Health Report (Norwegian Veterinary Institute)','resource',NULL,'welfare-science','aquatic','active','{"aliases":["Fiskehelserapporten","Norwegian Fish Health Report"],"categories":["welfare-science"],"species":["farmed-fish"],"regions":["europe"],"countries":["NO"],"interventions":["research","data-tools"],"approach":"research","summary":"Annual report by the Norwegian Veterinary Institute on the main health challenges in Norwegian aquaculture, including mortality trends for farmed salmon and cod and a survey of causes of death. The 2025 edition adds a chapter on climate change and fish health.","website":"https://www.vetinst.no/en/reports-and-publications/reports","hq":"Norway","founded":null,"sources":[{"url":"https://www.vetinst.no/rapporter-og-publikasjoner/rapporter/2026/fish-health-report-2025","title":"Fish Health Report 2025 - Norwegian Veterinary Institute","accessed":"2026-11-19","published":null},{"url":"https://www.vetinst.no/en/reports-and-publications/reports","title":"Reports - Norwegian Veterinary Institute","accessed":"2026-11-19","published":null}],"notes":"The 2025 edition reports salmon mortality slightly down on 2024 and 2023, cod mortality up, and injuries after delousing and infectious disease as the leading stated causes of death for salmon in sea cages. Editions back to at least 2006 are listed on the reports page. Exact publication date of the 2025 edition not stated (URL path: 2026).","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('lse-sentience-review-cephalopods-decapods','Review of the Evidence of Sentience in Cephalopod Molluscs and Decapod Crustaceans','resource',NULL,'welfare-science','aquatic','active','{"aliases":["LSE sentience report","Birch report"],"categories":["welfare-science","policy-law"],"species":["crustaceans","cephalopods"],"regions":["uk"],"countries":["GB"],"interventions":["research","legislation-policy"],"approach":"research","summary":"November 2021 report by an LSE-led team, commissioned by Defra, reviewing over 300 studies on sentience in cephalopods and decapod crustaceans and the welfare implications of commercial practices. It recommends treating both groups as sentient in UK animal welfare law.","website":"https://www.lse.ac.uk/business/consulting/reports/review-of-the-evidence-of-sentiences-in-cephalopod-molluscs-and-decapod-crustaceans","hq":"United Kingdom","founded":"2021","sources":[{"url":"https://www.lse.ac.uk/business/consulting/reports/review-of-the-evidence-of-sentiences-in-cephalopod-molluscs-and-decapod-crustaceans","title":"Review of the Evidence of Sentience in Cephalopod Molluscs and Decapod Crustaceans","accessed":"2026-11-19","published":null}],"notes":"Dated November 2021 on the LSE page. Published open access (CC-BY 4.0) through LSE Consulting; peer-reviewed by two external experts selected by Defra. ''Birch report'' is an informal name after the lead author. A static publication; ''active'' here means it is available and in use, not updated.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('animal-activism-collective','Animal Activism Collective','organisation',NULL,'direct-action','funding','active','{"aliases":[],"categories":["direct-action","movement-infrastructure"],"species":["all-animals","crustaceans"],"regions":["north-america","europe"],"countries":["US"],"interventions":["capacity-building","education","protest","corporate-campaigns"],"approach":"abolitionist","summary":"Trains and supports grassroots animal rights activists through a free one-to-one mentorship programme, online livestreams and a podcast, in-person convergences, a directory of activist groups and a grassroots campaigns training programme.","website":"https://www.animalactivismcollective.org/","hq":null,"founded":null,"sources":[{"url":"https://www.animalactivismcollective.org/about","title":"Animal Activism Collective - Taking Action for Change (About page)","accessed":"2026-11-19","published":null},{"url":"https://www.animalactivismcollective.org/","title":"Animal Activism Collective - Taking Action for Change","accessed":"2026-11-19","published":null},{"url":"https://funds.effectivealtruism.org/grants","title":"Grants Database | Effective Altruism Funds","accessed":"2026-11-19","published":null}],"notes":"The site does not state a headquarters or founding year; it lists convergences in Miami and Chicago (US). The crustacean and Europe tags come from the EA Animal Welfare Fund grant record (2025 Q4: grassroots communities in European cities pressing for shrimp welfare policies), not from the site, whose campaigns page is script-rendered and could not be read. It abbreviates itself AAC, which Animal Advocacy Careers also uses, so the abbreviation is not listed as an alias.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('animal-law-italia','Animal Law Italia','organisation',NULL,'policy-law','funding','active','{"aliases":["ALI (Animal Law Italia) ETS"],"categories":["policy-law","advocacy-campaigns"],"species":["all-animals","crustaceans","companion-animals","wild-animals"],"regions":["europe"],"countries":["IT"],"interventions":["legislation-policy","public-awareness","education","research"],"approach":"mixed","summary":"Italian non-profit association, founded in 2016, that promotes stronger legal protection for animals and respect for existing laws. It runs the \"Dalla parte dei crostacei\" campaign on the treatment of lobsters and crabs, a legal reporting service, a law journal and education projects.","website":"https://ali.ong/","hq":"Italy","founded":"2016","sources":[{"url":"https://ali.ong/chi-siamo/","title":"Chi siamo, i nostri obiettivi e cosa facciamo - ALI - Animal Law Italia","accessed":"2026-11-19","published":null},{"url":"https://ali.ong/","title":"ALI (Animal Law Italia) ETS – Vogliamo leggi eque per gli animali","accessed":"2026-11-19","published":null},{"url":"https://funds.effectivealtruism.org/grants","title":"Grants Database | Effective Altruism Funds","accessed":"2026-11-19","published":null}],"notes":"Its own short name is ALI, which Aquatic Life Institute also uses, so \"ALI\" alone is not listed as an alias. Site and feed are in Italian. The older domain animallaw.it did not respond; animal-law.it redirects to ali.ong. The EA Funds grants database (CSV at funds.effectivealtruism.org/api/grants) lists three Animal Welfare Fund grants to it: 2022 Q3, 2024 Q3 and 2026 Q1, all for crustacean or aquatic animal welfare.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('awash','AWASH','organisation',NULL,'welfare-science','funding','active','{"aliases":["Aquatic Welfare for African Sustainability and Health","Aquatic Welfare for African Sustainability and Health LBG"],"categories":["welfare-science","advocacy-campaigns"],"species":["farmed-fish"],"regions":["africa"],"countries":["GH"],"interventions":["research","farm-practices","producer-engagement"],"approach":"welfare-reform","summary":"Works to improve the welfare of farmed Nile tilapia in Ghana. It has published a literature review, a scoping report based on visits to cage farms on Lake Volta and an intervention comparison, and is piloting egg disinfection at hatcheries to reduce disease and early mortality.","website":null,"hq":null,"founded":null,"sources":[{"url":"https://forum-bots.effectivealtruism.org/posts/Ng2xJfeRLJtAZoK5Y/awash-intervention-selection-improving-farmed-fish-welfare","title":"AWASH: Intervention Selection - Improving farmed fish welfare in Ghana — EA Forum","accessed":"2026-11-19","published":null},{"url":"https://forum-bots.effectivealtruism.org/posts/NJpxXEvkwhG93qcwE/awash-ghana-scoping-report","title":"AWASH: Ghana scoping report — EA Forum","accessed":"2026-11-19","published":"2026-06-09"},{"url":"https://animalcharityevaluators.org/blog/announcing-round-11-movement-grants/","title":"Announcing our latest Movement Grants - Animal Charity Evaluators","accessed":"2026-11-19","published":"2026-09-29"}],"notes":"No website of its own was found; profile is built from its own EA Forum reports and the ACE grant announcement, which gives the legal name. Headquarters and founding year are not stated in those sources.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('bbsrc','Biotechnology and Biological Sciences Research Council','funder',NULL,'funding','funding','active','{"aliases":["BBSRC","BBSRC (UKRI)","UKRI-BBSRC"],"categories":["funding","welfare-science"],"species":["farmed-animals","farmed-fish","animals-in-research","companion-animals"],"regions":["uk"],"countries":["GB"],"interventions":["grantmaking","research"],"approach":"neutral-infrastructure","summary":"UK public research council for bioscience, part of UK Research and Innovation. Listed here as a funder: its \"welfare of managed animals\" priority supports UK research on farmed, laboratory and companion animal welfare through standard research grants of up to £2 million, open at any time.","website":"https://www.ukri.org/councils/bbsrc/","hq":"United Kingdom","founded":"1994","sources":[{"url":"https://www.ukri.org/what-we-do/browse-our-areas-of-investment-and-support/welfare-of-managed-animals/","title":"Welfare of managed animals – UKRI","accessed":"2026-11-19","published":null},{"url":"https://www.ukri.org/councils/bbsrc/","title":"Biotechnology and Biological Sciences Research Council (BBSRC) – UKRI","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/Biotechnology_and_Biological_Sciences_Research_Council","title":"Biotechnology and Biological Sciences Research Council - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"A general bioscience funder; animal welfare is one priority area among many. The area page lists stunning of aquatic species and welfare indicators among example topics, and says BBSRC co-funds the Animal Welfare Research Network with Defra. Founding year and Swindon base are from Wikipedia.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('blueperch','BluePerch','funder',NULL,'funding','funding','active','{"aliases":[],"categories":["funding"],"species":["farmed-animals","wild-animals"],"regions":["global"],"countries":[],"interventions":["grantmaking"],"approach":"neutral-infrastructure","summary":"New fund for farmed animal advocacy projects, with a stated interest in early-stage projects, time-sensitive policy windows and work other funders miss. It expects most grants to be about USD 5,000-100,000, with open, rolling applications from mid-2027; expressions of interest are open now.","website":"https://www.blueperch.org/","hq":null,"founded":null,"sources":[{"url":"https://www.blueperch.org/about","title":"About (BluePerch)","accessed":"2026-11-19","published":null},{"url":"https://www.blueperch.org/","title":"BluePerch · Funding for high-impact farmed animal advocacy projects","accessed":"2026-11-19","published":null}],"notes":"Despite the name, not a fish-specific fund: scope is farmed animals (chickens, fish, pigs, insects, shrimp), wild animals and comparable neglected groups; it expects to exclude diet-change work, alternative proteins, pet welfare, direct care and conservation. Fiscally sponsored by Anti Entropy (US 501(c)(3)). Says it hopes to fund anywhere in the world, with the probable exception of China, and that timelines may change. Not yet making grants as of 2026-11-19. Its Atom feed returned no entries.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('center-for-responsible-seafood','The Center for Responsible Seafood','organisation',NULL,'welfare-technology','funding','active','{"aliases":["TCRS","Center for Responsible Seafood","Responsible Aquaculture Foundation"],"categories":["welfare-technology","welfare-science"],"species":["farmed-fish","crustaceans","wild-fish"],"regions":["global"],"countries":["US"],"interventions":["research","humane-slaughter","certification-standards","education","producer-engagement"],"approach":"research","summary":"US non-profit, known as the Responsible Aquaculture Foundation from 2009 until 2021, that runs knowledge-sharing, applied research and industry programmes on seafood production. Its fish welfare project evaluates humane slaughter technologies and feeds results into certification standards.","website":"https://responsibleseafood.org/","hq":"United States","founded":"2009","sources":[{"url":"https://www.responsibleseafood.org/about","title":"About TCRS – The Center for Responsible Seafood","accessed":"2026-11-19","published":null},{"url":"https://responsibleseafood.org/applied-research/","title":"Applied Research – The Center for Responsible Seafood","accessed":"2026-11-19","published":null},{"url":"https://responsibleseafood.org/","title":"The Center for Responsible Seafood","accessed":"2026-11-19","published":null}],"notes":"An industry-facing seafood organisation, not an advocacy group; founders and board come from the aquaculture industry. The site says its fish welfare work has been supported by Open Philanthropy (now Coefficient Giving) since 2018 and that results go to the Global Seafood Alliance for its Best Aquaculture Practices standards. A white paper on shrimp welfare at reproduction and slaughter appears in its feed (October 2026). Grant records use the id the-center-for-responsible-seafood.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('european-commission','European Commission (Horizon Europe)','funder',NULL,'funding','funding','active','{"aliases":["European Commission","Horizon Europe"],"categories":["funding","policy-law"],"species":["farmed-animals","farmed-fish"],"regions":["europe"],"countries":[],"interventions":["grantmaking","research","legislation-policy"],"approach":"neutral-infrastructure","summary":"Executive body of the European Union. Listed here as a public funder: Horizon Europe (2021-2027, indicative EUR 93.5 billion) funds research that includes farmed and aquatic animal welfare under its food and agriculture cluster and co-funds the European Partnership on Animal Health and Welfare.","website":"https://commission.europa.eu/index_en","hq":"Belgium","founded":null,"sources":[{"url":"https://research-and-innovation.ec.europa.eu/funding/funding-opportunities/funding-programmes-and-open-calls/horizon-europe_en","title":"Horizon Europe - Research and innovation - European Commission","accessed":"2026-11-19","published":null},{"url":"https://research-and-innovation.ec.europa.eu/funding/funding-opportunities/funding-programmes-and-open-calls/horizon-europe/cluster-6-food-bioeconomy-natural-resources-agriculture-and-environment_en","title":"Cluster 6: Food, Bioeconomy, Natural Resources, Agriculture and Environment - Research and innovation","accessed":"2026-11-19","published":null},{"url":"https://www.eupahw.eu/about-us","title":"EUPAHW - European Partnership on Animal Health and Welfare","accessed":"2026-11-19","published":null},{"url":"https://food.ec.europa.eu/animals/animal-welfare_en","title":"Animal welfare - Food Safety - European Commission","accessed":"2026-11-19","published":null}],"notes":"A general research funder and regulator, not an animal welfare funder as such: welfare appears as one topic within much larger programmes. Calls are published on the EU Funding & Tenders portal and are open to consortia, mostly of research bodies. The Commission also proposes EU animal welfare legislation and designates EU reference centres for animal welfare.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('fai-farms','FAI Farms','organisation',NULL,'welfare-science','funding','active','{"aliases":["FAI","FAI Farms Ltd"],"categories":["welfare-science","welfare-technology"],"species":["farmed-fish","crustaceans","chickens","cows","farmed-animals"],"regions":["global"],"countries":["GB","BR","VN"],"interventions":["producer-engagement","farm-practices","education","data-tools","research"],"approach":"welfare-reform","summary":"UK-based research, data and consultancy company that works with livestock and aquaculture supply chains on welfare and sustainability. Its aquaculture work includes a tilapia welfare assessment app and online Tilapia and Shrimp Hubs with free training for farmers in several languages.","website":"https://www.faifarms.com/","hq":"United Kingdom","founded":"2000","sources":[{"url":"https://www.faifarms.com/","title":"Homepage - FAI Farms","accessed":"2026-11-19","published":null},{"url":"https://www.faifarms.com/products/tilapia-welfare/","title":"Tilapia Welfare App - FAI Farms","accessed":"2026-11-19","published":null},{"url":"https://www.faifarms.com/fai-puts-welfare-front-and-centre-of-shrimp-production/","title":"FAI puts welfare front and centre of shrimp production - FAI Farms","accessed":"2026-11-19","published":null},{"url":"https://find-and-update.company-information.service.gov.uk/company/04131435","title":"FAI FARMS LIMITED overview - Companies House","accessed":"2026-11-19","published":null}],"notes":"A private company (England and Wales no. 04131435) that sells consultancy, data and training services to food businesses; it receives philanthropic grants for its aquaculture welfare training. \"Founded\" is the Companies House incorporation date (28 December 2000). Country tags reflect its UK base and the Brazil and Vietnam projects named in grant records and on its site.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('fundacion-derecho-y-defensa-animal','Fundación Derecho y Defensa Animal','organisation',NULL,'policy-law','funding','active','{"aliases":[],"categories":["policy-law","advocacy-campaigns"],"species":["farmed-fish","cephalopods","crustaceans","chickens","companion-animals","all-animals"],"regions":["latin-america"],"countries":["CL"],"interventions":["legislation-policy","research","corporate-campaigns","public-awareness","education"],"approach":"mixed","summary":"Chilean foundation of lawyers that works for animals through legislative advocacy, legal advice and research. Its campaigns seek a ban on octopus farms, a ban on selling and boiling live lobsters, and humane slaughter standards for farmed fish in Chilean aquaculture law.","website":"https://fundaciondyda.com/","hq":"Chile","founded":null,"sources":[{"url":"https://www.fundaciondyda.com","title":"Fundación Derecho y Defensa Animal","accessed":"2026-11-19","published":null},{"url":"https://www.aquaticwelfare.org","title":"Aquatic Welfare | acuicultura, animal, acuaticos","accessed":"2026-11-19","published":null},{"url":"https://forum-bots.effectivealtruism.org/posts/pik5Br8EzxnEg5vPw/new-aquaculture-law-in-chile-now-is-the-time","title":"New Aquaculture Law in Chile: Now is the time! — EA Forum","accessed":"2026-11-19","published":"2025-02-25"},{"url":"https://www.diarioconstitucional.cl/2025/02/25/fundacion-derecho-y-defensa-animal-llama-a-prohibir-el-cultivo-de-pulpos-en-la-nueva-ley-de-acuicultura/","title":"Fundación Derecho y Defensa Animal llama a prohibir el cultivo de pulpos en la nueva Ley de Acuicultura - Diario Constitucional","accessed":"2026-11-19","published":"2025-02-25"}],"notes":"Its site says it has worked for 10 years but gives no founding year. aquaticwelfare.org is its project site on Chilean aquaculture law (linked from its own EA Forum post). Other campaigns on its site: a ban on dog racing and a cage-free egg campaign aimed at LATAM Airlines. Its RSS feeds returned no items.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('kickstarting-for-good','Kickstarting for Good','funder','proveg-international','incubation-careers','funding','active','{"aliases":["K4G","Kickstarting For Good Incubator"],"categories":["incubation-careers","funding"],"species":["farmed-animals"],"regions":["global"],"countries":["DE"],"interventions":["capacity-building","grantmaking","careers-talent"],"approach":"neutral-infrastructure","summary":"Incubator run by ProVeg International: an 18-week programme, with two in-person weeks in Berlin, for non-profits and initiatives working towards a plant-forward food system. Graduates receive seed grants (over USD 1 million in total in 2026); it also seeds the Movement Infrastructure Lab grants.","website":"https://kickstartingforgood.org/","hq":"Germany","founded":null,"sources":[{"url":"https://kickstartingforgood.org/","title":"Kickstarting For Good Incubator - Kickstarting For Good","accessed":"2026-11-19","published":null},{"url":"https://kickstartingforgood.org/incubator/frequently-asked-questions/","title":"Frequently Asked Questions - Kickstarting For Good","accessed":"2026-11-19","published":null},{"url":"https://kickstartingforgood.org/legal-disclosure/","title":"Legal disclosure - Kickstarting For Good","accessed":"2026-11-19","published":null},{"url":"https://forum-bots.effectivealtruism.org/posts/CD2B4E52EhGtdsZgi/why-i-m-launching-a-movement-infrastructure-lab-a-request","title":"Why I’m launching a Movement Infrastructure Lab: a request for proposals — EA Forum","accessed":"2026-11-19","published":"2026-10-17"}],"notes":"Primarily an incubation programme rather than a grant-maker: funding goes to people accepted into the programme (every 2026 graduate receives at least USD 10,000, up to USD 100,000 on pitch day) plus development grants of up to USD 12,000 for some applicants not admitted. The site''s legal disclosure names ProVeg International, Inc. Applicants worldwide are eligible; the in-person weeks are in Berlin, which is the basis for the Germany tags (no headquarters is stated). Kind is kept as \"funder\" to match the existing stub; \"programme\" would also fit.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('mtu-loomus','MTÜ Loomus','organisation',NULL,'advocacy-campaigns','funding','active','{"aliases":["Loomus"],"categories":["advocacy-campaigns","policy-law"],"species":["fur-animals","farmed-fish","farmed-animals","companion-animals","all-animals"],"regions":["europe"],"countries":["EE"],"interventions":["legislation-policy","public-awareness","protest","diet-change"],"approach":"mixed","summary":"Estonian animal advocacy organisation, founded in 2014, that works to raise the profile of animal issues in Estonia, promote animal-friendly behaviour and consumption, and shape animal protection policy. Its work includes fur farming, fish and other aquatic animals, and veganism.","website":"https://loomus.ee/","hq":"Estonia","founded":"2014","sources":[{"url":"https://loomus.ee/visioon/","title":"Loomade eestkoste - Loomakaitse - MTÜ Loomus","accessed":"2026-11-19","published":null},{"url":"https://loomus.ee/en/news/","title":"News - Loomus","accessed":"2026-11-19","published":null},{"url":"https://loomus.ee/kalad/","title":"Armas Kala (MTÜ Loomus)","accessed":"2026-11-19","published":null},{"url":"https://funds.effectivealtruism.org/grants","title":"Grants Database | Effective Altruism Funds","accessed":"2026-11-19","published":null}],"notes":"The main site and feed are in Estonian; the English feed (https://loomus.ee/en/feed/) is valid but its newest item is from September 2024. A November 2026 feed item calls for binding requirements to protect aquatic animals rather than expansion of aquaculture. The site was intermittently slow to respond.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('national-lottery-community-fund','The National Lottery Community Fund','funder',NULL,'funding','funding','active','{"aliases":["National Lottery Community Fund","Big Lottery Fund"],"categories":["funding"],"species":[],"regions":["uk"],"countries":["GB"],"interventions":["grantmaking"],"approach":"neutral-infrastructure","summary":"UK public body that distributes money raised by National Lottery players to charities and community projects across the UK. A general community funder, not an animal welfare funder; listed because its Awards for All England programme (£300 to £20,000) funded a Crustacean Compassion project in 2026.","website":"https://www.tnlcommunityfund.org.uk/","hq":"United Kingdom","founded":"2004","sources":[{"url":"https://www.tnlcommunityfund.org.uk/","title":"Home | The National Lottery Community Fund","accessed":"2026-11-19","published":null},{"url":"https://www.tnlcommunityfund.org.uk/funding/funding-programmes/national-lottery-awards-for-all-england","title":"National Lottery Awards for All England | The National Lottery Community Fund","accessed":"2026-11-19","published":null},{"url":"https://www.tnlcommunityfund.org.uk/about-us/our-strategy","title":"The National Lottery Community Fund Strategy 2023 to 2030","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/National_Lottery_Community_Fund","title":"National Lottery Community Fund - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"Funds community projects that bring people together, with a focus on poverty, disadvantage and discrimination; animal welfare is not a stated priority, so the species field is left empty. Awards for All England is open to applications on a rolling basis with a decision in about 16 weeks. Founding year (formed June 2004 as the Big Lottery Fund) is from Wikipedia. Grant records use the id the-national-lottery-community-fund. The Crustacean Compassion grant comes from the 360Giving record already on the map, which was not re-fetched on 2026-11-19.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('science-for-animal-welfare','Science for Animal Welfare','funder',NULL,'funding','funding','active','{"aliases":["UFAW","Universities Federation for Animal Welfare","University of London Animal Welfare Society"],"categories":["funding","welfare-science"],"species":["all-animals","farmed-animals","companion-animals","animals-in-research","wild-animals"],"regions":["global"],"countries":["GB"],"interventions":["grantmaking","research","education"],"approach":"research","summary":"UK charity and international scientific society, founded in 1926 and known as UFAW until 2026, that funds and promotes animal welfare science. It offers small and large research grants, awards and scholarships to applicants worldwide, publishes the journal Animal Welfare and runs conferences.","website":"https://scienceforanimalwelfare.org/","hq":"United Kingdom","founded":"1926","sources":[{"url":"https://scienceforanimalwelfare.org/what-we-do/our-history/","title":"Our history - Science for Animal Welfare","accessed":"2026-11-19","published":null},{"url":"https://scienceforanimalwelfare.org/for-scientists/grants-and-awards/","title":"Grants and Awards - Science for Animal Welfare","accessed":"2026-11-19","published":null},{"url":"https://scienceforanimalwelfare.org/award/large-research-grants/","title":"Large Research Grants - Science for Animal Welfare","accessed":"2026-11-19","published":null},{"url":"https://scienceforanimalwelfare.org/","title":"Home - Science for Animal Welfare","accessed":"2026-11-19","published":null}],"notes":"Open on 2026-11-19: Centenary Research Award (concept notes by 31 Dec 2026), Small Research Grants (up to £5,000) and Large Research Grants (over £5,000; deadlines 1 April and 1 October each year). Research on farmed animals in transport, at markets or at slaughter is referred to its sister charity, the Humane Slaughter Association. Registered charity in England no. 207996. More a scientific society that also makes grants than a pure funder; kind kept as \"funder\" to match the existing stub.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('sharegift','ShareGift','funder',NULL,'funding','funding','active','{"aliases":["The Orr Mackintosh Foundation"],"categories":["funding"],"species":[],"regions":["uk"],"countries":["GB"],"interventions":["grantmaking"],"approach":"neutral-infrastructure","summary":"UK charity that collects donated shareholdings, sells them and passes the proceeds to UK registered charities as unrestricted one-off grants, guided by donor suggestions. A general funder, not animal-specific, and it takes no applications; it made a grant to Crustacean Compassion in 2026.","website":"https://www.sharegift.org/","hq":"United Kingdom","founded":"1996","sources":[{"url":"https://www.sharegift.org/for-charities/","title":"For charities - ShareGift","accessed":"2026-11-19","published":null},{"url":"https://www.sharegift.org/","title":"Home - ShareGift","accessed":"2026-11-19","published":null},{"url":"https://www.sharegift.org/about-sharegift/","title":"About us - ShareGift","accessed":"2026-11-19","published":null}],"notes":"Legal name The Orr Mackintosh Foundation Limited, registered charity no. 1052686. Founding year is inferred from its site, which says 2026 is its 30th year as a charity. Charities cannot apply; the suggested route is for a charity''s supporters to donate shares and name it. Its site says it gave more than £10 million in 2025. Species left empty because it has no animal remit. Its RSS feed holds a single page item, so it is not listed. The 2026 Crustacean Compassion grant comes from the 360Giving record already on the map, which was not re-fetched on 2026-11-19.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('strategic-animal-funding-circle','Strategic Animal Funding Circle','funder',NULL,'funding','funding','active','{"aliases":[],"categories":["funding"],"species":["farmed-animals","all-animals"],"regions":["global"],"countries":[],"interventions":["grantmaking"],"approach":"neutral-infrastructure","summary":"Group of donors that holds two collaborative grant rounds a year for animal welfare and protection non-profits, with a preference for organisations under four years old or with budgets under USD 500,000. It is not a pooled fund: each member makes independent funding decisions.","website":"https://www.animalfundingcircle.com/","hq":null,"founded":null,"sources":[{"url":"https://www.animalfundingcircle.com/","title":"HOME | Strategic Animal Funding Circle","accessed":"2026-11-19","published":null}],"notes":"The site describes it as a project of Senterra Funders and Ambitious Impact. Its stated aims are funding welfare-focused interventions, supporting plant-based innovations and movement building in neglected regions. Members contribute at least USD 100,000 a year to farmed animal advocacy. The latest round closed on 1 November 2026, with decisions expected by early December; applicants must be registered non-profits or have a fiscal agent.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('university-of-stirling','University of Stirling (Institute of Aquaculture)','organisation',NULL,'welfare-science','funding','active','{"aliases":["University of Stirling","Institute of Aquaculture"],"categories":["welfare-science"],"species":["farmed-fish"],"regions":["uk","southeast-asia"],"countries":["GB","TH","VN","ID"],"interventions":["research","education","capacity-building"],"approach":"research","summary":"Scottish university listed here for its Institute of Aquaculture, a teaching, research and consultancy centre for the aquaculture sector. The institute leads grant-funded projects on farmed fish welfare in Thailand, Vietnam and Indonesia, and UK research on fish health and welfare in salmon farming.","website":"https://www.stir.ac.uk/about/faculties/natural-sciences/aquaculture/","hq":"United Kingdom","founded":null,"sources":[{"url":"https://www.stir.ac.uk/about/faculties/natural-sciences/aquaculture/","title":"Institute of Aquaculture | About | University of Stirling","accessed":"2026-11-19","published":null},{"url":"https://www.stir.ac.uk/news/2022/november-2022-news/funding-announced-for-major-aquaculture-project-in-thailand-and-vietnam/","title":"Funding announced for major aquaculture project in Thailand and Vietnam | University of Stirling","accessed":"2026-11-19","published":null},{"url":"https://www.globalseafood.org/advocate/university-of-stirlings-new-grant-aims-to-advance-fish-welfare-and-responsible-aquaculture-in-southeast-asia/","title":"University of Stirling''s new grant aims to advance fish welfare and responsible aquaculture in Southeast Asia - Responsible Seafood Advocate","accessed":"2026-11-19","published":null},{"url":"https://gtr.ukri.org/find-research-and-innovation/project/8d91e5bd-2a56-483e-9f75-6210a34a7ff2","title":"UKRI Gateway to Research: BB/Z515255/1","accessed":"2026-11-19","published":null}],"notes":"A research and teaching institution serving the aquaculture industry, not an advocacy group; welfare is one strand of its work. The website field points to the institute page rather than the university homepage. The 2022 university news item reports £780,000 from Open Philanthropy for the Thailand and Vietnam project; the later, larger grant covering Indonesia is reported by Global Seafood Alliance. The salmon work refers to the BBSRC-funded project on electric-powered aeration for fish welfare (Gateway to Research BB/Z515255/1).","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('wageningen-university','Wageningen University & Research','organisation',NULL,'welfare-science','funding','active','{"aliases":["WUR","Wageningen University","Wageningen Research"],"categories":["welfare-science"],"species":["wild-fish","farmed-fish"],"regions":["europe"],"countries":["NL"],"interventions":["research","humane-slaughter"],"approach":"research","summary":"Dutch university and research organisation for life sciences and agriculture. Listed here for fish welfare research: Wageningen Research co-founded the Catch Welfare Platform in 2023, an industry and research network on the welfare of wild-caught fish, including stunning and slaughter on board.","website":"https://www.wur.nl/en.htm","hq":"Netherlands","founded":"1918","sources":[{"url":"https://www.wur.nl/en/about-wur.htm","title":"About Wageningen University & Research | WUR","accessed":"2026-11-19","published":null},{"url":"https://catchwelfareplatform.com/what-we-do/","title":"ABOUT US – catchwelfareplatform.com","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/Wageningen_University_%26_Research","title":"Wageningen University & Research - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"A large general research institution; fish welfare is a small part of its work. WUR''s own pages on fish welfare research returned 404 or errors on 2026-11-19, so the welfare link rests on the Catch Welfare Platform site and the Coefficient Giving grant records for wild-caught fish welfare. \"Founded\" is the year it was recognised as a university (Wikipedia: established 1876 as an agricultural college).","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('who-let-docs-out','Who Let The Docs Out','funder',NULL,'funding','funding','active','{"aliases":["Who Let the Docs Out"],"categories":["funding","community-media"],"species":["all-animals","farmed-animals"],"regions":["global"],"countries":[],"interventions":["grantmaking","public-awareness","capacity-building"],"approach":"neutral-infrastructure","summary":"Filmmaker-led non-profit that makes grants to impact documentaries about animals, food systems and the planet, at four production stages and in three funding cycles a year. It also offers filmmakers worldwide mentorship, a community, distribution support and advises philanthropists on film funding.","website":"https://www.docsout.org/","hq":null,"founded":null,"sources":[{"url":"https://www.docsout.org/","title":"Who Let The Docs Out | Secure Funding Today – Apply Now","accessed":"2026-11-19","published":null},{"url":"https://www.docsout.org/funding","title":"Grant Cycles — Who Let The Docs Out","accessed":"2026-11-19","published":null},{"url":"https://www.docsout.org/about","title":"About Us — Who Let The Docs Out","accessed":"2026-11-19","published":null}],"notes":"wholetthedocsout.org redirects to docsout.org. Cycles on its site on 2026-11-19: 2026 Autumn (pre-applications closed 13 Nov 2026; full applications due 1 Jan), 2027 Spring (pre-application deadline 19 March 2027) and 2027 Summer (16 July 2027). The per-stage grant ceiling of USD 50,000 reported by Hive was not found on the pages fetched, which are partly script-rendered. Headquarters and founding year are not stated. Grant records use the id who-let-the-docs-out.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('senterra-funders','Senterra Funders','network',NULL,'funding','funding','active','{"aliases":["Farmed Animal Funders","FAF","Senterra"],"categories":["funding","movement-infrastructure"],"species":["farmed-animals","farmed-fish","crustaceans"],"regions":["global"],"countries":[],"interventions":["grantmaking","capacity-building","research"],"approach":"neutral-infrastructure","summary":"Membership community of individual and institutional funders who each give USD 250,000 or more a year to end factory farming. It offers members philanthropic advising, shared learning and co-funding vehicles such as its Aquatic Animal Funding Circle and EU policy portfolio. Renamed in 2025.","website":"https://www.senterrafunders.org/","hq":null,"founded":null,"sources":[{"url":"https://www.senterrafunders.org/","title":"Senterra Funders","accessed":"2026-11-19","published":null},{"url":"https://www.senterrafunders.org/opportunities-for-funders","title":"Advising | Empower Sustainable Giving Now — Senterra Funders","accessed":"2026-11-19","published":null},{"url":"https://www.senterrafunders.org/how-we-work","title":"Our Work | Join the Movement Now — Senterra Funders","accessed":"2026-11-19","published":null},{"url":"https://forum-bots.effectivealtruism.org/posts/7qZ9tRiBztSqF9oNH/introducing-senterra-funders-the-new-name-for-farmed-animal","title":"Introducing Senterra Funders: the new name for Farmed Animal Funders — EA Forum","accessed":"2026-11-19","published":"2025-10-15"}],"notes":"A donor network, not a fund that charities can apply to: members make their own grants. Its homepage gives 56 members and says members account for roughly 75% of global philanthropic funding to end factory farming (its own figure). Founding year is reported as 2017 or 2018 by secondary sources and is left empty. Co-runs the Strategic Animal Funding Circle with Ambitious Impact. The newest item in its articles feed is from December 2025. The old domain farmedanimalfunders.org did not respond.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('aquatic-animal-funding-circle','Aquatic Animal Funding Circle','programme','senterra-funders','funding','funding','unclear','{"aliases":[],"categories":["funding"],"species":["farmed-fish","crustaceans"],"regions":["global"],"countries":[],"interventions":["grantmaking"],"approach":"neutral-infrastructure","summary":"Funding circle hosted by Senterra Funders since January 2025 that brings major donors together to learn about, evaluate and co-fund work to reduce the suffering of farmed aquatic animals and prevent the growth of aquaculture, with a co-funding goal of at least USD 1 million per cycle.","website":"https://www.senterrafunders.org/articles/the-aquatic-animal-funding-circle-tmphf","hq":null,"founded":"2025","sources":[{"url":"https://www.senterrafunders.org/articles/the-aquatic-animal-funding-circle-tmphf","title":"Aquatic Animal Funding Circle — Senterra Funders","accessed":"2026-11-19","published":null},{"url":"https://forum-bots.effectivealtruism.org/posts/dBwoeth8y9dQjTeSw/aquatic-animal-funding-recommendations","title":"Aquatic Animal Funding Recommendations — EA Forum","accessed":"2026-11-19","published":"2025-08-14"}],"notes":"Open to Senterra members able to co-fund significantly, and case by case to other donors giving at least USD 100,000 per round; not open to public applications, though the 2025 cycle ran a request for proposals. In 2025 circle members and aligned funders granted over USD 1.5 million to ten organisations. Senterra''s page describes the circle in the past tense, so whether a further cycle is running is not confirmed: status set to unclear. Stated inspiration: proposals from Rethink Priorities and Aquatic Life Institute.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('india-animal-fund','India Animal Fund','funder',NULL,'funding','funding','active','{"aliases":["IAF"],"categories":["funding","movement-infrastructure","incubation-careers"],"species":["farmed-animals"],"regions":["south-asia"],"countries":["IN"],"interventions":["grantmaking","capacity-building","research"],"approach":"neutral-infrastructure","summary":"Indian organisation that works to build the country''s farmed animal welfare field: it funds organisations and early-stage ideas, advises philanthropists, foundations and companies, incubates new organisations, connects NGOs with corporate funding and publishes research.","website":"https://indiaanimalfund.org/","hq":"India","founded":null,"sources":[{"url":"https://indiaanimalfund.org/","title":"Farmed Animal Welfare in India | India Animal Fund","accessed":"2026-11-19","published":null},{"url":"https://indiaanimalfund.org/our-approach/","title":"Animal Welfare Funding & Philanthropy, Partnerships, Research India","accessed":"2026-11-19","published":null},{"url":"https://indiaanimalfund.org/about-us/","title":"About India Animal Fund | Animal Welfare India","accessed":"2026-11-19","published":null}],"notes":"The site does not describe an application process or state a founding year. It links to the India Animal Welfare Funding Circle. Its RSS feed holds only a placeholder post, so it is not listed. Also profiled in data/research/movement-south-entities.json under the same id. | Founding year not stated on the pages fetched. A funder/intermediary; flagged for the funders pass in case of overlap.","merged_from":["india-animal-fund"]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('india-animal-welfare-funding-circle','India Animal Welfare Funding Circle','funder',NULL,'funding','funding','active','{"aliases":[],"categories":["funding"],"species":["farmed-animals","all-animals"],"regions":["south-asia"],"countries":["IN"],"interventions":["grantmaking"],"approach":"neutral-infrastructure","summary":"Group of donors that makes grants to animal-focused non-profits in India, particularly for farmed animals, in funding rounds. Each funder decides independently; it is not a pooled fund. Open to non-profits registered in India, partner programmes and people planning a new organisation.","website":"https://animalfundingcircle.in/","hq":"India","founded":null,"sources":[{"url":"https://animalfundingcircle.in/","title":"India Animal Welfare Funding Circle | Strategic Animal Welfare Funding","accessed":"2026-11-19","published":null},{"url":"https://indiaanimalfund.org/","title":"Farmed Animal Welfare in India | India Animal Fund","accessed":"2026-11-19","published":null}],"notes":"The site is script-rendered: the description was read from the page metadata and the site''s own script bundle (animalfundingcircle.in/assets/index-CASVqhLR.js), which says applicants need Indian 80G and 12A registration or a registered partner. Round dates were not readable; the site offers sign-up for round announcements. Linked from India Animal Fund''s site; the relationship between the two is not spelled out. Named in Hive''s fundraising guide.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('thrive-philanthropy','Thrive Philanthropy','funder',NULL,'funding','funding','active','{"aliases":[],"categories":["funding","movement-infrastructure"],"species":["farmed-animals"],"regions":["global","africa","asia","latin-america"],"countries":["US"],"interventions":["grantmaking","capacity-building","diet-change"],"approach":"neutral-infrastructure","summary":"US-registered grantmaker funding initiatives that accelerate alternatives to industrial animal agriculture and build plant-rich food systems worldwide. It offers seed grants of up to USD 5,000, larger grants for established groups, and accelerators and programmes in Africa, Asia and Latin America.","website":"https://www.thrivephilanthropy.org/","hq":"United States","founded":null,"sources":[{"url":"https://www.thrivephilanthropy.org/grants","title":"Apply | Join the Movement Today — Thrive Philanthropy","accessed":"2026-11-19","published":null},{"url":"https://www.thrivephilanthropy.org/","title":"Thrive Philanthropy | Join Us to End Factory Farming","accessed":"2026-11-19","published":null}],"notes":"Seed grants are aimed at new or smaller organisations, one-off projects and individuals without non-profit status; the larger grant type is mainly for mid-size and larger organisations with a track record or previous grantees. Application deadlines were not found on the pages fetched. Focus is plant-based food systems and diet change rather than farm welfare standards. Thrive Philanthropy, Inc. is a US 501(c)(3); founding year not found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('greenbaum','The Greenbaum Foundation','funder',NULL,'funding','funding','active','{"aliases":["Greenbaum Foundation"],"categories":["funding"],"species":["farmed-animals","all-animals"],"regions":["north-america","global"],"countries":["US"],"interventions":["grantmaking","diet-change","public-awareness"],"approach":"neutral-infrastructure","summary":"US private grantmaking foundation, operational since 1999, that now concentrates on moving the world to whole-food, plant-based diets and ending factory farming, including funding documentary films. It does not accept unsolicited proposals and does not fund sanctuaries.","website":"https://www.greenbaumfoundation.org/","hq":"United States","founded":"1999","sources":[{"url":"https://www.greenbaumfoundation.org/about","title":"About — Greenbaum Foundation","accessed":"2026-11-19","published":null},{"url":"https://www.greenbaumfoundation.org/contact","title":"Contact — Greenbaum Foundation","accessed":"2026-11-19","published":null},{"url":"https://www.greenbaumfoundation.org/","title":"Greenbaum Foundation","accessed":"2026-11-19","published":null}],"notes":"Invitation only. Its site says annual grant-making is currently in the USD 6-7 million range and that it still funds a small number of legacy human rights organisations. \"Founded\" is the year the site says it became fully operational. The global tag reflects its stated aim and internationally distributed films; where grantees are based was not checked.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('quinn','The Quinn Foundation','funder',NULL,'funding','funding','active','{"aliases":["Quinn Foundation"],"categories":["funding"],"species":["companion-animals","farmed-animals","farmed-fish","animals-in-research","wild-animals"],"regions":["north-america"],"countries":["US"],"interventions":["grantmaking"],"approach":"neutral-infrastructure","summary":"US private family foundation that funds animal protection, the environment and a food system free of factory farming, mainly in the US. It is affiliated with Stray Dog Institute, through which it makes some international food-systems grants. It is not currently accepting unsolicited proposals.","website":"https://thequinnfoundation.org/","hq":"United States","founded":null,"sources":[{"url":"https://thequinnfoundation.org/","title":"Home - The Quinn Foundation","accessed":"2026-11-19","published":null},{"url":"https://animalgrantmakers.org/Sys/PublicProfile/41940796/1588687","title":"Animal Grantmakers - Member public profile: The Quinn Foundation","accessed":"2026-11-19","published":null}],"notes":"Invitation only according to its own site; its Animal Grantmakers member profile suggests email outreach as the initial approach. That profile gives Leawood, United States, and lists funding for companion and equine animals, farmed land and aquatic animals (cows, pigs, poultry, fish), animals used in testing and some marine and wild animals, across direct care, policy, litigation, narrative change, movement building and diet change. Stray Dog Institute is already on the map as a separate entry; the two share founders. Founding year not found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('mobius','Mobius','funder',NULL,'funding','funding','active','{"aliases":["Mobius Life"],"categories":["funding"],"species":["farmed-animals"],"regions":["global","asia","north-america"],"countries":["US"],"interventions":["grantmaking","legislation-policy","alt-proteins"],"approach":"neutral-infrastructure","summary":"Family office that gives to work on factory farming and the food system alongside its investments. Its stated philanthropic priorities are political advocacy for farmed animals, alternative proteins, neglected regions such as Asia, and newer organisations that can attract further funding.","website":"https://mobius.life/","hq":null,"founded":null,"sources":[{"url":"https://mobius.life/for-grant-seekers/","title":"For grant-seekers | Mobius","accessed":"2026-11-19","published":null},{"url":"https://mobius.life/","title":"Mobius | Capital Allocation Office","accessed":"2026-11-19","published":null}],"notes":"How to apply: it considers unsolicited applications only through the Strategic Animal Funding Circle (two rounds a year). It has no endowment and gives according to yearly business results, so it rarely makes grant decisions between January and September and does not make multi-year commitments. Its site says it has donated over USD 40 million to food-system non-profits. Headquarters not stated; the US tag reflects its US policy work.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('craigslist-charitable-fund','Craigslist Charitable Fund','funder',NULL,'funding','funding','active','{"aliases":["CCF","Craigslist Fund"],"categories":["funding"],"species":["farmed-animals","all-animals"],"regions":["global"],"countries":["US"],"interventions":["grantmaking"],"approach":"neutral-infrastructure","summary":"Grant-making fund focused on ending animal exploitation, in particular animal agriculture. It accepts applications through an online portal from organisations anywhere in the world, with or without US charity status, and typically funds no more than 30% of an organisation''s annual budget.","website":"https://www.craigslistfund.org/","hq":"United States","founded":null,"sources":[{"url":"https://www.craigslistfund.org/faq","title":"Frequently Asked Questions — Craigslist Fund","accessed":"2026-11-19","published":null},{"url":"https://www.craigslistfund.org/","title":"Craigslist Fund","accessed":"2026-11-19","published":null}],"notes":"No deadlines are stated; the FAQ says review can take up to 6 months and that it cannot meet urgent deadlines. Academic research is eligible if at most 10% goes to overheads. Its funding priorities page lists categories including schools and universities and documentaries, but the page is partly script-rendered and was not fully read. The United States base is inferred from FAQ references to the San Francisco Bay Area.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('food-system-research-fund','Food System Research Fund','funder',NULL,'funding','funding','active','{"aliases":["Food Systems Research Fund"],"categories":["funding","welfare-science"],"species":["farmed-animals","farmed-fish","chickens"],"regions":["global"],"countries":["US"],"interventions":["grantmaking","research"],"approach":"research","summary":"Research fund managed by the US non-profit Food System Innovations. It funds empirical studies on interventions for a more sustainable, plant-forward food system that could affect large numbers of animals, often fish and chickens. Grants are rarely above USD 50,000. Not accepting applications now.","website":"https://www.fsrfund.org/","hq":"United States","founded":null,"sources":[{"url":"https://www.fsrfund.org/","title":"Food System Research Fund","accessed":"2026-11-19","published":null},{"url":"https://www.fsrfund.org/research-focus","title":"Research Focus — Food System Research Fund","accessed":"2026-11-19","published":null},{"url":"https://www.fsrfund.org/faqs","title":"FAQs & Policies — Food System Research Fund","accessed":"2026-11-19","published":null},{"url":"https://www.fsrfund.org/about","title":"About Us — Food System Research Fund","accessed":"2026-11-19","published":null}],"notes":"On 2026-11-19 the site said it was not accepting applications and that its portal may re-open at any time; during a funding cycle applications are rolling, and it also issues requests for proposals with deadlines. It may support a PhD or postdoctoral project but not a programme generally. Food System Innovations is not on the map, so no parent is set. No worldwide eligibility statement was found; \"global\" reflects its stated aim of generalisable research.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('effective-animal-advocacy-fund','Effective Animal Advocacy Fund','funder',NULL,'funding','funding','active','{"aliases":["Giving What We Can Effective Animal Advocacy Fund"],"categories":["funding"],"species":["farmed-animals","wild-animals"],"regions":["global"],"countries":[],"interventions":["grantmaking"],"approach":"neutral-infrastructure","summary":"Donor fund run by Giving What We Can. It pools donations and allocates them quarterly to grantmakers its research team judges best placed to improve animal welfare; the current plan is half to the EA Animal Welfare Fund and half to Animal Charity Evaluators'' Movement Grants.","website":"https://www.givingwhatwecan.org/charities/effective-animal-advocacy-fund","hq":null,"founded":null,"sources":[{"url":"https://www.givingwhatwecan.org/charities/effective-animal-advocacy-fund","title":"Effective Animal Advocacy Fund · Giving What We Can","accessed":"2026-11-19","published":null}],"notes":"A fund for donors, not one that organisations apply to: applicants go to the EA Animal Welfare Fund or ACE Movement Grants. Giving What We Can says it reviews the allocation at least once a year. Giving What We Can itself is not on the map, so no parent is set.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('effektiv-spenden-tierleid-verringern','Spendenfonds: Tierleid verringern (Effektiv Spenden)','funder',NULL,'funding','funding','active','{"aliases":["Effektiv Spenden animal welfare fund","Tierleid verringern"],"categories":["funding"],"species":["farmed-animals"],"regions":["europe","global"],"countries":["DE"],"interventions":["grantmaking"],"approach":"neutral-infrastructure","summary":"Donation fund of the German effective-giving organisation Effektiv Spenden for reducing animal suffering, with a focus on farmed animals. Donations are pooled and passed on following the recommendations of the EA Animal Welfare Fund.","website":"https://effektiv-spenden.org/effektiver-tierschutz/","hq":"Germany","founded":null,"sources":[{"url":"https://effektiv-spenden.org/effektiver-tierschutz/","title":"Tierleid verringern | Effektiv Spenden","accessed":"2026-11-19","published":null}],"notes":"A fund for donors in Germany, not one that organisations apply to. The page (in German) also recommends individual charities assessed by Animal Charity Evaluators, such as The Humane League. Donors are in Germany; the money is regranted internationally, hence both region tags. The fund''s own detail page was not fetched.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('doneer-effectief-dierenwelzijn-fonds','Fonds Dierenwelzijn & voedseltransitie (Doneer Effectief)','funder',NULL,'funding','funding','active','{"aliases":["Doneer Effectief animal welfare fund","Dierenwelzijn en voedseltransitie"],"categories":["funding"],"species":["farmed-animals","farmed-fish"],"regions":["europe","global"],"countries":["NL"],"interventions":["grantmaking"],"approach":"neutral-infrastructure","summary":"Animal welfare and food transition fund of the Dutch effective-giving foundation Doneer Effectief (founded 2022). It pools donations for charities that improve farmed animal welfare or reduce consumption of animal products, basing allocations on Animal Charity Evaluators'' evaluations.","website":"https://doneereffectief.nl/toporganisaties/dierenwelzijn-en-voedseltransitie/","hq":"Netherlands","founded":null,"sources":[{"url":"https://doneereffectief.nl/toporganisaties/dierenwelzijn-en-voedseltransitie/","title":"Dierenwelzijn & voedseltransitie - Doneer Effectief","accessed":"2026-11-19","published":null},{"url":"https://doneereffectief.nl/over-ons/","title":"Over ons - Doneer Effectief","accessed":"2026-11-19","published":null}],"notes":"A fund for donors in the Netherlands, not one that organisations apply to. The page is in Dutch; its news items credit the fund with support for groups such as Animal Welfare Observatory. The 2022 date is when Doneer Effectief was founded; the fund''s own start date was not found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('culture-and-animals','Culture & Animals Foundation','funder',NULL,'funding','funding','active','{"aliases":["CAF"],"categories":["funding","community-media"],"species":["all-animals"],"regions":["global"],"countries":[],"interventions":["grantmaking","research","public-awareness"],"approach":"neutral-infrastructure","summary":"Foundation, begun in 1985, that gives annual grants to scholars and artists whose research, creative work or performances build understanding of human-animal relationships and respect for animal rights. Grants are up to USD 5,000 and open to applicants in any country.","website":"https://cultureandanimals.org/","hq":null,"founded":"1985","sources":[{"url":"https://cultureandanimals.org/grants/","title":"Grants – Culture & Animals Foundation","accessed":"2026-11-19","published":null},{"url":"https://cultureandanimals.org/grants/grant_faqs/","title":"Grant Essential Information – Culture & Animals Foundation","accessed":"2026-11-19","published":null},{"url":"https://cultureandanimals.org/about/history/","title":"History – Culture & Animals Foundation","accessed":"2026-11-19","published":null}],"notes":"Next cycle: proposals accepted 4-17 January 2027 or until 200 applications are received, whichever comes first; decisions by mid-March. Grants go to individuals, not institutions, and applications must be in English. Founded by the philosopher Tom Regan and Nancy Regan. Headquarters not stated on the pages fetched.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('a-well-fed-world','A Well-Fed World','organisation',NULL,'funding','funding','active','{"aliases":[],"categories":["funding","advocacy-campaigns"],"species":["farmed-animals"],"regions":["global"],"countries":[],"interventions":["grantmaking","diet-change","public-awareness"],"approach":"unclear","summary":"Organisation working on hunger and plant-based food that runs global grants and climate-food funds. It has moved away from open online grant applications and now funds through its established partnership circles.","website":"https://awellfedworld.org/","hq":null,"founded":null,"sources":[{"url":"https://awellfedworld.org/grants/","title":"Global Grants, Climate Food & Impact Funds - A Well-Fed World","accessed":"2026-11-19","published":null}],"notes":"Only its grants page was read. Not open to unsolicited applications as of 2026-11-19; the page invites sign-up to hear if open granting relaunches. Headquarters, founding year and its wider programmes were not verified, so approach is left as unclear.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('marchig-animal-welfare-trust','Marchig Animal Welfare Trust','funder',NULL,'funding','funding','active','{"aliases":["Marchig Trust"],"categories":["funding"],"species":["all-animals","companion-animals","animals-in-research","wild-animals"],"regions":["global","uk"],"countries":["GB"],"interventions":["grantmaking"],"approach":"neutral-infrastructure","summary":"UK charity established in 1989 that gives grants and awards for practical work preventing cruelty and relieving animal suffering, and for alternatives to animal experiments, anywhere except the USA and Canada. It is not accepting new grant applications until further notice.","website":"https://marchigtrust.org/","hq":"United Kingdom","founded":"1989","sources":[{"url":"https://marchigtrust.org/","title":"The Marchig Animal Welfare Trust – Grants & Awards","accessed":"2026-11-19","published":null},{"url":"https://marchigtrust.org/grants/","title":"Grants Programme – The Marchig Animal Welfare Trust","accessed":"2026-11-19","published":null}],"notes":"Closed to new applications on 2026-11-19 because of the number of requests received. Past support listed on its site includes spay/neuter programmes, veterinary clinics, sanctuaries and anti-poaching work, so it is mainly a companion and wild animal funder rather than a farmed animal one. Registered charity nos. 802133 (England and Wales) and SC038057 (Scotland).","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('parks-for-animal-welfare','The William and Charlotte Parks Foundation for Animal Welfare','funder',NULL,'funding','funding','active','{"aliases":["Parks Foundation"],"categories":["funding"],"species":["all-animals"],"regions":["global"],"countries":[],"interventions":["grantmaking","research"],"approach":"neutral-infrastructure","summary":"Foundation that makes project grants, usually of no more than USD 10,000 a year, to animal protection organisations and scholars for projects and research that reduce animal suffering or improve the status of animals. Applicants must be registered charities in the US or their home country.","website":"https://www.parksfoundation.org/","hq":null,"founded":null,"sources":[{"url":"https://www.parksfoundation.org/","title":"The William and Charlotte Parks Foundation for Animal Welfare","accessed":"2026-11-19","published":null},{"url":"https://www.parksfoundation.org/types-of-grants","title":"Types of Grants — The William and Charlotte Parks Foundation for Animal Welfare","accessed":"2026-11-19","published":null},{"url":"https://www.parksfoundation.org/how-to-apply","title":"How to Apply — The William and Charlotte Parks Foundation for Animal Welfare","accessed":"2026-11-19","published":null}],"notes":"Applies through an online portal with a listed close date (the date itself was not readable on the pages fetched); notifications generally within 90 days of closing. Project grants only: no capital or general operating grants, and none for animal health, spay/neuter, endangered species, wildlife rehabilitation or basic US shelter costs. The site says the foundation has worked for nearly half a century; headquarters and founding year are not stated.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('nc3rs','NC3Rs','funder',NULL,'funding','funding','active','{"aliases":["National Centre for the Replacement, Refinement and Reduction of Animals in Research"],"categories":["funding","welfare-science"],"species":["animals-in-research"],"regions":["uk"],"countries":["GB"],"interventions":["grantmaking","research","education"],"approach":"research","summary":"UK-based scientific organisation that works with the research community to replace, refine and reduce the use of animals in research and testing. It funds 3Rs research, studentships, fellowships and technology challenges, and publishes guidance and training resources.","website":"https://nc3rs.org.uk/","hq":"United Kingdom","founded":"2004","sources":[{"url":"https://nc3rs.org.uk/who-we-are","title":"Who we are | NC3Rs","accessed":"2026-11-19","published":null},{"url":"https://nc3rs.org.uk/our-funding-schemes","title":"Research and innovation funding schemes | NC3Rs","accessed":"2026-11-19","published":null},{"url":"https://nc3rs.org.uk/","title":"NC3Rs","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/National_Centre_for_the_Replacement,_Refinement_and_Reduction_of_Animals_in_Research","title":"National Centre for the Replacement, Refinement and Reduction of Animals in Research - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"On 2026-11-19 its funding page said NC3Rs funding schemes are not open for applications at this time, with updates to follow on each scheme page. Concerned with animals used in science, not farmed animals. Full name and founding year (established 2004) are from Wikipedia.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('for-food-and-agriculture-research','Foundation for Food & Agriculture Research','funder',NULL,'funding','funding','active','{"aliases":["FFAR"],"categories":["funding","welfare-technology"],"species":["chickens","farmed-animals"],"regions":["north-america"],"countries":["US"],"interventions":["grantmaking","research"],"approach":"neutral-infrastructure","summary":"US food and agriculture research funder that works through public-private partnerships. Its animal programmes have included SMART Broiler (USD 4 million for automated broiler welfare monitoring, with McDonald''s) and the Egg-Tech Prize for in-ovo sexing technology to end male chick culling.","website":"https://foundationfar.org/","hq":"United States","founded":null,"sources":[{"url":"https://foundationfar.org/programs/smart-broiler/","title":"SMART Broiler - Foundation for Food & Agriculture Research","accessed":"2026-11-19","published":null},{"url":"https://foundationfar.org/programs/egg-tech-prize/","title":"Egg-Tech Prize - Foundation for Food & Agriculture Research","accessed":"2026-11-19","published":null},{"url":"https://foundationfar.org/what-we-do/research-priorities/production-systems/","title":"Production Systems - Foundation for Food & Agriculture Research","accessed":"2026-11-19","published":null},{"url":"https://foundationfar.org/grants-funding/open-opportunities/","title":"Open Opportunities - Foundation for Food & Agriculture Research","accessed":"2026-11-19","published":null}],"notes":"A general agricultural research funder oriented to production; welfare is one aim of its Production Systems priority, alongside productivity. Its open opportunities page said there were no open funding opportunities when fetched on 2026-11-19, while also listing consortium requests. The Egg-Tech Prize page says it offers up to USD 6 million and was run with Open Philanthropy. Founding year and legal basis were not verified.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('fhf-norwegian-seafood-research-fund','FHF – Norwegian Seafood Research Fund','funder',NULL,'funding','funding','active','{"aliases":["FHF","Fiskeri- og havbruksnæringens forskningsfinansiering"],"categories":["funding","welfare-science"],"species":["farmed-fish","wild-fish","crustaceans"],"regions":["europe"],"countries":["NO"],"interventions":["grantmaking","research"],"approach":"neutral-infrastructure","summary":"Norwegian state-owned company that funds research and development for the seafood industry, financed by a 0.3% levy on seafood exports. Fish health and welfare in salmon farming is one of its largest research areas, and it publishes calls for projects on topics such as welfare indicators.","website":"https://www.fhf.no/","hq":"Norway","founded":null,"sources":[{"url":"https://www.fhf.no/fhf/about-fhf-english/","title":"FHF – Norwegian Seafood Research Fund","accessed":"2026-11-19","published":null},{"url":"https://www.fhf.no/prioriteringer/havbruk/fiskehelse-og-fiskevelferd/","title":"Fiskehelse og fiskevelferd – FHF","accessed":"2026-11-19","published":null},{"url":"https://www.fhf.no/utlysninger/utlysninger/risikoreduserende-tiltak-ved-lave-oksygennivaa-i-aapne-merder/","title":"Risikoreduserende tiltak ved lave oksygennivå i åpne merder – FHF","accessed":"2026-11-19","published":"2026-09-24"}],"notes":"An industry research fund, not an advocacy funder: its goal is added value for the seafood industry, with welfare treated alongside survival, biosecurity and production. Owned by the Ministry of Trade, Industry and Fisheries, with an industry board. Site and feeds are in Norwegian (feed-utlysninger lists calls, feed-nyheter news). Open on 2026-11-19: a call of up to NOK 10 million on low oxygen in open sea cages, deadline 4 December 2026. Founding year not verified.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('european-partnership-on-animal-health-and-welfare','European Partnership on Animal Health and Welfare','funder','european-commission','funding','funding','active','{"aliases":["EUPAHW","EUP AH&W"],"categories":["funding","welfare-science"],"species":["farmed-animals","farmed-fish","chickens","pigs","cows"],"regions":["europe"],"countries":["BE"],"interventions":["grantmaking","research","education"],"approach":"research","summary":"EU research partnership launched in 2024, expected to invest EUR 360 million over seven years in research on livestock, poultry and aquaculture health and welfare. Co-funded by Horizon Europe and national funders, it runs joint calls for research consortia. Coordinated by Ghent University.","website":"https://www.eupahw.eu/","hq":"Belgium","founded":"2024","sources":[{"url":"https://www.eupahw.eu/","title":"EUPAHW - Home","accessed":"2026-11-19","published":null},{"url":"https://www.eupahw.eu/about-us","title":"About us - EUPAHW","accessed":"2026-11-19","published":null},{"url":"https://www.ukri.org/opportunity/shaping-the-future-of-animal-health-and-welfare/","title":"Shaping the future of animal health and welfare – UKRI","accessed":"2026-11-19","published":null}],"notes":"Health (infectious disease control, antimicrobial use) is as central as welfare. Its site lists two external calls, but the open-calls pages are script-rendered and could not be read; the call described by UKRI (\"Shaping the future of animal health and welfare\", with national co-funders including BBSRC and Defra) had a pre-proposal deadline of 30 March 2026, with full proposals by invitation. Co-funded under Horizon Europe project 101136346. Parent set to the European Commission entry as its EU co-funder; national agencies fund their own countries'' teams.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('animal-health-and-welfare-pathway','Animal Health and Welfare Pathway','programme',NULL,'funding','funding','active','{"aliases":[],"categories":["funding","policy-law"],"species":["farmed-animals","cows","chickens"],"regions":["uk"],"countries":["GB"],"interventions":["grantmaking","farm-practices","producer-engagement"],"approach":"welfare-reform","summary":"UK government programme for England that uses public funds to pay livestock farmers for health and welfare improvements: funded vet visits (the animal health and welfare review), capital grants and other schemes, with priorities set for each livestock sector together with industry, vets and NGOs.","website":"https://www.gov.uk/government/publications/animal-health-and-welfare-pathway/animal-health-and-welfare-pathway","hq":"United Kingdom","founded":null,"sources":[{"url":"https://www.gov.uk/government/publications/animal-health-and-welfare-pathway/animal-health-and-welfare-pathway","title":"Animal Health and Welfare Pathway - GOV.UK","accessed":"2026-11-19","published":"2026-09-10"}],"notes":"Run by the Department for Environment, Food and Rural Affairs (Defra), which is not on the map, so no parent is set. Funding goes to farmers and vets, not to charities or researchers; it also aims to stimulate market demand for higher-welfare products. The page was last updated 10 September 2026 and applies to England only. The review launched in February 2023 and capital grants in March 2023; the Pathway''s own start year was not read. Separately, Defra co-funds welfare research with BBSRC.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('formas','Formas','funder',NULL,'funding','funding','active','{"aliases":[],"categories":["funding","welfare-science"],"species":["farmed-animals"],"regions":["europe"],"countries":["SE"],"interventions":["grantmaking","research"],"approach":"neutral-infrastructure","summary":"Swedish government research council for sustainable development, covering the environment, agricultural sciences and spatial planning. Listed here as a funder: it has run dedicated calls for applied research on the protection and welfare of food-producing animals, at up to SEK 2 million per project.","website":"https://formas.se/en/","hq":"Sweden","founded":null,"sources":[{"url":"https://formas.se/en/start-page/about-formas.html","title":"About Formas - Formas","accessed":"2026-11-19","published":null},{"url":"https://formas.se/en/start-page/apply-for-funding/all-calls/calls/2023-04-24-applied-research-for-increased-animal-protection-and-welfare.html","title":"Applied research for increased animal protection and welfare - Formas","accessed":"2026-11-19","published":null}],"notes":"A general research funder; animal welfare is a small, recurring strand. The call verified is from 2023 and required a research organisation plus an end user. Formas pages from 2025-2026 that mention animal welfare (an \"Action! From research to impact\" call and an idea-development call on animal protection and wellbeing) appeared in search results but were not fetched, so whether a welfare call is open now is not confirmed. Founding year not verified.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('animal-grantmakers','Animal Grantmakers','network',NULL,'funding','funding','active','{"aliases":[],"categories":["funding","movement-infrastructure"],"species":["all-animals","companion-animals","farmed-animals","wild-animals"],"regions":["north-america"],"countries":["US"],"interventions":["capacity-building","grantmaking"],"approach":"neutral-infrastructure","summary":"Affinity group for animal funders: foundations, public charities, corporate giving programmes and individual philanthropists working on issues affecting all types of animals. It runs an annual conference, publishes member profiles with funding areas and lists resources for grantseekers.","website":"https://animalgrantmakers.org/","hq":"United States","founded":null,"sources":[{"url":"https://animalgrantmakers.org/","title":"Animal Grantmakers","accessed":"2026-11-19","published":null},{"url":"https://animalgrantmakers.org/grantseekers","title":"Resources for Grantseekers - Animal Grantmakers","accessed":"2026-11-19","published":null},{"url":"https://animalgrantmakers.org/Sys/PublicProfile/41940796/1588687","title":"Animal Grantmakers - Member public profile: The Quinn Foundation","accessed":"2026-11-19","published":null}],"notes":"A membership body for funders, not a grant-maker: it does not fund charities itself. Its member profiles state each funder''s species, project types, geography and preferred approach, which makes it a way to find US animal funders. Much of its programming concerns companion animals and shelters. The US base is inferred from its \"Animal Philanthropy in the United States\" resources and US-based conference; founding year not found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('humane-league','The Humane League','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["THL"],"categories":["advocacy-campaigns"],"species":["chickens","farmed-animals"],"regions":["global","north-america","uk"],"countries":["US","GB"],"interventions":["corporate-campaigns","legislation-policy","diet-change"],"approach":"welfare-reform","summary":"Nonprofit working to end the abuse of animals raised for food by influencing the policies of large companies, pursuing legislation, and encouraging people to leave animals off their plates. Coordinates the Open Wing Alliance.","website":"https://thehumaneleague.org","hq":"United States","founded":"2005","sources":[{"url":"https://thehumaneleague.org/","title":"The Humane League (homepage)","accessed":"2026-11-05","published":null},{"url":"https://thehumaneleague.org/our-mission","title":"Our Mission - The Humane League","accessed":"2026-11-05","published":null},{"url":"https://en.wikipedia.org/wiki/The_Humane_League","title":"The Humane League - Wikipedia","accessed":"2026-11-05","published":null}],"notes":"Founding year 2005 and HQ (Rockville, Maryland) from Wikipedia infobox; THL site mentions origins in Philadelphia. No RSS feed found at /feed or /rss.xml.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('open-wing-alliance','Open Wing Alliance','programme','humane-league','advocacy-campaigns','movement','active','{"aliases":["OWA"],"categories":["advocacy-campaigns"],"species":["chickens"],"regions":["global"],"countries":[],"interventions":["corporate-campaigns","capacity-building"],"approach":"welfare-reform","summary":"International coalition of 80+ member organisations, coordinated by The Humane League, working to end the abuse of chickens worldwide, starting with cage confinement of hens; runs global campaigns targeting restaurants and supermarkets.","website":"https://openwingalliance.org","hq":null,"founded":null,"sources":[{"url":"https://thehumaneleague.org/open-wing-alliance","title":"Open Wing Alliance - The Humane League","accessed":"2026-11-05","published":null}],"notes":"THL page cites both ''82 groups'' and ''over 80 member organizations'' across 72 countries. openwingalliance.org returned an empty JS-rendered page; founding year not stated on the fetched page.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('sinergia-animal','Sinergia Animal','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":[],"categories":["advocacy-campaigns"],"species":["farmed-animals","chickens","pigs"],"regions":["latin-america","southeast-asia"],"countries":["AR","BR","CL","CO","TH","ID"],"interventions":["corporate-campaigns","investigations","diet-change","public-awareness"],"approach":"welfare-reform","summary":"International animal protection organisation working exclusively in Global South countries to reduce farmed animal suffering through corporate campaigns, investigations, institutional plant-based meal programmes and bank-policy work.","website":"https://sinergiaanimal.org","hq":null,"founded":null,"sources":[{"url":"https://sinergiaanimal.org/","title":"Sinergia Animal | Animal Protection in the Global South","accessed":"2026-11-05","published":null},{"url":"https://sinergiaanimal.org/mission-1","title":"Our Mission - Sinergia Animal","accessed":"2026-11-05","published":null},{"url":"https://sinergiaanimal.org/about-us","title":"About us - Sinergia Animal","accessed":"2026-11-05","published":null}],"notes":"Site says it works in eight countries but the fetched page names six. Earliest timeline entry is 2017; HQ/registration not stated. No feed found.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('anima-international','Anima International','network',NULL,'advocacy-campaigns','movement','active','{"aliases":["Otwarte Klatki","Open Cages","Anima"],"categories":["advocacy-campaigns"],"species":["farmed-animals","chickens","fur-animals"],"regions":["europe","uk"],"countries":["BG","DK","FR","NO","PL","GB"],"interventions":["corporate-campaigns","legislation-policy","investigations","public-awareness"],"approach":"mixed","summary":"Coalition of national animal advocacy groups (including Otwarte Klatki in Poland and Anima in Denmark and Norway) formed by the merger of Anima and Open Cages; runs corporate, legislative and public campaigns for farmed animals.","website":"https://animainternational.org","hq":null,"founded":null,"sources":[{"url":"https://animainternational.org/","title":"Anima International","accessed":"2026-11-05","published":null},{"url":"https://animainternational.org/about/history/","title":"History - Anima International","accessed":"2026-11-05","published":null},{"url":"https://animainternational.org/about/organisations","title":"Organisations - Anima International","accessed":"2026-11-05","published":null}],"notes":"HQ not stated on fetched pages. Earlier histories list Ukraine/Belarus/Russia branches; current organisations page lists six countries. No feed found.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('humane-world-for-animals','Humane World for Animals','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["Humane Society of the United States","HSUS","Humane Society International","HSI","Humane World India"],"categories":["advocacy-campaigns","policy-law","sanctuary-rescue"],"species":["all-animals","companion-animals","farmed-animals","wild-animals","animals-in-research"],"regions":["global","north-america","south-asia","europe"],"countries":["US","IN"],"interventions":["legislation-policy","corporate-campaigns","litigation","sanctuary","public-awareness"],"approach":"welfare-reform","summary":"Global animal protection organisation (formerly the Humane Society of the United States and Humane Society International) working on companion animals, wildlife, farmed animals and animals in research, with offices on six continents.","website":"https://www.humaneworld.org","hq":"United States","founded":"1954","sources":[{"url":"https://www.humaneworld.org/en","title":"Humane World for Animals","accessed":"2026-11-05","published":null},{"url":"https://www.humaneworld.org/en/about-us","title":"About us | Humane World for Animals","accessed":"2026-11-05","published":null},{"url":"https://www.humaneworld.org/india/en","title":"India | Humane World for Animals","accessed":"2026-11-05","published":null},{"url":"https://en.wikipedia.org/wiki/Humane_World_for_Animals","title":"Humane World for Animals - Wikipedia","accessed":"2026-11-05","published":null}],"notes":"Renamed in February 2025 (Wikipedia citing WJLA, 2025-02-13). Founded 1954 as National Humane Society. No RSS found at tested paths.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('animals-australia','Animals Australia','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":[],"categories":["advocacy-campaigns"],"species":["farmed-animals","all-animals"],"regions":["oceania"],"countries":["AU"],"interventions":["investigations","public-awareness","grantmaking"],"approach":"mixed","summary":"Australian animal protection organisation that investigates and exposes animal cruelty, runs public awareness campaigns focused on farmed animals, and funds and supports other animal organisations.","website":"https://animalsaustralia.org","hq":"Australia","founded":"1980","sources":[{"url":"https://en.wikipedia.org/wiki/Animals_Australia","title":"Animals Australia - Wikipedia","accessed":"2026-11-05","published":null}],"notes":"animalsaustralia.org returned a Cloudflare challenge (403); facts from Wikipedia (founded 1980, Melbourne). Feed not checked.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('fiapo','Federation of Indian Animal Protection Organisations','network',NULL,'advocacy-campaigns','movement','active','{"aliases":["FIAPO"],"categories":["advocacy-campaigns","movement-infrastructure"],"species":["all-animals","farmed-animals"],"regions":["south-asia"],"countries":["IN"],"interventions":["capacity-building","legislation-policy","public-awareness"],"approach":"mixed","summary":"Federation uniting animal protection groups across India to advocate for animal rights, welfare and vegan advocacy; supports member organisations with capacity-building workshops.","website":"https://www.fiapo.org","hq":"India","founded":"2010","sources":[{"url":"https://www.fiapo.org/","title":"FIAPO | Join Us in Protecting Animals","accessed":"2026-11-05","published":null},{"url":"https://www.fiapo.org/who-we-are","title":"Who we are - FIAPO","accessed":"2026-11-05","published":null},{"url":"https://en.wikipedia.org/wiki/Federation_of_Indian_Animal_Protection_Organisations","title":"FIAPO - Wikipedia","accessed":"2026-11-05","published":null}],"notes":"Established 25 November 2010 per Wikipedia; Delhi-based. No feed found.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('world-animal-protection','World Animal Protection','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["WSPA","World Society for the Protection of Animals"],"categories":["advocacy-campaigns"],"species":["all-animals","farmed-animals","wild-animals"],"regions":["global"],"countries":["GB"],"interventions":["corporate-campaigns","legislation-policy","public-awareness"],"approach":"welfare-reform","summary":"International animal welfare charity, known as the World Society for the Protection of Animals (WSPA) until 2014, campaigning to end animal cruelty worldwide.","website":"https://www.worldanimalprotection.org","hq":"United Kingdom","founded":"1981","sources":[{"url":"https://www.worldanimalprotection.org/about-us/","title":"About Us - World Animal Protection","accessed":"2026-11-05","published":null},{"url":"https://en.wikipedia.org/wiki/World_Animal_Protection","title":"World Animal Protection - Wikipedia","accessed":"2026-11-05","published":null}],"notes":"Registered charity in England and Wales; country offices not enumerated here.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('four-paws','FOUR PAWS International','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["VIER PFOTEN","Four Paws"],"categories":["advocacy-campaigns","sanctuary-rescue"],"species":["all-animals","wild-animals","companion-animals","farmed-animals"],"regions":["global","europe"],"countries":["AT"],"interventions":["sanctuary","corporate-campaigns","legislation-policy","public-awareness"],"approach":"welfare-reform","summary":"Vienna-based global animal welfare organisation for animals under human influence; reveals suffering, rescues animals in need and runs sanctuaries and campaigns.","website":"https://www.four-paws.org","hq":"Austria","founded":"1988","sources":[{"url":"https://www.four-paws.org/","title":"FOUR PAWS International - Animal Welfare Organisation","accessed":"2026-11-05","published":null},{"url":"https://en.wikipedia.org/wiki/Four_Paws","title":"Four Paws - Wikipedia","accessed":"2026-11-05","published":null}],"notes":"Country offices exist but list not verified. No feed found at /rss.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('proveg-international','ProVeg International','organisation',NULL,'alt-protein','movement','active','{"aliases":["ProVeg"],"categories":["alt-protein","advocacy-campaigns"],"species":["farmed-animals"],"regions":["global","europe"],"countries":[],"interventions":["alt-proteins","diet-change","legislation-policy"],"approach":"welfare-reform","summary":"Food-awareness organisation working to accelerate the shift to a sustainable food system by making plant-rich foods and alternative proteins more accessible; offices in 14 countries; runs a start-up incubator.","website":"https://proveg.org","hq":null,"founded":"2017","sources":[{"url":"https://proveg.org/about-us/","title":"About us - ProVeg International","accessed":"2026-11-05","published":null},{"url":"https://en.wikipedia.org/wiki/ProVeg_International","title":"ProVeg International - Wikipedia","accessed":"2026-11-05","published":null}],"notes":"Founded 2017 per Wikipedia (from older national groups). Approach set to welfare-reform as a best fit; it frames work around food-system change.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('vegan-outreach','Vegan Outreach','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":[],"categories":["advocacy-campaigns"],"species":["farmed-animals"],"regions":["north-america","south-asia","southeast-asia","global"],"countries":["US","IN","VN"],"interventions":["diet-change","public-awareness","education"],"approach":"abolitionist","summary":"US nonprofit founded in 1993 advocating against the exploitation of farmed animals through outreach, an online ''10 Weeks to Vegan'' programme, vegan mentorship, and institutional food work in India and Vietnam.","website":"https://veganoutreach.org","hq":"United States","founded":"1993","sources":[{"url":"https://veganoutreach.org/about/","title":"About - Vegan Outreach","accessed":"2026-11-05","published":null},{"url":"https://en.wikipedia.org/wiki/Vegan_Outreach","title":"Vegan Outreach - Wikipedia","accessed":"2026-11-05","published":null}],"notes":"Approach ''abolitionist'' reflects its vegan advocacy mission; could be classed as mixed.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('forum-animal','Fórum Nacional de Proteção e Defesa Animal','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["Fórum Animal"],"categories":["advocacy-campaigns","policy-law"],"species":["all-animals","farmed-animals"],"regions":["latin-america"],"countries":["BR"],"interventions":["legislation-policy","public-awareness","education"],"approach":"mixed","summary":"Brazilian NGO working for animal rights and against cruelty across species; activities include policy advocacy, a voter guide on animal issues and seminars on One Health and animal protection.","website":"https://forumanimal.org","hq":"Brazil","founded":null,"sources":[{"url":"https://forumanimal.org/","title":"Fórum Nacional de Proteção e Defesa Animal","accessed":"2026-11-05","published":null}],"notes":"About page URL not found; summary based on homepage description and feed items. Founding year not verified.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('people-for-animals-india','People for Animals','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["PFA"],"categories":["advocacy-campaigns","sanctuary-rescue"],"species":["all-animals","companion-animals"],"regions":["south-asia"],"countries":["IN"],"interventions":["sanctuary","legislation-policy","public-awareness"],"approach":"welfare-reform","summary":"Indian animal welfare organisation with local units across the country; handles cruelty reports, animal rescue and shelters, and provides public information on animal protection law.","website":"https://www.peopleforanimalsindia.org","hq":"India","founded":"1992","sources":[{"url":"https://peopleforanimalsindia.org/","title":"People for Animals | India''s largest animal welfare organisation","accessed":"2026-11-05","published":null},{"url":"https://en.wikipedia.org/wiki/People_for_Animals","title":"People for Animals - Wikipedia","accessed":"2026-11-05","published":null}],"notes":"Founded 1992, New Delhi per Wikipedia. Self-description ''India''s largest animal welfare organisation'' not independently verified.","merged_from":[]}',0,'2026-11-05','2026-11-20T00:05:21.099Z');
