INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('humanny-pokrok','Humánny pokrok','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["Humane Progress"],"categories":["advocacy-campaigns"],"species":["farmed-animals","chickens"],"regions":["europe"],"countries":["SK"],"interventions":["corporate-campaigns","legislation-policy","public-awareness"],"approach":"welfare-reform","summary":"Slovak organisation working for animals kept in industrial farming through gradual systemic change: ending the worst practices, corporate responsibility commitments, legislation protecting animals, and educating the public about farming conditions.","website":"https://humannypokrok.sk","hq":"Slovakia","founded":null,"sources":[{"url":"https://humannypokrok.sk/o-nas/","title":"O nás - Humánny pokrok","accessed":"2026-11-19","published":null},{"url":"https://humannypokrok.sk/","title":"Humánny pokrok (homepage)","accessed":"2026-11-19","published":null}],"notes":"About page says it has worked ''for 15 years'' (as read Nov 2026); exact founding year not stated. English alias is a translation.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('lav-italy','LAV','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["Lega Anti Vivisezione","LAV ETS"],"categories":["advocacy-campaigns","policy-law"],"species":["all-animals","animals-in-research","wild-animals","farmed-animals"],"regions":["europe"],"countries":["IT"],"interventions":["legislation-policy","investigations","public-awareness","litigation"],"approach":"mixed","summary":"Italian animal rights association (Lega Anti Vivisezione) active since 1977. Campaigns and petitions on hunting and wildlife, circuses, animal experimentation and other uses of animals, and publishes investigations.","website":"https://www.lav.it","hq":"Italy","founded":"1977","sources":[{"url":"https://www.lav.it/","title":"LAV - dalla parte degli animali (homepage)","accessed":"2026-11-19","published":null}],"notes":"Homepage (Nov 2026) foregrounds wildlife, circus and research-animal campaigns; its farmed-animal work was not checked on a fetched page. No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('dansk-vegetarisk-forening','Dansk Vegetarisk Forening','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["DVF","Vegetarian Society of Denmark"],"categories":["advocacy-campaigns","alt-protein","policy-law"],"species":["farmed-animals"],"regions":["europe"],"countries":["DK"],"interventions":["legislation-policy","diet-change","alt-proteins","certification-standards","litigation"],"approach":"neutral-infrastructure","summary":"Danish organisation founded in 1896 that works to shift Denmark''s food system toward plant-based: policy and legislation work including strategic lawsuits, a plant protein network, training for professional kitchens, labelling schemes and international knowledge-sharing.","website":"https://vegetarisk.dk","hq":"Denmark","founded":"1896","sources":[{"url":"https://vegetarisk.dk/english/","title":"Vegetarian Society of Denmark (English page)","accessed":"2026-11-19","published":null},{"url":"https://animalcharityevaluators.org/charity-review/dansk-vegetarisk-forening/","title":"Dansk Vegetarisk Forening - ACE charity review","accessed":"2026-11-19","published":null}],"notes":"Listed by ACE as an Evaluated Charity (Nov 2026). Founding year from the ACE review. Site read via a fetch tool; direct connection from the research sandbox failed, so no feed check was possible.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('ethical-farming-ireland','Ethical Farming Ireland','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["EFI"],"categories":["advocacy-campaigns"],"species":["farmed-animals","cows"],"regions":["europe"],"countries":["IE"],"interventions":["legislation-policy","public-awareness","litigation","diet-change"],"approach":"welfare-reform","summary":"Volunteer-run Irish group campaigning for better conditions for farm animals, specifically against factory farming and live animal export, including the transport of unweaned calves. Also encourages a move to more plant-based foods.","website":"https://www.ethicalfarmingireland.com","hq":"Ireland","founded":null,"sources":[{"url":"https://www.ethicalfarmingireland.com/","title":"Ethical Farming Ireland - Campaigning for farm animals (homepage)","accessed":"2026-11-19","published":null},{"url":"https://www.ethicalfarmingireland.com/about","title":"About - Ethical Farming Ireland","accessed":"2026-11-19","published":null}],"notes":"Small volunteer group; included as the Irish anchor for farmed-animal campaigning. Homepage (Nov 2026) reports a formal legal notice issued to a ferry company over calf transport.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('party-for-animals','Partij voor de Dieren','organisation',NULL,'policy-law','movement','active','{"aliases":["Party for the Animals","PvdD"],"categories":["policy-law"],"species":["all-animals"],"regions":["europe"],"countries":["NL"],"interventions":["legislation-policy","public-awareness"],"approach":"mixed","summary":"Dutch political party founded in 2002 with animal rights and animal welfare among its main goals. Holds seats in the Dutch House of Representatives and supports animal-politics parties in other countries through an affiliated foundation.","website":"https://www.partyfortheanimals.com","hq":"Netherlands","founded":"2002","sources":[{"url":"https://www.partyfortheanimals.com/","title":"Party for the Animals (international site)","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/Party_for_the_Animals","title":"Party for the Animals - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"Political party. Wikipedia (Nov 2026): three of 150 House seats after the 2025 general election. The international site refers to the Animal Politics Foundation.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('ep-intergroup-welfare-conservation-animals','Intergroup on the Welfare and Conservation of Animals','network',NULL,'policy-law','movement','active','{"aliases":["European Parliament Animal Welfare Intergroup"],"categories":["policy-law"],"species":["all-animals"],"regions":["europe"],"countries":[],"interventions":["legislation-policy"],"approach":"welfare-reform","summary":"Cross-party group of Members of the European Parliament working to advance animal welfare and conservation in EU policymaking. Holds regular sessions on EU files such as fur, livestock strategy and animal testing; its secretariat is provided by Eurogroup for Animals.","website":"https://www.animalwelfareintergroup.eu","hq":null,"founded":null,"sources":[{"url":"https://www.animalwelfareintergroup.eu/","title":"Intergroup on the Welfare and Conservation of Animals (homepage)","accessed":"2026-11-19","published":null}],"notes":"Secretariat provided by Eurogroup for Animals (already on the map as ''eurogroup-for-animals''); not set as parent because the Intergroup is a parliamentary body.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('care-conference','Conference on Animal Rights in Europe','programme','anima-international','movement-infrastructure','movement','active','{"aliases":["CARE","CARE Conference"],"categories":["movement-infrastructure"],"species":["all-animals","farmed-animals"],"regions":["europe"],"countries":["PL"],"interventions":["capacity-building"],"approach":"neutral-infrastructure","summary":"Annual animal rights conference held in Warsaw and online, organised by Anima International, with talks, workshops and networking sessions for advocates from many organisations and countries.","website":"https://careconf.eu","hq":"Poland","founded":null,"sources":[{"url":"https://careconf.eu/","title":"CARE 2026: Animal Rights Conference (Warsaw)","accessed":"2026-11-19","published":null}],"notes":"No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('rspca','Royal Society for the Prevention of Cruelty to Animals','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["RSPCA"],"categories":["advocacy-campaigns","sanctuary-rescue","policy-law"],"species":["all-animals","companion-animals","farmed-animals","wild-animals"],"regions":["uk"],"countries":["GB"],"interventions":["legislation-policy","certification-standards","public-awareness","sanctuary"],"approach":"welfare-reform","summary":"Animal welfare charity operating in England and Wales, founded in 1824 and funded mainly by donations. Specialises in animal rescue and in advancing the welfare of all animals; its RSPCA Assured scheme certifies farms to RSPCA welfare standards.","website":"https://www.rspca.org.uk","hq":"United Kingdom","founded":"1824","sources":[{"url":"https://www.rspca.org.uk/","title":"RSPCA (homepage)","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/RSPCA","title":"RSPCA - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"Parent body of RSPCA Assured, which is already on the map as ''rspca-assured''. HQ Horsham, West Sussex (Wikipedia). No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('animal-aid','Animal Aid','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":[],"categories":["advocacy-campaigns"],"species":["all-animals","farmed-animals","animals-in-research"],"regions":["uk"],"countries":["GB"],"interventions":["investigations","public-awareness","diet-change","education"],"approach":"abolitionist","summary":"British animal rights organisation founded in 1977. Campaigns peacefully against all forms of animal abuse, carries out undercover investigations, and promotes a cruelty-free lifestyle with free outreach and educational materials.","website":"https://www.animalaid.org.uk","hq":"United Kingdom","founded":"1977","sources":[{"url":"https://www.animalaid.org.uk/","title":"Animal Aid (homepage)","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/Animal_Aid","title":"Animal Aid - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"Based in Tonbridge (Wikipedia). /feed/ returned RSS with no items, so no feed listed.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('vegan-society','The Vegan Society','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":[],"categories":["advocacy-campaigns","community-media"],"species":["all-animals","farmed-animals"],"regions":["uk","global"],"countries":["GB"],"interventions":["diet-change","public-awareness","certification-standards","education"],"approach":"abolitionist","summary":"UK registered charity founded in 1944, the oldest vegan organisation, whose founders coined the word ''vegan''. Provides information and campaigns on veganism in the UK and internationally.","website":"https://www.vegansociety.com","hq":"United Kingdom","founded":"1944","sources":[{"url":"https://www.vegansociety.com/about-us","title":"About The Vegan Society","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/The_Vegan_Society","title":"The Vegan Society - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"Based in Birmingham (Wikipedia). Its Vegan Trademark product-labelling scheme was not checked on a fetched page.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
