INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('cruelty-free-international','Cruelty Free International','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["British Union for the Abolition of Vivisection","BUAV"],"categories":["advocacy-campaigns","policy-law"],"species":["animals-in-research"],"regions":["global","uk","europe"],"countries":["GB"],"interventions":["legislation-policy","certification-standards","investigations","public-awareness"],"approach":"abolitionist","summary":"Organisation working to end animal testing worldwide. Works with politicians, businesses and regulators, promotes non-animal science, and supports companies with cruelty-free certification. Founded in 1898 as the British Union for the Abolition of Vivisection.","website":"https://crueltyfreeinternational.org","hq":"United Kingdom","founded":"1898","sources":[{"url":"https://www.crueltyfreeinternational.org/our-work/about-us/","title":"About Us - Cruelty Free International","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/Cruelty_Free_International","title":"Cruelty Free International - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"History (BUAV, 1898; Leaping Bunny certification) from Wikipedia.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
