INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('social-change-lab','Social Change Lab','organisation',NULL,'welfare-science','movement','active','{"aliases":[],"categories":["welfare-science","movement-infrastructure"],"species":["all-animals"],"regions":["uk","global"],"countries":["GB"],"interventions":["research","capacity-building"],"approach":"research","summary":"Non-profit that studies how social movements and protest shape public opinion, policy and social change, publishing open-access research for activists, researchers and funders. Animal rights is one of its research areas, alongside climate and AI safety.","website":"https://www.socialchangelab.org","hq":"United Kingdom","founded":null,"sources":[{"url":"https://www.socialchangelab.org/","title":"Social Change Lab (homepage)","accessed":"2026-11-19","published":null}],"notes":"Not an animal-specific organisation. UK base inferred from its UK press phone number. No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
