INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('world-federation-for-animals','World Federation for Animals','network',NULL,'policy-law','movement','active','{"aliases":["WFA"],"categories":["policy-law","movement-infrastructure"],"species":["all-animals"],"regions":["global"],"countries":[],"interventions":["legislation-policy","capacity-building"],"approach":"welfare-reform","summary":"Federation of more than 70 NGOs working for recognition of animal welfare in the sustainable development agenda. Focuses on integrating animal welfare into international health, food and environmental regimes and into trade and development finance rules.","website":"https://wfa.org","hq":null,"founded":null,"sources":[{"url":"https://wfa.org/","title":"World Federation for Animals (homepage)","accessed":"2026-11-19","published":null},{"url":"https://wfa.org/the-team/","title":"The World Federation for Animals Team","accessed":"2026-11-19","published":null}],"notes":"Secretariat works remotely across five countries (team page). No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('better-chicken-commitment','Better Chicken Commitment','resource',NULL,'advocacy-campaigns','movement','active','{"aliases":["European Chicken Commitment","ECC"],"categories":["advocacy-campaigns"],"species":["chickens"],"regions":["global","north-america","europe","uk","oceania","latin-america"],"countries":["US","CA","GB","AU","NZ","BR"],"interventions":["corporate-campaigns","certification-standards","farm-practices"],"approach":"welfare-reform","summary":"Set of broiler chicken welfare standards that food companies are asked to commit to publicly. The site reports more than 200 company commitments since November 2016 and publishes regional versions for the US, UK, EU, Canada, Australia/New Zealand and Brazil.","website":"https://betterchickencommitment.com","hq":null,"founded":"2016","sources":[{"url":"https://betterchickencommitment.com/us/","title":"The Better Chicken Commitment - BCC [US]","accessed":"2026-11-19","published":null}],"notes":"A shared policy standard, not an organisation; the site does not name a single owner on the page fetched. The EU version is widely known as the European Chicken Commitment (alias from general knowledge). ''founded'' is the date of the first commitments given on the site. No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
