INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('aspca','American Society for the Prevention of Cruelty to Animals','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["ASPCA"],"categories":["advocacy-campaigns","sanctuary-rescue","policy-law"],"species":["companion-animals","farmed-animals","chickens"],"regions":["north-america"],"countries":["US"],"interventions":["legislation-policy","corporate-campaigns","public-awareness","sanctuary"],"approach":"welfare-reform","summary":"US non-profit founded in 1866 and based in New York City, dedicated to preventing cruelty to animals. Its farm animal programme calls for greater transparency in animal agriculture, stronger laws and an end to the cruellest factory farming practices.","website":"https://www.aspca.org","hq":"United States","founded":"1866","sources":[{"url":"https://www.aspca.org/protecting-farm-animals","title":"Protecting Farm Animals from Abuse and Suffering | ASPCA","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/American_Society_for_the_Prevention_of_Cruelty_to_Animals","title":"American Society for the Prevention of Cruelty to Animals - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"Included for its farm animal welfare programme (the Global Animal Partnership site refers to an ''ASPCA ShopKind'' product listing). A second feed exists at https://www.aspca.org/blog/feed/.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('animal-welfare-institute','Animal Welfare Institute','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["AWI"],"categories":["advocacy-campaigns","policy-law"],"species":["all-animals","farmed-animals","animals-in-research","wild-animals"],"regions":["north-america"],"countries":["US"],"interventions":["legislation-policy","research","public-awareness","certification-standards"],"approach":"welfare-reform","summary":"Washington, D.C. non-profit dedicated since 1951 to alleviating animal suffering caused by people, in agriculture, commerce, homes and communities, research and the wild. Its farmed animal programme covers factory farms, aquaculture, slaughter, transport and labelling.","website":"https://awionline.org","hq":"United States","founded":"1951","sources":[{"url":"https://awionline.org/content/about-awi","title":"About AWI - Animal Welfare Institute","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/Animal_Welfare_Institute","title":"Animal Welfare Institute - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"Site returned 403 to direct requests from the research sandbox; the About page was read through a fetch tool, so no feed check was possible.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('farm-forward','Farm Forward','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":[],"categories":["advocacy-campaigns"],"species":["farmed-animals","chickens"],"regions":["north-america"],"countries":["US"],"interventions":["public-awareness","investigations","legislation-policy","certification-standards"],"approach":"mixed","summary":"US non-profit whose stated mission is to end factory farming by changing farming, changing policy and changing the stories told about animal agriculture. Runs a campaign against ''humanewashing'', the deceptive welfare labelling of animal products.","website":"https://www.farmforward.com","hq":"United States","founded":null,"sources":[{"url":"https://www.farmforward.com/","title":"Farm Forward (homepage)","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/Farm_Forward","title":"Farm Forward - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"Founding year not confirmed on a fetched page (commonly given as 2007); left null.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('nonhuman-rights-project','Nonhuman Rights Project','organisation',NULL,'policy-law','movement','active','{"aliases":["NhRP"],"categories":["policy-law"],"species":["all-animals","wild-animals"],"regions":["north-america"],"countries":["US"],"interventions":["litigation","legislation-policy","education"],"approach":"abolitionist","summary":"US civil rights organisation working to secure fundamental rights for nonhuman animals through litigation, legislation and education. Its cases seek to change the legal status of certain animals from ''things'' to rights-holders, with rights such as bodily liberty.","website":"https://www.nonhumanrights.org","hq":"United States","founded":"2007","sources":[{"url":"https://www.nonhumanrights.org/about-us/","title":"About Us | Nonhuman Rights Project","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/Nonhuman_Rights_Project","title":"Nonhuman Rights Project - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"Wikipedia: founded 2007 as a project of the Center for the Expansion of Fundamental Rights, renamed NhRP in 2012. ACE Movement Grant recipient in 2020.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('legal-impact-for-chickens','Legal Impact for Chickens','organisation',NULL,'policy-law','movement','active','{"aliases":["LIC"],"categories":["policy-law"],"species":["chickens","farmed-animals"],"regions":["north-america"],"countries":["US"],"interventions":["litigation"],"approach":"welfare-reform","summary":"US animal law non-profit founded in 2021 that brings civil lawsuits against companies and executives over the treatment of chickens and other farmed animals, aiming to enforce existing cruelty laws in industrial farming.","website":"https://www.legalimpactforchickens.org","hq":"United States","founded":"2021","sources":[{"url":"https://www.legalimpactforchickens.org/","title":"Legal Impact for Chickens (homepage)","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/Legal_Impact_for_Chickens","title":"Legal Impact for Chickens - Wikipedia","accessed":"2026-11-19","published":null},{"url":"https://animalcharityevaluators.org/evaluated-charities/","title":"Evaluated Charities - Animal Charity Evaluators","accessed":"2026-11-19","published":null}],"notes":"Listed among ACE''s evaluated charities (Nov 2026). Founding date and Sacramento headquarters from Wikipedia.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('greener-by-default','Greener by Default','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["GBD"],"categories":["advocacy-campaigns","alt-protein"],"species":["farmed-animals"],"regions":["north-america","europe"],"countries":["US"],"interventions":["diet-change","corporate-campaigns","research"],"approach":"neutral-infrastructure","summary":"Organisation that works with hospitals, universities, corporate dining programmes and city governments to make plant-based food the default menu option while keeping meat and dairy available on request. Named an ACE Recommended Charity for 2026.","website":"https://www.greenerbydefault.com","hq":"United States","founded":null,"sources":[{"url":"https://www.greenerbydefault.com/","title":"Greener by Default (homepage)","accessed":"2026-11-19","published":null},{"url":"https://animalcharityevaluators.org/recommended-charities/","title":"Recommended Charities - Animal Charity Evaluators","accessed":"2026-11-19","published":null}],"notes":"ACE describes it as working in North America and Europe. US headquarters not stated on the pages fetched - check.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
