INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('pro-animal-future','Pro-Animal Future','organisation',NULL,'policy-law','movement','active','{"aliases":[],"categories":["policy-law","advocacy-campaigns"],"species":["farmed-animals"],"regions":["north-america"],"countries":["US"],"interventions":["legislation-policy","public-awareness"],"approach":"abolitionist","summary":"US organisation building a political movement to end factory farming through citizen ballot initiatives and local legislation, with regional volunteer chapters. Reports a 2026 Washington, DC initiative banning sales of force-fed foie gras and a similar Portland ordinance.","website":"https://proanimal.org","hq":"United States","founded":null,"sources":[{"url":"https://proanimal.org/","title":"Pro-Animal Future (homepage)","accessed":"2026-11-19","published":null},{"url":"https://paxfauna.org/","title":"Pax Fauna (homepage)","accessed":"2026-11-19","published":null},{"url":"https://animalcharityevaluators.org/movement-grants/past-movement-grants-recipients/","title":"ACE Movement Grants: past recipients","accessed":"2026-11-19","published":null}],"notes":"Grew out of Pax Fauna''s research (Pax Fauna''s site carries Pro-Animal Future''s 10-year plan). ACE Movement Grant recipient in 2024.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
