INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('ubc-animal-welfare-program','UBC Animal Welfare Program','programme',NULL,'welfare-science','movement','active','{"aliases":["University of British Columbia Animal Welfare Program"],"categories":["welfare-science"],"species":["farmed-animals","cows","animals-in-research","companion-animals"],"regions":["north-america"],"countries":["CA"],"interventions":["research","education","farm-practices"],"approach":"research","summary":"Animal welfare science programme at the University of British Columbia, started in 1997. Its mission is to improve the welfare and humane care of animals in agriculture, research, companionship and other areas through research, education and public outreach.","website":"https://awp.landfood.ubc.ca","hq":"Canada","founded":"1997","sources":[{"url":"https://awp.landfood.ubc.ca/","title":"UBC Animal Welfare Program (homepage)","accessed":"2026-11-19","published":null}],"notes":"''cows'' tagged for its dairy cattle welfare research, which is from general knowledge rather than the page fetched.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('innovate-animal-ag','Innovate Animal Ag','organisation',NULL,'welfare-technology','movement','active','{"aliases":[],"categories":["welfare-technology"],"species":["chickens","pigs","farmed-animals"],"regions":["north-america"],"countries":["US"],"interventions":["research","producer-engagement","farm-practices","grantmaking"],"approach":"welfare-reform","summary":"Non-profit industry think tank that works with producers and the supply chain to speed adoption of technologies that improve animal health and welfare. Publishes technology overviews and market reports on in-ovo sexing, immunocastration and on-farm hatching, and offers technology grants.","website":"https://innovateanimalag.org","hq":"United States","founded":null,"sources":[{"url":"https://innovateanimalag.org/","title":"Innovate Animal Ag (homepage)","accessed":"2026-11-19","published":null},{"url":"https://innovateanimalag.org/about","title":"About - Innovate Animal Ag","accessed":"2026-11-19","published":null}],"notes":"US base inferred from its US-focused reports; EA Animal Welfare Fund grantee. No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('orbem','Orbem','organisation',NULL,'welfare-technology','movement','active','{"aliases":["Orbem GmbH"],"categories":["welfare-technology"],"species":["chickens"],"regions":["europe","north-america"],"countries":["DE","US"],"interventions":["farm-practices"],"approach":"neutral-infrastructure","summary":"German technology company applying AI-powered MRI imaging to food and health. Its poultry products include in-ovo sexing, which identifies the sex of chicks in the egg before hatching, and fertilisation-status scanning for hatcheries.","website":"https://www.orbem.ai","hq":"Germany","founded":null,"sources":[{"url":"https://www.orbem.ai/","title":"Orbem | AI-Powered MRI for Food & Health Sustainability (homepage)","accessed":"2026-11-19","published":null}],"notes":"Commercial company, not an advocacy organisation; included as an in-ovo sexing provider. Site footer lists offices in Germany and Houston, Texas. No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('seleggt','SELEGGT','programme',NULL,'welfare-technology','movement','active','{"aliases":["SelEggt","respeggt","respeggt group"],"categories":["welfare-technology"],"species":["chickens"],"regions":["europe","north-america"],"countries":[],"interventions":["farm-practices"],"approach":"neutral-infrastructure","summary":"In-ovo sexing technology offered by HatchTech Group, which determines the sex of hatching eggs from around day 8-9 of incubation so that male layer chicks need not be hatched, alongside egg-handling equipment for hatcheries.","website":"https://www.seleggt.com","hq":null,"founded":null,"sources":[{"url":"https://www.seleggt.com/","title":"Home - Seleggt (respeggt.com redirects here)","accessed":"2026-11-19","published":null},{"url":"https://hatchtechgroup.com/seleggt/","title":"SELEGGT - HatchTech Group (respeggt-group.com redirects here)","accessed":"2026-11-19","published":null},{"url":"https://hatchtechgroup.com/","title":"HatchTech Group (homepage)","accessed":"2026-11-19","published":null}],"notes":"Commercial technology, not an advocacy organisation. When checked, respeggt.com and respeggt-group.com both redirected to SELEGGT/HatchTech Group pages, so ''respeggt'' is recorded as an alias; the corporate history behind the change was not researched. A second Dutch in-ovo provider, In Ovo (inovo.nl), showed a closed/maintenance page.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('sentient-futures','Sentient Futures','organisation',NULL,'movement-infrastructure','movement','active','{"aliases":["AI for Animals"],"categories":["movement-infrastructure","incubation-careers"],"species":["all-animals"],"regions":["global","north-america"],"countries":["US"],"interventions":["capacity-building","education","research"],"approach":"neutral-infrastructure","summary":"US non-profit supporting research, policy and community on the welfare of animals and artificial minds. Runs an AI x Animals course, a project incubator, a residency and summits, and hosts an online community it puts at more than 1,700 members.","website":"https://www.sentientfutures.ai","hq":"United States","founded":null,"sources":[{"url":"https://www.sentientfutures.ai/","title":"Sentient Futures (homepage)","accessed":"2026-11-19","published":null},{"url":"https://animalcharityevaluators.org/movement-grants/past-movement-grants-recipients/","title":"ACE Movement Grants: past recipients","accessed":"2026-11-19","published":null}],"notes":"ACE lists it as ''Sentient Futures (formerly AI for Animals)''; EA Animal Welfare Fund records list ''AI for Animals, a project of Hive Community, Inc'', so it began as a project of Hive (on the map as ''hive''). No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('mission-motor','The Mission Motor','organisation',NULL,'movement-infrastructure','movement','active','{"aliases":[],"categories":["movement-infrastructure"],"species":["farmed-animals"],"regions":["global","europe"],"countries":["NL"],"interventions":["capacity-building","data-tools"],"approach":"neutral-infrastructure","summary":"Charity registered in the Netherlands that gives free training and coaching to organisations in the farmed animal and food-system change movement so they can build monitoring, evaluation and learning (MEL) practices and use data to increase their impact.","website":"https://www.themissionmotor.org","hq":"Netherlands","founded":null,"sources":[{"url":"https://www.themissionmotor.org/","title":"The Mission Motor (homepage)","accessed":"2026-11-19","published":null},{"url":"https://animalcharityevaluators.org/movement-grants/past-movement-grants-recipients/","title":"ACE Movement Grants: past recipients","accessed":"2026-11-19","published":null}],"notes":"ACE Movement Grant recipient in early 2026; EA Animal Welfare Fund grantee. No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('how-i-learned-to-love-shrimp','How I Learned to Love Shrimp','resource',NULL,'community-media','movement','active','{"aliases":[],"categories":["community-media"],"species":["farmed-animals","wild-animals","all-animals"],"regions":["global"],"countries":[],"interventions":["public-awareness","education"],"approach":"neutral-infrastructure","summary":"Podcast about promising ways to help animals and build the animal advocacy movement. Interviews practitioners and experts on farmed and wild animal welfare, alternative proteins, policy change, protest and movement strategy.","website":"https://www.howilearnedtoloveshrimp.com","hq":null,"founded":null,"sources":[{"url":"https://www.howilearnedtoloveshrimp.com/","title":"How I Learned To Love Shrimp: Animal Advocacy Podcast (homepage)","accessed":"2026-11-19","published":null}],"notes":"Podcast feed is hosted off-site and was not checked; no RSS link on the homepage.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('269-liberation-animale','269 Libération animale','organisation',NULL,'direct-action','movement','unclear','{"aliases":["269 Life Libération Animale"],"categories":["direct-action"],"species":["farmed-animals"],"regions":["europe"],"countries":["FR"],"interventions":["direct-action","sanctuary"],"approach":"abolitionist","summary":"French antispeciesist association created in Lyon in 2016, known for direct action against speciesism and for running sanctuaries. Originally linked to the association 269 Life France, it later became independent and shortened its name.","website":"https://fr.wikipedia.org/wiki/269_Lib%C3%A9ration_animale","hq":"France","founded":"2016","sources":[{"url":"https://fr.wikipedia.org/wiki/269_Lib%C3%A9ration_animale","title":"269 Libération animale - Wikipédia (fr)","accessed":"2026-11-19","published":null}],"notes":"Encyclopedic entry only; the website field points to Wikipedia rather than the group''s own site. Current activity level not verified, so status is ''unclear''.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('meat-victims','Meat the Victims','network',NULL,'direct-action','movement','unclear','{"aliases":[],"categories":["direct-action"],"species":["farmed-animals","pigs"],"regions":["oceania","north-america","europe","uk"],"countries":["AU","CA","NL","IE","GB"],"interventions":["direct-action","protest"],"approach":"abolitionist","summary":"International animal rights collective that began in Australia in 2018 and describes its aim as abolishing animal exploitation. News media reported its protests at farms in Canada and the Netherlands in 2019, which led to arrests and, in Canada, to criminal convictions.","website":"https://thetyee.ca/News/2022/12/13/Excelsior-Case-Animal-Welfare/","hq":null,"founded":"2018","sources":[{"url":"https://thetyee.ca/News/2022/12/13/Excelsior-Case-Animal-Welfare/","title":"The Escalating Fight Against Animal Agriculture | The Tyee","accessed":"2026-11-19","published":"2022-12-13"},{"url":"https://www.dutchnews.nl/2019/05/police-end-pig-farm-occupation-dozens-of-activists-arrested/","title":"Police end pig farm occupation, dozens of activists arrested - DutchNews.nl","accessed":"2026-11-19","published":"2019-05-14"}],"notes":"Encyclopedic entry only; the website field points to a news article rather than the group''s own channels. The Tyee also reports protests in Ireland, the UK and Israel. No documented activity after 2022 was found, so status is ''unclear''.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('provieh','PROVIEH','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["PROVIEH e.V.","Verein gegen tierquälerische Massentierhaltung"],"categories":["advocacy-campaigns"],"species":["farmed-animals"],"regions":["europe"],"countries":["DE"],"interventions":["legislation-policy","public-awareness","farm-practices"],"approach":"welfare-reform","summary":"German association for the protection of farmed animals, based in Kiel. Since 1973 it has worked for species-appropriate husbandry and against industrial intensive animal farming.","website":"https://www.provieh.de","hq":"Germany","founded":"1973","sources":[{"url":"https://www.provieh.de/","title":"PROVIEH (homepage)","accessed":"2026-11-19","published":null},{"url":"https://de.wikipedia.org/wiki/Provieh","title":"Provieh - Wikipedia (de)","accessed":"2026-11-19","published":null}],"notes":null,"merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('tier-im-recht','Stiftung für das Tier im Recht','organisation',NULL,'policy-law','movement','active','{"aliases":["TIR","Tier im Recht","Foundation for the Animal in the Law"],"categories":["policy-law"],"species":["all-animals"],"regions":["europe"],"countries":["CH"],"interventions":["legislation-policy","research","education"],"approach":"welfare-reform","summary":"Swiss non-profit foundation that has advocated for strong legal protection of animals since 1996. Works for animal-friendly laws and their enforcement and gives information and advice on animal-related legal questions.","website":"https://www.tierimrecht.org","hq":"Switzerland","founded":null,"sources":[{"url":"https://www.tierimrecht.org/en/","title":"Stiftung für das Tier im Recht (TIR) - English homepage","accessed":"2026-11-19","published":null},{"url":"https://de.wikipedia.org/wiki/Stiftung_f%C3%BCr_das_Tier_im_Recht","title":"Stiftung für das Tier im Recht - Wikipedia (de)","accessed":"2026-11-19","published":null}],"notes":"Site says it has campaigned ''since 1996''; exact founding date not confirmed, so left null. Seat Zürich per German Wikipedia. English alias is a translation. No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('oikeutta-elaimille','Oikeutta eläimille','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["Justice for Animals (Finland)","OE"],"categories":["advocacy-campaigns"],"species":["farmed-animals","fur-animals","all-animals"],"regions":["europe"],"countries":["FI"],"interventions":["investigations","public-awareness","diet-change","protest"],"approach":"abolitionist","summary":"Finnish animal rights organisation founded in 1995. Works to end the exploitation of animals and improve their status: it publicises conditions in the animal industry, campaigns for animal rights and promotes veganism.","website":"https://oikeuttaelaimille.fi","hq":"Finland","founded":"1995","sources":[{"url":"https://oikeuttaelaimille.fi/meista/","title":"Meistä - Oikeutta eläimille","accessed":"2026-11-19","published":null}],"notes":"English alias is a translation of the Finnish name.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('nahtamatud-loomad','Nähtamatud Loomad','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["Invisible Animals","MTÜ Nähtamatud Loomad"],"categories":["advocacy-campaigns"],"species":["farmed-animals","chickens"],"regions":["europe"],"countries":["EE"],"interventions":["corporate-campaigns","legislation-policy","diet-change","public-awareness"],"approach":"welfare-reform","summary":"Estonian animal protection organisation focused on farmed animal welfare, meat reduction and plant-based food, and systemic change, including a campaign for a legal ban on keeping hens in cages.","website":"https://nahtamatudloomad.ee","hq":"Estonia","founded":null,"sources":[{"url":"https://nahtamatudloomad.ee/","title":"Nähtamatud Loomad (homepage)","accessed":"2026-11-19","published":null},{"url":"https://animalcharityevaluators.org/movement-grants/past-movement-grants-recipients/","title":"ACE Movement Grants: past recipients","accessed":"2026-11-19","published":null}],"notes":"ACE Movement Grant recipient in 2026 (listed as ''Nähtamatud Loomad (Invisible Animals)''). The /en page returned a server error when fetched; Estonian homepage used. No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('eyes-on-animals','Eyes on Animals','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["EonA"],"categories":["advocacy-campaigns","welfare-technology"],"species":["farmed-animals","pigs","cows","chickens"],"regions":["europe"],"countries":["NL"],"interventions":["investigations","humane-slaughter","producer-engagement","farm-practices"],"approach":"welfare-reform","summary":"Amsterdam-based organisation that inspects farm animal transport, markets and slaughterhouses, reports breaches of European legislation to the authorities, and works with slaughter plants and transporters on stunning, catching and loading practices.","website":"https://www.eyesonanimals.com","hq":"Netherlands","founded":null,"sources":[{"url":"https://www.eyesonanimals.com/","title":"Eyes on Animals - Watching out for their Welfare (homepage)","accessed":"2026-11-19","published":null}],"notes":"Homepage (Nov 2026) also reports advisory work outside Europe (a seminar for Japanese slaughterhouses). Founding year not found on the page fetched.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('madre-brava','Madre Brava','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":[],"categories":["advocacy-campaigns","alt-protein"],"species":["farmed-animals"],"regions":["europe"],"countries":["DE","ES"],"interventions":["corporate-campaigns","research","diet-change","legislation-policy"],"approach":"neutral-infrastructure","summary":"International climate advocacy organisation whose mission is to protect people, animals and the planet through a shift to more plants in food. Publishes research and campaigns with partners, focusing on supermarkets, companies and policymakers.","website":"https://www.madrebrava.org","hq":null,"founded":null,"sources":[{"url":"https://www.madrebrava.org/","title":"Madre Brava (homepage)","accessed":"2026-11-19","published":null},{"url":"https://www.madrebrava.org/about","title":"About - Madre Brava","accessed":"2026-11-19","published":null}],"notes":"Climate/food-system organisation rather than an animal advocacy group. Germany and Spain are the countries its site content refers to most; full country list not verified. No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('better-food','Better Food Foundation','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["BFF"],"categories":["advocacy-campaigns"],"species":["farmed-animals"],"regions":["north-america"],"countries":["US"],"interventions":["diet-change","research","capacity-building"],"approach":"neutral-infrastructure","summary":"Non-profit working toward plant-rich foods as the norm. Educates and mobilises students, universities, employers, city officials, food service directors, media and NGO partners around climate-smart diets and institutional food change.","website":"https://www.betterfoodfoundation.org","hq":"United States","founded":null,"sources":[{"url":"https://www.betterfoodfoundation.org/about/","title":"About Better Food Foundation | Our Vision","accessed":"2026-11-19","published":null},{"url":"https://animalcharityevaluators.org/evaluated-charities/","title":"Evaluated Charities - Animal Charity Evaluators","accessed":"2026-11-19","published":null}],"notes":"Listed among ACE''s evaluated charities (Nov 2026). US base not stated on the page fetched - check.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('physicians-committee-for-responsible-medicine','Physicians Committee for Responsible Medicine','organisation',NULL,'advocacy-campaigns','movement','active','{"aliases":["PCRM","Physicians Committee"],"categories":["advocacy-campaigns","policy-law"],"species":["animals-in-research","farmed-animals"],"regions":["north-america"],"countries":["US"],"interventions":["research","diet-change","legislation-policy","education"],"approach":"mixed","summary":"Washington, DC non-profit founded in 1985 that promotes non-animal methods in research and medical education and plant-based diets for disease prevention. Reports more than 17,000 physician members and nearly one million members and supporters.","website":"https://www.pcrm.org","hq":"United States","founded":"1985","sources":[{"url":"https://www.pcrm.org/about-us","title":"About Us - Physicians Committee for Responsible Medicine","accessed":"2026-11-19","published":null},{"url":"https://en.wikipedia.org/wiki/Physicians_Committee_for_Responsible_Medicine","title":"Physicians Committee for Responsible Medicine - Wikipedia","accessed":"2026-11-19","published":null}],"notes":"Membership figures are the organisation''s own.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
