INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('yale-law-environment-animals-program','Law, Environment & Animals Program, Yale Law School','programme',NULL,'policy-law','movement','active','{"aliases":["LEAP","Yale LEAP","Law, Ethics & Animals Program"],"categories":["policy-law"],"species":["all-animals"],"regions":["north-america"],"countries":["US"],"interventions":["research","education","legislation-policy"],"approach":"research","summary":"Yale Law School programme that supports learning and scholarship on the legal, scientific and moral questions raised by humanity''s treatment of other animals, and helps Yale scholars and students produce legal and political change. Hosts the ''When We Talk About Animals'' podcast.","website":"https://law.yale.edu/animals","hq":"United States","founded":null,"sources":[{"url":"https://law.yale.edu/animals","title":"Law, Environment & Animals Program | Yale Law School","accessed":"2026-11-19","published":null}],"notes":"Page title (Nov 2026) reads ''Law, Environment & Animals Program''; it was previously known as the Law, Ethics & Animals Program (general knowledge). No RSS feed found.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('scarlet-spark','Scarlet Spark','organisation',NULL,'movement-infrastructure','movement','active','{"aliases":[],"categories":["movement-infrastructure"],"species":["all-animals"],"regions":["north-america","global"],"countries":["US"],"interventions":["capacity-building"],"approach":"neutral-infrastructure","summary":"Non-profit providing free leadership development and organisational support to animal protection organisations, covering strategy, recruitment, retention, workplace culture and team collaboration.","website":"https://www.scarletspark.org","hq":null,"founded":null,"sources":[{"url":"https://www.scarletspark.org/","title":"Scarlet Spark | animal advocacy consulting (homepage)","accessed":"2026-11-19","published":null}],"notes":"EA Animal Welfare Fund grantee. US base not stated on the page fetched.","merged_from":[]}',0,'2026-11-19','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('washington-octopus-farming-ban-2024','legal_development','Washington State bans octopus farming (HB 1153)','House Bill 1153, sponsored by Rep. Strom Peterson, prohibiting the farming of octopus in Washington State was signed by the governor; the policy takes effect 90 days after signature.','2024-03','2024-03-13','2026-11-05','https://housedemocrats.wa.gov/blog/2024/03/13/octopuses-in-washington-to-remain-in-their-little-hideaways-beneath-the-waves-safe-from-farming/','Octopuses in Washington to remain in their little hideaways beneath the waves, safe from farming. – Washington State House Democrats',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Exact signing day not stated on the source page (post dated 2024-03-13 says the bill ''has been signed''). Described by advocates as the first octopus farming ban.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('california-octo-act-2024','legal_development','California signs OCTO Act banning octopus farming and sale of farmed octopus','Governor Gavin Newsom signed the California Oppose Cruelty to Octopuses (OCTO) Act, prohibiting octopus farming and sales of commercially farmed octopus; over 130 Aquatic Animal Alliance members signed a support letter and ALI gave testimony.','2024-09-27','2024-10-15','2026-11-05','https://www.ali.fish/blog/the-media-celebrates-californias-historic-ban-on-octopus-farming-tpg8b','The Media Celebrates California''s Historic Ban on Octopus Farming — Aquatic Life Institute',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Bill co-sponsored by Animal Legal Defense Fund and Social Compassion in Legislation (not entities in this dataset). Source is an advocacy organisation''s blog.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('efa-ciwf-octopus-farm-case-study-2024','report_published','Eurogroup/CIWF case study on environmental risks of Nueva Pescanova octopus farm','Eurogroup for Animals and Compassion in World Farming published a case study on the proposed Canary Islands octopus farm, noting the Canary Islands Government had rejected Nueva Pescanova''s simplified environmental impact assessment and required a fuller one.','2024-07-12','2024-07-12','2026-11-05','https://www.eurogroupforanimals.org/library/exposing-environmental-risks-octopus-farming','Exposing the environmental risks of octopus farming — Eurogroup for Animals',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Search results reported that Nueva Pescanova later withdrew its octopus farm plans (SeafoodSource), but that article was blocked (HTTP 403) and the withdrawal and its date were not verified.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('ali-certification-benchmark-2024','report_published','ALI releases 3rd Aquaculture Certification Schemes Benchmark','Aquatic Life Institute published the third edition of its benchmark of welfare requirements in 8 seafood certification schemes and 1 ratings agency; ASC ranked top (8/10, assessed on its draft farm standard) and RSPCA second.','2024-10','2024-10-07','2026-11-05','https://www.ali.fish/resource-library/aquaculture-certification-schemes-benchmark-2024','2024 Aquaculture Certification Schemes Benchmark: Aquatic Animal Welfare — Aquatic Life Institute',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','ASC score from ALI''s 2024-10-10 blog post; RSPCA ranking from ALI feed item titled ''RSPCA Ranks 2nd in 2024 Aquaculture Certification Schemes Benchmark'' (2024-10-18).','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('swp-ace-aquatec-portable-stunner-2024','project_active','First portable in-water shrimp stunner installed in Thailand','Thai shrimp farm Sea Farms became the first to install Ace Aquatec''s small transportable A-HSU stunning system for crustaceans, through a partnership with Shrimp Welfare Project.','2024-12-12','2024-12-12','2026-11-05','https://www.shrimpwelfareproject.org/blog/ace-aquatec-and-shrimp-welfare-project-launch-new-portable-in-water-stunning-system','Ace Aquatec and Shrimp Welfare Project launch new portable in-water stunning system',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated',NULL,'2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('scottish-parliament-fish-reception-2025','announcement','Scottish Parliament reception on farmed fish welfare','The Humane League UK, Animal Equality UK and The Animal Law Foundation held a reception in the Scottish Parliament on farmed fish welfare, calling for legislation requiring pre-slaughter stunning, as recommended by the Animal Welfare Committee in 2023.','2025-01-21','2025-01-22','2026-11-05','https://thehumaneleague.org.uk/article/parliamentary-reception-shines-a-light-on-forgotten-fishes','Parliamentary reception shines a light on forgotten fishes — The Humane League UK',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Event date inferred from the article (dated 22 Jan 2025) saying the reception was held ''last night''.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('coop-prawn-welfare-policy-2025','campaign_outcome','Co-op (UK) commits to electrical stunning for all farmed prawns by 2027','UK retailer Co-op stated that all its fresh and frozen prawns are ablation-free and committed to implementing electrical stunning across its whole prawn supply chain by 2027; the policy was developed with support from Aquatic Life Institute.','2025-03','2025-03-11','2026-11-05','https://www.ali.fish/blog/co-op-prawn-policy-2025','Co-op Announces Progressive Prawn Welfare Policy — Aquatic Life Institute',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Co-op''s own announcement was not fetched; quote is reproduced on ALI''s blog.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('animal-ask-fish-farming-economics-2025','report_published','Animal Ask review of fish farming economics in Europe','Animal Ask published a systematic review of the economics of European aquaculture (salmonids, bass and bream, carp), part of a multi-organisation project with Rethink Priorities and Welfare Footprint to guide fish welfare movement strategy.','2025-05-02','2025-05-02','2026-11-05','https://www.animalask.org/post/the-economics-of-fish-farming-and-fish-welfare-in-europe','The economics of fish farming and fish welfare in Europe — Animal Ask',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Publication date from the Animal Ask RSS feed. A companion post on mapping the European farmed fish supply chain is dated 2025-05-01.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('asc-farm-standard-launch-2025','announcement','ASC launches unified Farm Standard with welfare provisions','The Aquaculture Stewardship Council launched its unified Farm Standard in May 2025; Aquatic Life Institute described it as making aquatic animal welfare a central pillar after five years of its engagement with the revision.','2025-05','2025-06-03','2026-11-05','https://www.ali.fish/blog/asc-farm-standard-2025','Behind the Reform: ALI''s Role in Shaping the ASC Farm Standard Revision — Aquatic Life Institute',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Specific welfare clauses of the standard were not reviewed. ASC news (Oct 2026) reports the first salmon producer (Bakkafrost) certified against the new standard.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('wfi-trout-air-asphyxia-paper-2025','report_published','Welfare Footprint paper quantifies pain of trout air asphyxia','A Scientific Reports paper applying the Welfare Footprint Framework estimated about 10 (1.9-21.7) minutes of moderate to intense pain per rainbow trout killed by air asphyxia and modelled the cost-effectiveness of electrical stunning.','2025',NULL,'2026-11-05','https://welfarefootprint.org/publications/trout-air-asphyxia.html','Air asphyxia in rainbow trout slaughter | WFI',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Scientific Reports 15, 19850 (2025); DOI 10.1038/s41598-025-04272-1. Exact publication date not shown on WFI page.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('swp-4-billion-shrimps-milestone-2025','announcement','Shrimp Welfare Project''s 21st stunner MOU (CAMIMEX, Vietnam)','Vietnamese producer CAMIMEX joined SWP''s Humane Slaughter Initiative, receiving an electrical stunner, with Netherlands-based supplier Seafood Connection committing to prioritise buying stunned shrimps; SWP estimates the programme now reaches about 4 billion shrimps a year.','2025-09-16','2025-09-16','2026-11-05','https://www.shrimpwelfareproject.org/blog/major-milestone-for-humane-slaughter-shrimp-welfare-project-expected-to-help-4-billion-shrimps-annually-new-mou-with-camimex-seafood-connection','Major Milestone for Humane Slaughter: Shrimp Welfare Project Expected to Help 4 Billion Shrimps Annually; New MOU with CAMIMEX, Seafood Connection',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Impact figure is SWP''s own estimate.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('scotland-farmed-fish-welfare-guidance-commitment-2025','legal_development','Scottish Government commits to official guidance on farmed fish welfare','According to The Animal Law Foundation, the Scottish Government committed in September 2025 to introducing official guidance on fish welfare, after the Foundation argued that the industry Code of Good Practice does not explain how to meet legal obligations.','2025-09',NULL,'2026-11-05','https://animallawfoundation.org/offishial-guidance','OfFISHial Guidance — Animal Law Foundation',NULL,NULL,NULL,NULL,NULL,NULL,'reported','[]','curated','Reported by an advocacy organisation; Scottish Government statement not fetched.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('chile-octopus-farming-ban-bill-2025','legal_development','Bill to ban octopus farming introduced in Chile','Fundación Veg and Congresswoman Marisela Santibáñez submitted Bill No. 17913-12 to Chile''s Congress to ban centres or systems for breeding, reproducing or fattening octopod species nationwide, with technical support from the Aquatic Animal Alliance.','2025-10-15','2025-10-22','2026-11-05','https://aquaticanimalalliance.org/blog/chile-octopus','Chile takes a visionary step to protect octopuses and the oceans — Aquatic Animal Alliance',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Bill introduced only; passage status not checked. Year of 15 Oct inferred from feed date of the post (2025-10-22).','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('swp-ace-recommended-2025','announcement','Shrimp Welfare Project named ACE Recommended Charity for 2025','Animal Charity Evaluators named Shrimp Welfare Project one of its 2025 Recommended Charities, the third consecutive year SWP received the recommendation.','2025-11-04','2025-11-04','2026-11-05','https://www.shrimpwelfareproject.org/blog/press-release-ace-recommended-charity-2025','Shrimp Welfare Project Named 2025 Recommended Charity by Animal Charity Evaluators',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated',NULL,'2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('uk-animal-welfare-strategy-boiling-alive-2025','legal_development','England''s Animal Welfare Strategy says boiling crustaceans alive is not acceptable','The UK Government''s Animal Welfare Strategy for England stated that boiling crustaceans alive is not acceptable and committed to publishing guidance in 2026 on lawful humane killing methods; Crustacean Compassion and The Animal Law Foundation had campaigned on the issue.','2025-12-22','2026-02-06','2026-11-05','https://www.crustaceancompassion.org/single-post/from-a-boiling-alive-ban-to-a-push-for-full-legal-protection-2026-is-the-year-for-decapod-welfare','From a boiling alive ban, to a push for full legal protection: 2026 is the year for decapod welfare — Crustacean Compassion',NULL,NULL,NULL,NULL,NULL,NULL,'reported','[]','curated','Source read via WebFetch (curl hit a bot check). Government strategy document itself not fetched. The Animal Law Foundation (AAA blog, 2026-02-11) describes the government as accepting the practice is illegal under existing law.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('nyc-bar-endorses-octopus-act-2026','announcement','NYC Bar Animal Law Committee endorses federal OCTOPUS Act','The New York City Bar Association''s Animal Law Committee released a report endorsing the federal OCTOPUS Act of 2025, which would prohibit commercial octopus aquaculture and restrict trade in farmed octopus in the US; the report cites ALI materials.','2026-01','2026-01-28','2026-11-05','https://www.ali.fish/blog/nyc-bar-octopusact-endorsement','Legal Voices Back Preventive Approach to Octopus Farming: NYC Bar Association Endorses Federal OCTOPUS Act — Aquatic Life Institute',NULL,NULL,NULL,NULL,NULL,NULL,'reported','[]','curated','The OCTOPUS Act is a pending federal bill; its legislative status was not checked. NYC Bar report itself not fetched.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('mexico-octopus-farming-ban-bill-2026','legal_development','Bill to ban cephalopod farming introduced in Mexico''s Senate','Senator Maki Esther Ortiz Domínguez introduced a reform of Mexico''s General Law of Sustainable Fisheries and Aquaculture to prohibit commercial aquaculture of any cephalopod species, led by Fundación Veg with support from ALI and the Aquatic Animal Alliance.','2026-02','2026-03-12','2026-11-05','https://aquaticanimalalliance.org/blog/behind-mexicos-octopus-farming-ban-bill','Four Years of Evidence-Based Advocacy Behind Mexico''s Octopus Farming Ban Bill — Aquatic Animal Alliance',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Bill introduced only. Web search snippets gave 25 Feb 2026 as the introduction date; not confirmed on the fetched page.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('kenya-national-fish-welfare-sop-2026','legal_development','Kenya launches national fish welfare SOP for aquaculture','At the 11th Our Ocean Conference in Mombasa, Kenya''s government launched the National Manual Standard Operating Procedure for Fish Welfare in Aquaculture (FW-MSOP), described as the first such national framework in Africa; OHDI''s AFIWEL programme supported its development.','2026-06-17','2026-07-07','2026-11-05','https://aquaticanimalalliance.org/blog/one-health-and-development-initiative-fw-msop','From Vision to National Policy: Kenya Launches Africa''s First National Fish Welfare Manual Standard Operating Procedure (FW-MSOP) — Aquatic Animal Alliance',NULL,NULL,NULL,NULL,NULL,NULL,'reported','[]','curated','Source is a guest post by OHDI on the AAA blog; Kenyan government documents not fetched.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('argentina-goldfish-sentience-ruling-2026','legal_development','Buenos Aires court recognises two goldfish as sentient subjects of rights','A Buenos Aires criminal court approved a pretrial probation agreement recognising two goldfish kept in a sushi restaurant tank as sentient beings and subjects of rights rather than property, in a case brought by Jaulas Vacías under Law 14,346.','2026-07-14','2026-08-25','2026-11-05','https://aquaticanimalalliance.org/blog/animal-interseccional-goldfish-sentience','Sentient: An Argentine Court Recognizes Two Goldfish as Subjects of Rights — Aquatic Animal Alliance',NULL,NULL,NULL,NULL,NULL,NULL,'reported','[]','curated','Guest post by Animal Interseccional; court documents not fetched. Concerns ornamental (not food) fish.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('efa-aquatic-slaughter-white-paper-2026','report_published','Eurogroup white paper: ''Aquatic animal slaughter: time to make the rules''','Eurogroup for Animals published a white paper examining slaughter practices in EU aquaculture and wild-capture fisheries and arguing for mandatory EU-level standards, noting over 130 billion aquatic animals are caught by EU fleets each year.','2026-07-15','2026-07-15','2026-11-05','https://www.eurogroupforanimals.org/library/aquatic-animal-slaughter-time-make-rules','Aquatic animal slaughter: time to make the rules — Eurogroup for Animals',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Related Eurogroup publications listed on the page: factsheet on RAS and slaughter (2026-06-04) and policy briefing on fish welfare indicators (2026-04-28).','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('fwi-proposed-international-expansion-2026','plan_announced','Fish Welfare Initiative scopes expansion beyond India and China','Fish Welfare Initiative said it is seriously considering expanding operations to another country for the first time since 2022, in line with a vision of running cost-effective programmes in multiple lower- and middle-income countries, and began scoping work.','2026-09-04','2026-09-04','2026-11-05','https://www.fishwelfareinitiative.org/post/intl-expansion','Our Proposed International Expansion — Fish Welfare Initiative',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated',NULL,'2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('asc-responsible-shrimp-slaughter-project-2026','project_active','ASC launches Responsible Shrimp Slaughter Project','The Aquaculture Stewardship Council launched an applied research project, supported by Coefficient Giving, to consolidate evidence, run research and field trials, and develop validated parameters and practical tools for stunning and slaughter of farmed shrimp.','2026-09-28','2026-09-28','2026-11-05','https://asc-aqua.org/news/shrimp-welfare-project/','ASC launches project to bridge science-to-practice gap in shrimp welfare',NULL,NULL,'coefficient-giving','aquaculture-stewardship-council',NULL,NULL,'confirmed','[]','curated','Grant amount not stated on the source page. Builds on a proposed Responsible Shrimp Slaughter Coalition that was never formally established.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('icaw-french-supermarket-shrimp-ranking-2026','report_published','ICAW ranks French supermarkets on shrimp welfare commitments','The International Council for Animal Welfare published ''Souffrance en rayon'', ranking 11 French retailers on commitments on eyestalk ablation and stunning before slaughter; four had commitments on both, four on ablation only and three on neither.','2026-10-20','2026-10-20','2026-11-05','https://animalwelfareobservatory.org/actualidad/noticias/icaw-langostinos.html','ICAW publishes the first ranking of French supermarkets on shrimp welfare — Animal Welfare Observatory',NULL,NULL,NULL,NULL,NULL,NULL,'reported','[]','curated','Reported on Animal Welfare Observatory''s site; ICAW (not an entity here) and its report were not fetched directly. Data as of 1 Oct 2026.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('eu-vision-2040-aquatic-welfare-2026','plan_announced','EU Vision for Fisheries and Aquaculture 2040 commits to farmed aquatic animal welfare framework','The European Commission''s Vision for Fisheries and Aquaculture towards 2040 includes a commitment to further develop the EU framework for welfare of farmed aquatic animals at all production stages; Eurogroup notes no timeline or explicit commitment to binding legislation.','2026-10','2026-10-21','2026-11-05','https://www.eurogroupforanimals.org/news/eu-vision-2040-step-towards-protection-aquatic-animals','EU Vision 2040: a step towards protection for aquatic animals — Eurogroup for Animals',NULL,NULL,NULL,NULL,NULL,NULL,'reported','[]','curated','Exact adoption date of the Commission''s Vision not stated on the source page; event_date approximated from source date. Commission document not fetched.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('fwi-nellore-data-retraction-2026','announcement','FWI retracts two years of farm-programme data from Nellore site','Fish Welfare Initiative reported detecting data fabrication at its smaller Nellore operating region and retracted all data and impact from that region for the previous two years; it said it is considering whether to continue operations there.','2026-10-21','2026-10-21','2026-11-05','https://www.fishwelfareinitiative.org/post/data-issues','Data Issues and Retraction in Our Farm Program — Fish Welfare Initiative',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated',NULL,'2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('soil-association-withdraws-organic-salmon-standards-2026-11','announcement','Soil Association to withdraw from setting organic salmon standards','After an extensive review, the Soil Association said it will stop setting standards for organic farmed salmon, citing a lack of evidence that its standards delivered good enough outcomes, high mortality and difficulty assessing fish welfare. Existing certification contracts will be honoured.','2026-11',NULL,'2026-11-19','https://www.soilassociation.org/our-standards/standards-innovation-our-work/uk-organic-salmon-standards/','UK organic salmon standards | Soil Association',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','The Soil Association page gives no date; OneKind''s blog on the decision is dated 2026-11-17 and trade press (seen in search results, not fetched) reported it in early November 2026. Organic salmon standards in the organic regulations continue; a withdrawal timetable is to be agreed with the sector.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('onekind-response-soil-association-salmon-2026-11','announcement','OneKind responds to Soil Association''s withdrawal from organic salmon','OneKind''s policy director welcomed the Soil Association''s decision to withdraw organic certification of farmed salmon, saying its review found serious animal welfare concerns and no evidence they could be addressed soon. OneKind says it raised the issue a decade earlier.','2026-11-17','2026-11-17','2026-11-19','https://www.onekind.org/blog/latest-blow-to-destructive-salmon-farming-industry-18-11-26','Latest blow to destructive salmon farming industry',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Blog post published 17 November 2026 and updated 18 November 2026.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('eurcaw-aqua-rainbow-trout-roadshow-brescia-2026-11','announcement','EURCAW-Aqua holds national roadshow on rainbow trout welfare in Italy','EURCAW-Aqua reported holding its National Roadshow on Rainbow Trout Welfare in Brescia, Italy, on 5-6 November 2026.','2026-11-05',NULL,'2026-11-19','https://www.eurcaw-aqua.eu/','EURCAW Aqua - Home',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','News item listed on the EURCAW-Aqua homepage in mid/late November 2026; exact posting date not confirmed.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('animal-outlook-cooke-return-investigation-2026-05','report_published','Animal Outlook publishes return investigation of Cooke Aquaculture salmon hatchery','Animal Outlook released a second undercover investigation of Cooke Aquaculture''s salmon hatchery in Maine, first investigated in 2019. It alleges fish were thrown and clubbed without being killed immediately and that contaminated feed was used. No enforcement outcome is reported.','2026-05-15','2026-05-15','2026-11-19','https://animaloutlook.org/animal-outlooks-return-investigation-of-cooke-aquaculture/','Animal Outlook''s return investigation of Cooke Aquaculture',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Findings are Animal Outlook''s allegations as described in its own post; the company''s response was not reviewed.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('apon-fish-welfare-implementation-pilot-survey-2026-05','report_published','APON publishes Fish Welfare Implementation Pilot survey of catfish farms in Edo State','The Animal Protection Organisation of Nigeria published the final report of its Fish Welfare Implementation Pilot survey, which assessed catfish welfare practices, farm management and operational challenges on ten farms in Olluedede village, Auchi, Edo State.','2026-05-01','2026-05-01','2026-11-19','https://aponwelfare.org/fish-welfare-survey-in-nigeria/','Fish Welfare Survey in Nigeria',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Survey dates and funders are not stated in the post; five cooperative/former NEWMAP farms and five privately owned farms were surveyed.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('afwn-third-funding-call-2026-09','announcement','Asian Fish Welfare Network launches third research funding call','The University of Stirling-led Asian Fish Welfare Network launched its third competitive call for collaborative fish welfare research projects with a webinar on 3 September 2026. The network covers Thailand, Vietnam and Indonesia.','2026-09-03',NULL,'2026-11-19','https://susaquastirling.net/asiafishwelfare','Asian Fish Welfare Network',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Recorded as an announcement rather than an open call because the deadline, grant sizes and whether the call is still open were not confirmed on the page fetched. The network itself is funded by Coefficient Giving.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('afwn-indonesia-workshop-research-call-2026','announcement','Asian Fish Welfare Network holds first Indonesian workshop and opens Indonesia research call','The Asian Fish Welfare Network held a workshop in Surabaya in April 2026 and launched a call for research proposals in Indonesia on fish welfare narratives, farmer perceptions and welfare improvements in local aquaculture, according to The Fish Site.','2026-04','2026-06-22','2026-11-19','https://thefishsite.com/articles/indonesia-begins-exploring-fish-welfare-through-new-research-initiative','Indonesia begins exploring fish welfare through new research initiative',NULL,NULL,NULL,NULL,NULL,NULL,'reported','[]','curated','Reported by trade press; partners named include Universitas Udayana, Universitas Gadjah Mada and Senang Eco.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('ida-nueva-pescanova-octopus-farm-abandoned-2026','campaign_outcome','In Defense of Animals reports plans for Nueva Pescanova octopus farm abandoned','In Defense of Animals reported that Nueva Pescanova''s plans for a commercial octopus farm at the Port of Las Palmas, Gran Canaria, have officially been abandoned. The group had campaigned for Spanish authorities to reject the proposal.','2026','2026-07-31','2026-11-19','https://www.idausa.org/campaign/wild-animals-and-habitats/latest-news/victory-plans-for-the-worlds-first-octopus-farm-are-scrapped/','Victory: Plans for the World''s First Octopus Farm Are Scrapped',NULL,NULL,NULL,NULL,NULL,NULL,'reported','[]','curated','The post gives no date or primary source for the abandonment; not checked against a statement from Nueva Pescanova or Canary Islands authorities. Many organisations campaigned against the project.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('world-day-end-of-fishing-10th-edition-2026-03','announcement','10th World Day for the End of Fishing and Fish Farming','The 10th edition of the World Day for the End of Fishing and Fish Farming took place on 28 March 2026. The organisers report 183 actions by 202 organisations in 32 countries.','2026-03-28',NULL,'2026-11-19','https://end-of-fishing.org/en/','End of fishing - World day for the end of fishing and fish farming',NULL,NULL,NULL,NULL,NULL,NULL,'reported','[]','curated','Participation figures are the organisers'' own. The next editions are listed for 27 March 2027 and 25 March 2028.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('norwegian-fish-health-report-2025-published','report_published','Norwegian Veterinary Institute publishes Fish Health Report 2025','The Fish Health Report 2025 finds salmon mortality in Norwegian aquaculture slightly lower than in 2024 and 2023 and farmed cod mortality higher, with injuries after delousing and infectious diseases named as the main causes of death for salmon in sea cages.','2026',NULL,'2026-11-19','https://www.vetinst.no/rapporter-og-publikasjoner/rapporter/2026/fish-health-report-2025','Fish Health Report 2025 - Norwegian Veterinary Institute',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Exact publication date not stated on the page (URL path: 2026). Includes a new chapter on climate change and fish health.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('safe-nz-calls-halt-fish-farm-expansion-2026-10','announcement','SAFE calls for halt to fish farm expansion in New Zealand','SAFE called for an immediate halt to proposed fish farm expansions and new developments in New Zealand, criticising fast-track approvals and citing repeated mass mortality events on Chinook salmon farms.','2026-10-23','2026-10-23','2026-11-19','https://safe.org.nz/news/fish-farms-the-underwater-factory-farms-hidden-beneath-the-surface/','Fish farms: the underwater factory farms hidden beneath the surface',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated',NULL,'2026-11-20T00:05:21.099Z');
