INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('sharegift-crustacean-compassion-2026','grant_awarded','ShareGift: Crustacean Compassion unrestricted grant','Unrestricted one-off grant of £17,500 from ShareGift to Crustacean Compassion (ShareGift distribution ID 62).','2026-08-20',NULL,'2026-11-05','https://grantnav.threesixtygiving.org/grant/360G-ShareGift-CHD012578','360Giving grant 360G-ShareGift-CHD012578',17500,'GBP','sharegift','crustacean-compassion',NULL,NULL,'confirmed','[]','curated','Read via 360Giving Datastore API (licence CC BY 4.0). Unrestricted, so not aquatic-specific in purpose; recipient is an aquatic-focused charity.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('bbsrc-university-of-stirling-electric-aeration-salmon-welfare','grant_awarded','BBSRC: electric-powered aeration for improved fish welfare in salmon aquaculture','UKRI-BBSRC award of £256,879 (BB/Z515255/1), led by the University of Stirling with partners including Bakkafrost, for on-demand electric-powered aeration to improve fish welfare in salmon aquaculture.','2024-07',NULL,'2026-11-05','https://gtr.ukri.org/find-research-and-innovation/project/8d91e5bd-2a56-483e-9f75-6210a34a7ff2','UKRI Gateway to Research: BB/Z515255/1',256879,'GBP','bbsrc','university-of-stirling',NULL,NULL,'confirmed','[]','curated','Read via GtR API. event_date is the fund start date (2024-07-01 UK time; fund end 2026-09-30); GtR does not give an award date. Welfare-science R&D rather than advocacy.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('tiny-beam-fund-fai-2023-aquatic-life-institute','grant_awarded','Tiny Beam Fund: Aquatic Life Institute (2023 Fueling Advocates Initiative)','Tiny Beam Fund 2023 Fueling Advocates Initiative grant to Aquatic Life Institute to develop templates to collect data from aquaculture associations, part of research documenting best fish and shrimp welfare practices.','2023',NULL,'2026-11-05','https://tinybeamfund.org/2023-FAI-Grantees','2023 FAI Grantees - Tiny Beam Fund',NULL,NULL,'tiny-beam-fund','aquatic-life-institute',NULL,NULL,'confirmed','[]','curated','Amount not disclosed on the page. The programme''s grants are stated as $6,000-$24,000 each (Grants Program page).','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-ea-animal-welfare-fund-rolling','open_call','EA Animal Welfare Fund: rolling grant applications','Rolling: EA Funds says it is ''always open to applications''; grants range $1,000-$500,000 for people, projects, non-profits and institutions. AWF priorities include aquatic animal welfare and humane shrimp slaughter.','2026-11-05',NULL,'2026-11-05','https://funds.effectivealtruism.org/apply-for-funding','Get funding for your high-impact project | Effective Altruism Funds',NULL,NULL,'ea-animal-welfare-fund',NULL,NULL,NULL,'confirmed','[]','curated','Confirmed open on 2026-11-05 (event_date = date verified). Strategy goals from https://funds.effectivealtruism.org/funds/animal-welfare.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-fish-welfare-initiative-india-2026','open_call','Fish Welfare Initiative: open call for new ideas for farmed fish welfare in India','Open until 18 Nov 2026 (18:00 IST): FWI funds field interventions, technologies or actionable research for Indian aquaculture; standard grants up to INR 10,00,000 (~USD 10k), exceptional up to INR 50,00,000 (~USD 50k).','2026-10-06','2026-10-06','2026-11-05','https://www.fishwelfareinitiative.org/post/rfp-india','Open Call: Funding New Ideas to Improve the Welfare of Farmed Fishes in India',NULL,NULL,'fish-welfare-initiative',NULL,'2026-11-18',NULL,'confirmed','[]','curated','Open to companies, non-profits, individuals/groups. Publication date from FWI blog RSS feed.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-science-for-animal-welfare-centenary-research-award','open_call','Science for Animal Welfare: £250,000 Centenary Research Award','Open: concept notes due 31 Dec 2026, invited full proposals due 15 May 2027, for one 2-4 year project (up to £250,000) on a major animal welfare challenge or fundamental question. Applicants worldwide.','2026-09-03','2026-09-03','2026-11-05','https://scienceforanimalwelfare.org/award/centenary-research-award/','Centenary Research Award - Science for Animal Welfare',NULL,NULL,'science-for-animal-welfare',NULL,'2026-12-31',NULL,'confirmed','[]','curated','Science for Animal Welfare is formerly UFAW. Not aquatic-specific. Page datePublished 2026-09-03, modified 2026-10-23.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-ace-movement-grants-round-12','open_call','ACE Movement Grants round 12','Closed 18 Oct 2026 (recurring grant rounds). Round 12 sought organisations under 3 years old, under $500k budget, incubators, or MEL requests; priority groups included aquatic animals in aquaculture or fishing.','2026-09-24','2026-09-24','2026-11-05','https://animalcharityevaluators.org/movement-grants/apply-for-funding/','Apply for Movement Grants Funding - Animal Charity Evaluators',NULL,NULL,'animal-charity-evaluators',NULL,'2026-10-18',NULL,'uncertain','[]','curated','Not currently open as of 2026-11-05 (deadline passed); watch for round 13. Call blog post: https://animalcharityevaluators.org/blog/call-for-movement-grants-applications/ (datePublished 2026-09-24).','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-strategic-animal-funding-circle-2026-h2','open_call','Strategic Animal Funding Circle: grant round','Closed 1 Nov 2026 (two collaborative grant rounds per year). Funds animal welfare/protection interventions by registered non-profits; preference for orgs under 4 years old or under $500k budget. Decisions expected early Dec.','2026',NULL,'2026-11-05','https://www.animalfundingcircle.com/','HOME | Strategic Animal Funding Circle',NULL,NULL,'strategic-animal-funding-circle',NULL,'2026-11-01',NULL,'uncertain','[]','curated','Not currently open as of 2026-11-05; recurring (twice yearly).','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-coefficient-giving-humane-fish-slaughter-rfp-2026','open_call','Coefficient Giving RFP: humane fish slaughter research/prototypes (~$7M)','Closed 1 Jul 2026: Coefficient Giving RFP allocating approx. $7 million to R&D that substantially improves fish welfare at capture and slaughter (pre-death insensibility for farmed and wild-caught fish).','2026-02','2026-02-10','2026-11-05','https://weareaquaculture.com/news/sustainability/us-fund-commits-7m-for-improving-fish-welfare-at-capture-and-slaughter','U.S. fund commits $7M for improving fish welfare at capture and slaughter - WeAreAquaculture',NULL,NULL,'coefficient-giving',NULL,'2026-07-01',NULL,'reported','[]','curated','Primary coefficientgiving.org page blocked (HTTP 403) from server. Hive Highlights (2026-06-10) describes 1 July as the letter-of-intent deadline. Not open as of 2026-11-05; watch for follow-on rounds.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-coefficient-giving-alt-protein-rd-rfp-2026','open_call','Coefficient Giving RFP: alternative protein research and development','Closed 10 Aug 2026: Coefficient Giving RFP for alternative protein R&D, reported at up to $10 million.','2026','2026-06-10','2026-11-05','https://joinhive.substack.com/i/201292923/jobs','Hive Highlights: Coefficient Giving funding, Stray Dog Institute movement survey, Rethink Priorities cause-neutral fund',NULL,NULL,'coefficient-giving',NULL,'2026-08-10',NULL,'reported','[]','curated','Secondary source only; primary page blocked (403). Not open as of 2026-11-05.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-tiny-beam-fund-fueling-advocates-2026','open_call','Tiny Beam Fund: Fueling Advocates Initiative grants (annual)','Closed for 2026 (concept notes accepted 8-30 June). Annual call; $6,000-$24,000 grants for NGOs/CSOs tackling drivers and impacts of industrial animal agriculture in low- and middle-income countries.','2026-06-08',NULL,'2026-11-05','https://tinybeamfund.org/Grants-Program','Grants Program - Tiny Beam Fund',NULL,NULL,'tiny-beam-fund',NULL,'2026-06-30',NULL,'uncertain','[]','curated','Recurring annually; page still says ''The 2026 Call for Applications is Open'' although the stated window has passed.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-tiny-beam-fund-fellowship-awards-2026','open_call','Tiny Beam Fund: Fellowship Awards (Burning Questions)','Closed for 2026 (applications 24 Mar-22 Apr 2026). Nine-month fellowships for PhD holders (US$60,000) or near-completion PhD students (US$45,000) to research ''Burning Questions'' on industrial animal agriculture in LMICs.','2026-03-24',NULL,'2026-11-05','https://tinybeamfund.org/Fellowship-Awards','Fellowship Awards - Tiny Beam Fund',NULL,NULL,'tiny-beam-fund',NULL,'2026-04-22',NULL,'uncertain','[]','curated','Recurring; not open as of 2026-11-05. Research Planning Grants are invitation-only as of 2026.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-ambitious-impact-incubation-feb-2027-factory-farming','open_call','Ambitious Impact incubation programme: February 2027 ''Transforming factory farming''','Closed: applications for AIM''s February 2027 ''Transforming factory farming'' cohort have closed. The fully funded two-month programme provides a charity idea, co-founder matching, training and seed-funding access.','2026',NULL,'2026-11-05','https://www.ambitiousimpact.com/start-a-charity','Start a charity — Ambitious Impact',NULL,NULL,'ambitious-impact',NULL,'2026-09-13','closed','uncertain','[]','curated','Next listed cohort (August 2027) is health systems/livelihoods, not animals; applications open January 2027. AIM was formerly Charity Entrepreneurship. | Also reported at https://joinhive.substack.com/p/august-2026','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-horizon-europe-cl6-2027-02-farm2fork-06','open_call','Horizon Europe HORIZON-CL6-2027-02-FARM2FORK-06: small-scale aquatic food production','Forthcoming EU call ''Unleashing the potential of sustainable small-scale aquatic food production and recreational fisheries''; planned opening 20 Apr 2027, deadline 23 Sep 2027. Text says aquatic animal welfare should be considered where relevant.','2027-04-20',NULL,'2026-11-05','https://ec.europa.eu/info/funding-tenders/opportunities/data/topicDetails/horizon-cl6-2027-02-farm2fork-06.json','EU Funding & Tenders topic details: HORIZON-CL6-2027-02-FARM2FORK-06',NULL,NULL,'european-commission',NULL,'2027-09-23','forthcoming','uncertain','[]','curated','Status ''forthcoming'' in the EU Funding & Tenders search API. Human-readable page: https://ec.europa.eu/info/funding-tenders/opportunities/portal/screen/opportunities/topic-details/horizon-cl6-2027-02-farm2fork-06 . Welfare is a secondary consideration, not the call''s focus. No open EU call with animal welfare as primary topic was found.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-movement-infrastructure-lab-rfp-2026-primary','open_call','Movement Infrastructure Lab: request for proposals (round one)','Open until 30 Nov 2026: pilot call run in partnership with Kickstarting for Good, offering USD 10k development grants from a USD 200k pool for projects that strengthen the farmed animal and food system movements. Selected projects also get founder coaching.','2026-10-17','2026-10-17','2026-11-19','https://forum-bots.effectivealtruism.org/posts/CD2B4E52EhGtdsZgi/why-i-m-launching-a-movement-infrastructure-lab-a-request','Why I’m launching a Movement Infrastructure Lab: a request for proposals — EA Forum',NULL,NULL,'kickstarting-for-good',NULL,'2026-11-30',NULL,'confirmed','[]','curated','Primary source for the existing record call-movement-infrastructure-lab-kickstarting-for-good-2026, which cited Hive only. The post says "Apply by November 30" without a year; 2026 follows from the post date. Hive Highlights of 2026-11-11 reports the pool is now USD 210,000 after Stray Dog Institute added USD 10,000. The call is coordinated by an individual with Kickstarting for Good funding and support, not by a separate organisation. Read on the EA Forum bot mirror (forum-bots.effectivealtruism.org), which serves the same post as forum.effectivealtruism.org. | Also reported at https://joinhive.substack.com/p/late-october-2026','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-blueperch-expressions-of-interest-primary','open_call','BluePerch: expressions of interest ahead of grant applications in mid-2027','BluePerch invites grantseekers to register an expression of interest; public, rolling grant applications are planned to open in mid-2027. It expects most grants to be about USD 5,000-100,000 for farmed animal advocacy projects. Registering does not affect the chance of funding.','2026-09',NULL,'2026-11-19','https://www.blueperch.org/','BluePerch · Funding for high-impact farmed animal advocacy projects',NULL,NULL,'blueperch',NULL,NULL,'forthcoming','confirmed','[]','curated','Primary source for the existing record call-blueperch-expressions-of-interest, which cited Hive only. No deadline: the expression-of-interest form is open; applications themselves are not yet open. The fund says its timelines are subject to change. Grant range and first-year budget (about USD 1.2 million in 2027) are from https://www.blueperch.org/about. event_date is the month Hive first reported the fund (issue of 2026-09-23); the site gives no launch date. | Also reported at https://joinhive.substack.com/p/late-september-2026','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-who-let-docs-out-2026-autumn-cycle','open_call','Who Let The Docs Out: 2026 autumn grant cycle','Documentary grant cycle: pre-applications opened 16 Oct 2026 and closed 13 Nov 2026; full applications from invited filmmakers are due 1 Jan 2027, with notification in early February. Grantees commit to monthly check-ins from February to April.','2026-10-16',NULL,'2026-11-19','https://www.docsout.org/funding','Grant Cycles — Who Let The Docs Out',NULL,NULL,'who-let-docs-out',NULL,'2026-11-13',NULL,'confirmed','[]','curated','Primary source for the existing record call-who-let-the-docs-out-documentary-fund, which cited Hive only. Closed to new applicants as of 2026-11-19: the deadline given is the pre-application deadline. The page lists weekdays and dates without years for this cycle; years follow from the cycle name and the weekdays. Grant sizes were not found on the page (Hive reported up to USD 50,000 per production stage). | Also reported at https://joinhive.substack.com/p/late-october-2026','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-who-let-docs-out-2027-spring-cycle','open_call','Who Let The Docs Out: 2027 spring grant cycle','Forthcoming documentary grant cycle: pre-applications open in mid to late February 2027, pre-application deadline 19 March 2027, full applications due 30 April 2027, notification 28 May 2027.','2027-02',NULL,'2026-11-19','https://www.docsout.org/funding','Grant Cycles — Who Let The Docs Out',NULL,NULL,'who-let-docs-out',NULL,'2027-03-19',NULL,'confirmed','[]','curated','Not yet open as of 2026-11-19. The deadline given is the pre-application deadline. The same page lists a 2027 summer cycle (pre-application deadline 16 July 2027). Funds four stages of production; grant sizes not found on the page.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-science-for-animal-welfare-small-research-grants-2027-04','open_call','Science for Animal Welfare: Small Research Grants','Open: grants of up to £5,000 for research that improves understanding of the welfare of farmed, companion, laboratory, captive wild or human-affected free-living animals. Applicants from anywhere in the world; closing date shown 1 April 2027.','2026',NULL,'2026-11-19','https://scienceforanimalwelfare.org/award/small-research-grants/','Small Research Grants - Science for Animal Welfare',NULL,NULL,'science-for-animal-welfare',NULL,'2027-04-01',NULL,'confirmed','[]','curated','Page last modified 2026-10-23; the opening date is not stated, so event_date is the year only. Research on farmed animals in transport, at markets or at slaughter is referred to the Humane Slaughter Association. Not aquatic-specific.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-science-for-animal-welfare-large-research-grants-2027-04','open_call','Science for Animal Welfare: Large Research Grants','Open: grants of over £5,000 for animal welfare research projects, with two deadlines a year (1 April and 1 October); the next closing date shown is 1 April 2027. Applicants from anywhere in the world with expertise in animal welfare science.','2026',NULL,'2026-11-19','https://scienceforanimalwelfare.org/award/large-research-grants/','Large Research Grants - Science for Animal Welfare',NULL,NULL,'science-for-animal-welfare',NULL,'2027-04-01',NULL,'confirmed','[]','curated','Page last modified 2026-10-23; the opening date is not stated, so event_date is the year only. No upper limit was read on the page. Not aquatic-specific.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-culture-and-animals-2027','open_call','Culture & Animals Foundation: 2027 grant cycle','Forthcoming: proposals accepted from 4 to 17 January 2027, or until 200 applications are received. Grants of up to USD 5,000 to scholars and artists in any country for research, creative work or performance on human-animal relationships and animal rights.','2027-01-04',NULL,'2026-11-19','https://cultureandanimals.org/grants/grant_faqs/','Grant Essential Information – Culture & Animals Foundation',NULL,NULL,'culture-and-animals',NULL,'2027-01-17',NULL,'confirmed','[]','curated','Not yet open as of 2026-11-19. The window closes early if the cap of 200 applications is reached. Applicants are notified by mid-March. Grants go to individuals, not institutions. Its feed carried "Get Ready for the 2027 Grant Application Period!" on 2026-11-05.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-fhf-low-oxygen-open-cages-2026','open_call','FHF: risk-reducing measures at low oxygen levels in open sea cages','Open until 4 Dec 2026 (14:00): FHF offers up to NOK 10 million for research on when adding oxygen to open salmon cages is appropriate or needed to protect fish welfare and production during periods of low oxygen, including guideline thresholds.','2026-09-24','2026-09-24','2026-11-19','https://www.fhf.no/utlysninger/utlysninger/risikoreduserende-tiltak-ved-lave-oksygennivaa-i-aapne-merder/','Risikoreduserende tiltak ved lave oksygennivå i åpne merder – FHF',NULL,NULL,'fhf-norwegian-seafood-research-fund',NULL,'2026-12-04',NULL,'confirmed','[]','curated','Source is in Norwegian; status shown as "Pågående" (ongoing). "Up to NOK 10 million" is the ceiling for the call, so the amount field is left empty. Industry-funded research call for Norwegian aquaculture, not an advocacy grant.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-eupahw-shaping-future-of-animal-health-and-welfare-2026','open_call','EUPAHW joint call: Shaping the future of animal health and welfare','Closed 30 March 2026 (pre-proposals): transnational call of the European Partnership on Animal Health and Welfare with national funders for research on livestock and aquaculture systems. UK teams were funded by BBSRC or Defra, up to £730,000 full economic cost per project over 36 months.','2026',NULL,'2026-11-19','https://www.ukri.org/opportunity/shaping-the-future-of-animal-health-and-welfare/','Shaping the future of animal health and welfare – UKRI',NULL,NULL,'european-partnership-on-animal-health-and-welfare',NULL,'2026-03-30',NULL,'confirmed','[]','curated','Closed. Read from UKRI''s page for UK applicants; the partnership''s own call pages are script-rendered and could not be read. Consortia needed a UK team (for UK funding) and at least two partners from two other co-funding countries; full proposals were by invitation. The £730,000 limit is the UK component only (BBSRC funds 80%). Publication date of the call not found, so event_date is the year only.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('aquatic-animal-funding-circle-2025-round','grant_awarded','Aquatic Animal Funding Circle: 2025 round','After the circle''s 2025 cycle of co-learning, a request for proposals and joint evaluation, circle members and aligned funders granted over USD 1.5 million to ten organisations working on farmed aquatic animal welfare.','2025','2025-08-14','2026-11-19','https://forum-bots.effectivealtruism.org/posts/dBwoeth8y9dQjTeSw/aquatic-animal-funding-recommendations','Aquatic Animal Funding Recommendations — EA Forum',NULL,NULL,'aquatic-animal-funding-circle',NULL,NULL,NULL,'confirmed','[]','curated','Round total as worded by the source ("over $1.5 million"); the exact total and per-grantee amounts are not published, so the amount field is left empty. Not every funder funded every organisation, and each funder decided independently. Published under the host''s former name, Farmed Animal Funders. Crustacean Compassion is among the recommended organisations; the full list was not transcribed. Read on the EA Forum bot mirror.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-coefficient-giving-incubators-rfp-2026','open_call','Coefficient Giving: request for proposals for impact-oriented incubators','Reported open: request for proposals for impact-oriented incubators and accelerators, existing or new, with grants expected to last two to three years. Apply by 18 December (2026).','2026-11','2026-11-11','2026-11-19','https://joinhive.substack.com/p/early-november-2026','Hive Highlights, early November 2026',NULL,NULL,'coefficient-giving',NULL,'2026-12-18',NULL,'uncertain','[]','curated','Secondary source only (Hive newsletter, read via its RSS feed). The primary page (coefficientgiving.org/funds/effective-giving-and-careers/request-for-proposals-incubation) returns HTTP 403 to server-side requests. Not animal-specific: the link points to Coefficient Giving''s effective giving and careers fund; Hive lists it for animal advocacy incubators. Year of the deadline inferred from the issue date.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-animal-legal-defense-fund-small-research-grants-2026','open_call','Animal Legal Defense Fund: small grants for applied research','Reported open: small grants of up to USD 5,000 for applied, advocacy-oriented research combining legal, scientific and policy perspectives, for US-based researchers affiliated with a higher education institution. Apply by 15 December (2026).','2026-11','2026-11-11','2026-11-19','https://joinhive.substack.com/p/early-november-2026','Hive Highlights, early November 2026',NULL,NULL,'animal-legal-defense-fund',NULL,'2026-12-15',NULL,'uncertain','[]','curated','Secondary source only (Hive newsletter, read via its RSS feed); Hive links to an application form, and no page on aldf.org describing the programme was found. Year of the deadline inferred from the issue date. Not aquatic-specific.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('awf-animal-law-italia-2024-q3-aquatic-animal-welfare','grant_awarded','EA Animal Welfare Fund: Animal Law Italia (2024 Q3)','EA Animal Welfare Fund grant to Animal Law Italia (2024 Q3 round): a 1-year project for advancing aquatic animal welfare in Italy and Europe through advocacy and corporate outreach.','2024',NULL,'2026-11-19','https://funds.effectivealtruism.org/grants','Grants Database | Effective Altruism Funds',81000,'USD','ea-animal-welfare-fund','animal-law-italia',NULL,NULL,'confirmed','[]','curated','From the EA Funds grants database CSV (https://funds.effectivealtruism.org/api/grants); record id recmwRqqfTRQU9PvG, round ''2024 Q3''. The database gives a quarter, not an exact date. Currency is not stated per record; EA Funds presents grant sizes in US dollars.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('awf-animal-law-italia-2022-q3-decapod-crustaceans','grant_awarded','EA Animal Welfare Fund: Animal Law Italia (2022 Q3)','EA Animal Welfare Fund grant to Animal Law Italia (2022 Q3 round): a 2-year plan to advance the legal protection of decapod crustaceans in Italy.','2022',NULL,'2026-11-19','https://funds.effectivealtruism.org/grants','Grants Database | Effective Altruism Funds',159000,'USD','ea-animal-welfare-fund','animal-law-italia',NULL,NULL,'confirmed','[]','curated','From the EA Funds grants database CSV (https://funds.effectivealtruism.org/api/grants); record id recvga70pxRIDKuGn, round ''2022 Q3''. The database gives a quarter, not an exact date. Currency is not stated per record; EA Funds presents grant sizes in US dollars. Grantee is written ''Animal Law Italia (ALI)'' in this record.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('hsus-hsi-rename-humane-world-for-animals-2025','announcement','HSUS and HSI rename to Humane World for Animals','The Humane Society of the United States and Humane Society International adopted a single new name, Humane World for Animals.','2025-02',NULL,'2026-11-05','https://en.wikipedia.org/wiki/Humane_World_for_Animals','Humane World for Animals - Wikipedia',NULL,NULL,NULL,NULL,NULL,NULL,'reported','[]','curated','Wikipedia cites a WJLA report dated 2025-02-13; the organisation''s homepage confirms the ''formerly HSUS and HSI'' wording but no date.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('lse-coller-centre-animal-sentience-announced-2025','plan_announced','LSE announces Jeremy Coller Centre for Animal Sentience','LSE announced a new research centre on animal sentience, funded by a £4m multi-year commitment from the Jeremy Coller Foundation, to launch in autumn 2025.','2025-03-25','2025-03-25','2026-11-05','https://www.lse.ac.uk/news/latest-news-from-lse/c-march/lse-centre-animal-sentience','LSE centre animal sentience',4000000,'GBP',NULL,'jeremy-coller-centre-for-animal-sentience',NULL,NULL,'confirmed','[]','curated','Funder (Jeremy Coller Foundation) is not a map entity.','2026-11-20T00:05:21.099Z');
