INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('ace-movement-grants-round-11-2026','grant_awarded','ACE awards latest Movement Grants','Animal Charity Evaluators awarded $1,054,939 to 21 projects and organisations after assessing 74 full applications in its latest Movement Grants round.','2026-06','2026-09-29','2026-11-05','https://animalcharityevaluators.org/blog/announcing-round-11-movement-grants/','Announcing our latest Movement Grants',1054939,'USD','animal-charity-evaluators',NULL,NULL,NULL,'confirmed','[]','curated','URL slug identifies this as round 11. Round total: the round''s per-recipient grants (ace-mg-round-11-*) are part of it. Event date is the round ACE''s past-recipients page lists (June 2026), the same as those records; the announcement was published 2026-09-29.','2026-11-20T00:05:21.099Z');
