INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('ace-influenced-giving-2025-2026','report_published','ACE reports $7.3m counterfactual influenced giving','ACE''s 2025–2026 influenced giving reports estimate $7.3 million in donations to its Recommended Charities that would not otherwise have occurred, within at least $14.7 million influenced in total.','2026-10-28','2026-10-28','2026-11-05','https://animalcharityevaluators.org/blog/announcing-latest-influenced-giving-metrics-2026/','The Second Year in a Row of Record Generosity: Announcing ACE''s 2025–2026 Influenced Giving Reports',7300000,'USD',NULL,NULL,NULL,NULL,'confirmed','[]','curated',NULL,'2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('faunalytics-brazil-voters-study-2026','report_published','Faunalytics study on farmed animal policy and Brazilian voters','Faunalytics surveyed nearly 2,000 Brazilians on which farmed animal policies voters reward or punish, to inform efforts to put farmed animals on Brazil''s political agenda.','2026-10-28','2026-10-28','2026-11-05','https://faunalytics.org/votos-pelos-animais-brazil-voters/','Votos Pelos Animais: How Farmed Animal Policy Wins Votes In Brazil',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated',NULL,'2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('dc-denver-foie-gras-ballot-bans-2026','legal_development','Washington, D.C. and Denver voters pass foie gras bans','Ballot measures banning force-feeding and sale of foie gras passed with 73% in D.C. and 66.55% in Denver in the 2026 midterms; both take effect 1 July 2027 barring legal challenges.','2026-11','2026-11-04','2026-11-05','https://sentientmedia.org/denver-and-d-c-have-voted-to-ban-foie-gras/','Denver and D.C. Have Voted to Ban Foie Gras',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Campaigns led by Pro-Animal Future (not yet a map entity). Sentient Media is the reporting source, not a party.','2026-11-20T00:05:21.099Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('eu-commission-work-programme-2027-animal-welfare-2026','legal_development','EU 2027 Work Programme omits farm animal cage proposals','The European Commission''s 2027 Work Programme did not mention promised revisions on laying hens, broiler chickens and pigs; a pig cage proposal had been planned for 2027 under the July Livestock Strategy.','2026-11-04','2026-11-04','2026-11-05','https://animallaweurope.org/commissions-new-work-programme-where-are-the-animals/','The Commission''s New Work Programme: Where Are the Animals?',NULL,NULL,NULL,NULL,NULL,NULL,'confirmed','[]','curated','Analysis by an advocacy think tank; the Commission''s stated December 2026 poultry proposal timeline was not independently checked.','2026-11-20T00:05:21.099Z');
